const MAX_REFERENCE_BYTES: usize = 8 * 1024 * 1024;
const MAX_REFERENCE_INLINE_BASE64: usize = 12 * 1024 * 1024;
const MAX_REFERENCE_WIDTH: u32 = 8192;
const MAX_REFERENCE_HEIGHT: u32 = 8192;
const MAX_REFERENCE_PIXELS: u64 = 16_777_216;
const MAX_REFERENCE_DECODE_ALLOC: u64 = 64 * 1024 * 1024;
// Candidate-bound geometry artifacts are read from CAS only through the
// metadata-first bounded API. Keep this aligned with the Geometry Worker GLB
// integrity ceiling; JSON projections/sidecars use the separate 1 MiB limit.
const MAX_GEOMETRY_ARTIFACT_BYTES: u64 = 64 * 1024 * 1024;
const MAX_DERIVED_JSON_BYTES: u64 = 1024 * 1024;
const TOPOLOGY_SNAPSHOT_POLICY: &str = "forgecad-topology-snapshot@1:evaluated-glb-triangles:position-weld-1e-6m:artifact-local-ids:faces-512:elements-1536:response-1mib:no-truncation";

// These are the product-level visible-view gates.  The earlier 0.72/0.75
// values were useful for exploratory comparison receipts, but were too weak
// to unlock downstream detail/material work.  Keep the thresholds in one
// Runtime-owned place so emitted reports and their validators cannot drift.
const VISIBLE_SILHOUETTE_IOU_MIN: f64 = 0.90;
const VISIBLE_BOUNDARY_F1_MIN: f64 = 0.90;
const VISIBLE_BBOX_EDGE_ERROR_MAX: f64 = 0.02;
const VISIBLE_CENTROID_ERROR_MAX: f64 = 0.02;
const VISIBLE_LANDMARK_COVERAGE_MIN: f64 = 0.80;
const VISIBLE_LANDMARK_NME_MAX: f64 = 0.03;
const VISIBLE_REGION_MEDIAN_IOU_MIN: f64 = 0.85;
const VISIBLE_CRITICAL_REGION_IOU_MIN: f64 = 0.85;
const VISIBLE_VIEW_THRESHOLD_REVISION: &str = "visible-view-gates@1";
const VISIBLE_VIEW_THRESHOLD_SOURCE: &str = "forgecad-runtime-visible-view-gates";
// A full 37+27 camera neighborhood is useful for offline research, but it is
// too slow for the product's single MCP request window on the fixed Worker.
// Keep the Runtime path deterministic and auditable with eight coarse probes;
// the probes are a balanced yaw/pitch/framing spread rather than an arbitrary
// prefix of the 37-row research list.
const CAMERA_FIT_RUNTIME_MAX_EVALUATIONS: usize = 8;
// The coarse camera search is intentionally low resolution, but the selected
// calibration is later bound to the 512x512 comparison/render set. Re-rank a
// small, deterministic top-k (plus the authored base camera) at the fixed
// resolution before exposing a CameraCalibrationRef. This prevents a
// low-resolution aliasing or landmark tie from becoming a durable camera
// binding while keeping the request bounded.
const CAMERA_FIT_FULL_RESOLUTION_MAX_EVALUATIONS: usize = 5;
// A Primary Form repair is one MCP action, so its nested Runtime-owned
// search stays within the same fixed 64-evaluation ceiling as the standalone
// fit. The action remains bounded and keeps continuous parameter search in
// Runtime/Workers rather than pushing it back into Codex.
const PRIMARY_FORM_REPAIR_MAX_EVALUATIONS: u64 = 64;
// A single 64-evaluation action may make a strong first camera/geometry
// incumbent but still need one local continuation around that incumbent.
// Keep the total evaluation ceiling unchanged; expose at most two Runtime
// iterations so the second round can refine the first round's camera context
// without returning a continuous search trace to Codex.
const PRIMARY_FORM_REPAIR_MAX_ITERATIONS: u64 = 2;

fn normalize_primary_form_repair_optimizer(optimizer: &mut serde_json::Map<String, Value>) {
    let requested_evaluations = optimizer
        .get("max_evaluations")
        .and_then(Value::as_u64)
        .unwrap_or(PRIMARY_FORM_REPAIR_MAX_EVALUATIONS);
    let requested_iterations = optimizer
        .get("max_iterations")
        .and_then(Value::as_u64)
        .unwrap_or(PRIMARY_FORM_REPAIR_MAX_ITERATIONS);
    optimizer.insert(
        "max_evaluations".to_owned(),
        Value::from(requested_evaluations.min(PRIMARY_FORM_REPAIR_MAX_EVALUATIONS)),
    );
    optimizer.insert(
        "max_iterations".to_owned(),
        Value::from(requested_iterations.min(PRIMARY_FORM_REPAIR_MAX_ITERATIONS)),
    );
}

#[derive(Debug, thiserror::Error)]
pub enum RuntimeError {
    #[error("{0}")]
    Store(#[from] StoreError),
    #[error("IPC error: {0}")]
    Ipc(#[from] IpcError),
    #[error("invalid runtime input: {0}")]
    InvalidInput(String),
    #[error("{0}")]
    ProcessLock(String),
}

pub struct Runtime {
    store: Store,
    capabilities: RuntimeCapabilities,
    reference_attachment_roots: Vec<PathBuf>,
    // CameraFitResult is deliberately cached only for the lifetime of this
    // Runtime process.  It is an optimisation for the immediately-following
    // CameraCalibrationRef -> SilhouetteFit handoff, never a source of truth:
    // the full result remains recomputable from the candidate/target hashes.
    camera_fit_cache: Mutex<HashMap<String, Value>>,
    // AgenticSceneObserveResult is a read-only projection, not durable user
    // data. Keep the exact projection available for bound plan/critic/action
    // follow-ups during this Runtime process so those calls consume one
    // observation instead of rebuilding several near-identical projections.
    // A Runtime restart intentionally loses this cache; bound consumers then
    // fall back to recomputation plus canonical-hash validation.
    agentic_observation_cache: Mutex<HashMap<String, Value>>,
    _process_lock: Option<process_lock::ProcessLock>,
}

/// One Runtime-derived view used by the Primary Form multi-view acceptance
/// boundary.  The camera is deliberately inferred from the typed view kind
/// and then calibrated only for framing against that view's reference mask;
/// it is not presented as an observed camera claim from the source image.
#[derive(Debug, Clone)]
struct PrimaryFormReferenceView {
    view_id: String,
    kind: String,
    reference: ReferenceEvidenceRecord,
    reference_mask: ReferenceMask,
    view_spec: Value,
    camera: Value,
}

#[derive(Debug, Clone)]
struct PrimaryFormMultiViewContext {
    reference_canvas_sha256: String,
    primary_view_id: String,
    views: Vec<PrimaryFormReferenceView>,
}

/// Durable source bindings and the Runtime-derived full-program graft used by
/// candidate-bound Modifier Apply.  The caller never supplies a GeometryProgram
/// or GLB for this path; both are reconstructed and replayed before this plan
/// can reach the ordinary exact geometry prepare transaction.
#[derive(Debug, Clone)]
struct ModifierApplyPlan {
    source_candidate: CandidateRecord,
    source_evidence: GeometryCandidateEvidenceRecord,
    source_reference_id: Option<String>,
    source_reference_sha256: Option<String>,
    source_artifact_sha256: String,
    source_artifact_readback_sha256: String,
    source_geometry_program_sha256: String,
    source_operator_catalog_sha256: String,
    source_readback_config_sha256: String,
    source_worker_build_cohort_sha256: String,
    source_part_id: String,
    source_material_zone_id: String,
    source_solid: bool,
    source_part_bindings: Vec<Value>,
    source_terminal_node_id: String,
    derived_terminal_node_id: String,
    preserved_part_ids: Vec<String>,
    modifier_apply_request_sha256: String,
    modifier_evaluation: Value,
    derived_program: Value,
}

/// Candidate-bound single-edge bevel@2 lowering.  This deliberately remains a
/// separate plan from `ModifierApplyPlan`: the legacy GeometryModifierApply
