    /// Return a deterministic QualityReport projection for a candidate. The
    /// MVP report is intentionally conservative: geometry/GLB/PBR/fixed-pass
    /// checks are reported from Runtime-owned artifacts; image similarity is
    /// only a bounded aspect-ratio comparison and is marked limited.
    pub fn quality(
        &self,
        candidate_id: &str,
        reference_id: Option<&str>,
    ) -> Result<Value, RuntimeError> {
        let candidate = self.candidate(candidate_id)?.ok_or_else(|| {
            RuntimeError::InvalidInput("NOT_FOUND: candidate not found".to_owned())
        })?;
        if let Some(evidence) = self.store.get_visual_evidence(candidate_id)? {
            let report: Value =
                serde_json::from_slice(&self.cas_read(&evidence.quality_report_object_sha256)?)
                    .map_err(|error| {
                        RuntimeError::InvalidInput(format!(
                            "QUALITY_REPORT_INVALID: visual report JSON is invalid: {error}"
                        ))
                    })?;
            if report.get("schema_version").and_then(Value::as_str) == Some("QualityReport@2") {
                if report.get("candidate_id").and_then(Value::as_str) != Some(candidate_id) {
                    return Err(RuntimeError::InvalidInput(
                        "QUALITY_REPORT_BINDING_MISMATCH: candidate hash is not bound".to_owned(),
                    ));
                }
                if let Some(reference_id) = reference_id {
                    if report.get("reference_id").and_then(Value::as_str) != Some(reference_id) {
                        return Err(RuntimeError::InvalidInput(
                            "REFERENCE_BINDING_MISMATCH: visual quality report uses another reference".to_owned(),
                        ));
                    }
                }
                validate_quality_report_v2_output(&report)?;
                return Ok(report);
            }
        }
        let quality_report_id = candidate.quality_report_id.as_deref().ok_or_else(|| {
            RuntimeError::InvalidInput(
                "QUALITY_REPORT_UNAVAILABLE: candidate has not completed Runtime quality evaluation"
                    .to_owned(),
            )
        })?;
        let mut checks = Vec::new();
        let mut artifact = Value::Null;
        if let Some(hash) = candidate
            .manifest_hash
            .as_deref()
            .filter(|hash| forgecad_contracts::is_sha256(hash))
        {
            artifact = self
                .artifact_readback(hash, candidate_id)
                .unwrap_or(Value::Null);
        }
        let artifact_valid =
            artifact.get("validator_status").and_then(Value::as_str) == Some("passed");
        let artifact_present = artifact.is_object();
        let v2_integrity = artifact.get("integrity");
        let v2_uv_tangent_passed = v2_integrity.is_some_and(|integrity| {
            [
                "uv_non_finite_count",
                "zero_area_uv_triangle_count",
                "tangent_non_finite_count",
                "tangent_orthogonality_error_count",
                "tangent_handedness_error_count",
            ]
            .iter()
            .all(|key| integrity.get(*key).and_then(Value::as_u64) == Some(0))
        });
        let legacy_uv_tangent_passed = artifact.get("uv_status").and_then(Value::as_str)
            == Some("passed")
            && artifact.get("tangent_status").and_then(Value::as_str) == Some("passed");
        checks.push(json!({"check_id":"candidate_state","status":if candidate.state == "reviewable" || candidate.state == "confirmed" {"passed"} else {"failed"},"message":format!("candidate state is {}", candidate.state)}));
        checks.push(json!({"check_id":"glb_readback","status":if artifact_valid {"passed"} else if artifact_present {"failed"} else {"not-run"},"message":"Runtime artifact readback is hash-bound"}));
        checks.push(json!({"check_id":"uv_tangent","status":if v2_integrity.is_some() && v2_uv_tangent_passed || v2_integrity.is_none() && legacy_uv_tangent_passed {"passed"} else if artifact_present {"failed"} else {"not-run"},"message":"UV and tangent attributes are read back from the GLB BIN"}));
        checks.push(json!({"check_id":"pbr_material_zones","status":if artifact.get("material_zone_ids").and_then(Value::as_array).is_some_and(|zones| !zones.is_empty()) {"passed"} else if artifact_present {"failed"} else {"not-run"},"message":"typed material zones are bound in GLB lineage"}));
        let mut compare = Value::Null;
        if let Some(reference_id) = reference_id {
            let reference = self.reference(reference_id)?.ok_or_else(|| {
                RuntimeError::InvalidInput("NOT_FOUND: reference not found".to_owned())
            })?;
            if reference.project_id != candidate.project_id {
                return Err(RuntimeError::InvalidInput(
                    "REFERENCE_SCOPE_DENIED: reference is outside the candidate project".to_owned(),
                ));
            }
            if let Some(evidence) = self.store.get_geometry_candidate_evidence(candidate_id)? {
                if evidence.reference_id.as_deref() != Some(reference_id)
                    || evidence.reference_sha256.as_deref()
                        != Some(reference.object_sha256.as_str())
                {
                    return Err(RuntimeError::InvalidInput(
                        "REFERENCE_BINDING_MISMATCH: quality comparison must use the candidate-bound reference"
                            .to_owned(),
                    ));
                }
            }
            let bytes = self.cas_read(&reference.object_sha256)?;
            let reference_ratio = reference.width as f64 / reference.height as f64;
            let model_ratio = candidate
                .manifest_hash
                .as_deref()
                .and_then(|hash| self.cas_read(hash).ok())
                .and_then(|bytes| inspect_glb(&bytes).ok())
                .map(|inspection| inspection.aspect_ratio)
                .unwrap_or(1.0);
            let aspect_error = (reference_ratio - model_ratio).abs();
            let aspect_score = (1.0 - aspect_error.min(1.0)).max(0.0);
            compare = json!({
                "reference_id":reference_id,
                "reference_sha256":reference.object_sha256,
                "reference_bytes_verified":!bytes.is_empty(),
                "reference_aspect_ratio":reference_ratio,
                "model_aspect_ratio":model_ratio,
                "aspect_score":aspect_score,
                "status":"limited",
                "limitation":"MVP does not infer pixel silhouette or semantic correspondence from one reference image; this is an aspect-ratio evidence check only."
            });
            checks.push(json!({"check_id":"reference_aspect_ratio","status":if aspect_score >= 0.55 {"passed"} else {"failed"},"message":"bounded reference/model aspect comparison","value":aspect_score,"threshold":0.55}));
        }
        let hard_gate_passed = candidate.quality_hard_gate_passed
            && checks
                .iter()
                .all(|check| check.get("status").and_then(Value::as_str) != Some("failed"));
        let mut report = json!({
            "schema_version":"QualityReport@1",
            "quality_report_id":quality_report_id,
            "candidate_id":candidate_id,
            "hard_gate_passed":hard_gate_passed,
            "checks":checks,
            "artifact":artifact,
            "reference_compare":compare,
            "canonical_sha256":""
        });
        report["canonical_sha256"] = Value::String(canonical_json_hash(&report));
        Ok(report)
    }

    /// Render a candidate against one user-authorized reference and persist a
    /// temporary RenderSet@2, mask, comparison report and QualityReport@2.
    /// No immutable version is created by this method.
    pub fn prepare_reference_comparison(
        &self,
        project_id: &str,
        request: Value,
    ) -> Result<Value, RuntimeError> {
        validate_id(project_id)?;
        let object = request.as_object().ok_or_else(|| {
            RuntimeError::InvalidInput("reference comparison request must be an object".to_owned())
        })?;
        validate_request_keys(
            object,
            &[
                "project_id",
                "candidate_id",
                "reference_id",
                "view_spec",
                "camera",
                "target_sha256",
            ],
            "reference_compare_prepare",
        )?;
        let candidate_id = required_value_id(object.get("candidate_id"), "candidate_id")?;
        let reference_id = required_value_id(object.get("reference_id"), "reference_id")?;
        let candidate = self.candidate(candidate_id)?.ok_or_else(|| {
            RuntimeError::InvalidInput("NOT_FOUND: candidate not found".to_owned())
        })?;
        if candidate.project_id != project_id {
            return Err(RuntimeError::InvalidInput(
                "PROJECT_SCOPE_DENIED: candidate is outside the target project".to_owned(),
            ));
        }
        let reference = self.reference(reference_id)?.ok_or_else(|| {
            RuntimeError::InvalidInput("NOT_FOUND: reference not found".to_owned())
        })?;
        if reference.project_id != project_id {
            return Err(RuntimeError::InvalidInput(
                "REFERENCE_SCOPE_DENIED: reference is outside the target project".to_owned(),
            ));
        }
        let view_spec = object
            .get("view_spec")
            .ok_or_else(|| RuntimeError::InvalidInput("REFERENCE_VIEW_SPEC_REQUIRED".to_owned()))?;
        validate_reference_view_spec(view_spec, &reference)?;
        let explicit_camera = object.get("camera").is_some_and(|value| !value.is_null());
        let target_sha256 = object
            .get("target_sha256")
            .map(|value| required_value_sha(Some(value), "target_sha256"))
            .transpose()?
            .map(str::to_owned);
        if let Some(target_sha256) = target_sha256.as_deref() {
            let target = self.read_silhouette_target(target_sha256)?;
            if target.get("reference_id").and_then(Value::as_str) != Some(reference_id) {
                return Err(RuntimeError::InvalidInput(
                    "REFERENCE_SCOPE_DENIED: silhouette target is bound to another reference"
                        .to_owned(),
                ));
            }
        }
        let mut reused_cached_camera_fit = false;
        let mut camera = match object.get("camera").filter(|value| !value.is_null()) {
            None => {
                let cached_camera = target_sha256.as_deref().and_then(|target_sha256| {
                    let cache_key = camera_fit_cache_key(project_id, candidate_id, target_sha256);
                    self.camera_fit_cache
                        .lock()
                        .ok()
                        .and_then(|cache| cache.get(&cache_key).cloned())
                        .and_then(|result| result.get("selected_camera").cloned())
                });
                if let Some(cached_camera) = cached_camera {
                    reused_cached_camera_fit = true;
                    cached_camera
                } else {
                    default_camera_calibration()
                }
            }
            Some(value)
                if value.get("schema_version").and_then(Value::as_str)
                    == Some("CameraCalibrationRef@1") =>
            {
                let target_sha256 = target_sha256.as_deref().ok_or_else(|| {
                    RuntimeError::InvalidInput(
                        "CAMERA_CALIBRATION_INVALID: CameraCalibrationRef@1 requires target_sha256"
                            .to_owned(),
                    )
                })?;
                self.resolve_silhouette_fit_camera(project_id, candidate_id, target_sha256, value)?
            }
            Some(value) => value.clone(),
        };
        validate_camera_calibration(&camera)?;
        let artifact_sha256 = candidate
            .manifest_hash
            .clone()
            .or(candidate.prepared_object_sha256.clone())
            .ok_or_else(|| {
                RuntimeError::InvalidInput("CANDIDATE_ARTIFACT_UNAVAILABLE".to_owned())
            })?;
        let glb = self.cas_read(&artifact_sha256)?;
        let inspection = strict_glb_inspection(&glb)?;
        if !inspection.hard_gate_passed {
            return Err(RuntimeError::InvalidInput(format!(
                "RENDER_REJECTED: strict GLB readback failed: {}",
                inspection.failure_codes.join(",")
            )));
        }
        let initial_render = render_glb_with_runtime_worker_identity(&glb, &camera)
            .map_err(|error| RuntimeError::InvalidInput(format!("RENDER_REJECTED: {error}")))?;
        let mut render_worker_cohort = initial_render.build_cohort_sha256.clone();
        let render_profile = initial_render.render_profile.clone();
        let mut render_passes = initial_render.passes;
        let (reference_mask, reference_mask_method, reference_mask_revision) =
            if let Some(target_sha256) = target_sha256.as_deref() {
                // A caller-supplied SilhouetteTarget is the reviewed contour
                // truth for this comparison. Falling back to a fresh
                // flood-fill here would make camera fitting and the final
                // quality gate evaluate different masks despite sharing one
                // target hash.
                let target = self.read_silhouette_target(target_sha256)?;
                (
                    self.target_mask(target_sha256, &target)?,
                    "silhouette-target",
                    "target-1",
                )
            } else {
                let reference_bytes = self.cas_read(&reference.object_sha256)?;
                (
                    reference_mask_png(&reference_bytes)?,
                    "local-border-flood-fill-morphology",
                    "mask-2",
                )
            };
        if !explicit_camera && !reused_cached_camera_fit {
            let initial_silhouette = render_passes
                .iter()
                .find(|pass| pass.pass == "silhouette")
                .map(|pass| decode_binary_mask(&pass.png))
                .transpose()?;
            if let Some(initial_silhouette) = initial_silhouette {
                // Compare a small deterministic set of framing candidates and
                // keep the one with the best combined silhouette/boundary/
                // extent/centroid score. This prevents a height-only fit from
                // improving one metric while making the overall reference
                // comparison worse. Only the winning render is persisted.
                let mut best_camera = camera.clone();
                let mut best_passes = std::mem::take(&mut render_passes);
                let mut best_score = camera_fit_score(&reference_mask.mask, &initial_silhouette);
                for candidate in [
                    calibrate_default_camera_height_only(
                        &camera,
                        &reference_mask.mask,
                        &initial_silhouette,
                    ),
                    calibrate_default_camera(&camera, &reference_mask.mask, &initial_silhouette),
                ] {
                    if candidate == camera {
                        continue;
                    }
                    validate_camera_calibration(&candidate)?;
                    let candidate_render =
                        render_glb_with_runtime_worker_identity(&glb, &candidate).map_err(
                            |error| RuntimeError::InvalidInput(format!("RENDER_REJECTED: {error}")),
                        )?;
                    let candidate_silhouette = candidate_render
                        .passes
                        .iter()
                        .find(|pass| pass.pass == "silhouette")
                        .map(|pass| decode_binary_mask(&pass.png))
                        .transpose()?
                        .ok_or_else(|| {
                            RuntimeError::InvalidInput(
                                "RENDER_REJECTED: calibrated silhouette pass missing".to_owned(),
                            )
                        })?;
                    let score = camera_fit_score(&reference_mask.mask, &candidate_silhouette);
                    if score > best_score {
                        best_score = score;
                        best_camera = candidate;
                        render_worker_cohort = candidate_render.build_cohort_sha256.clone();
                        best_passes = candidate_render.passes;
                    }
                }
                camera = best_camera;
                render_passes = best_passes;
            }
        }
        let camera_bytes = canonical_json_bytes(&camera)
            .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
        let camera_object = self.put_object(
            &camera_bytes,
            None,
            "application/json",
            "camera-calibration",
        )?;
        if render_passes.len() != 9
            || render_passes
                .iter()
                .any(|pass| pass.width != 512 || pass.height != 512)
        {
            return Err(RuntimeError::InvalidInput(
                "RENDER_REJECTED: fixed renderer did not return nine 512x512 passes".to_owned(),
            ));
        }
        let mut pass_artifacts = serde_json::Map::new();
        let mut pass_bytes = std::collections::HashMap::new();
        for pass in &render_passes {
            let stored = self.put_object(
                &pass.png,
                None,
                "image/png",
                &format!("render-pass-{}", pass.pass),
            )?;
            pass_bytes.insert(pass.pass.clone(), pass.png.clone());
            pass_artifacts.insert(
                pass.pass.clone(),
                json!({
                    "sha256":stored.record.sha256,
                    "mime":"image/png",
                    "size_bytes":stored.record.size_bytes,
                    "width":512,
                    "height":512,
                    "channels":"rgba8",
                    "color_space":if pass.pass == "beauty" {"srgb"} else {"data"}
                }),
            );
        }
        let mut render_set = json!({
            "schema_version":"RenderSet@2",
            "render_set_id":format!("render-set-{}", &artifact_sha256[..32]),
            "candidate_id":candidate_id,
            "artifact_sha256":artifact_sha256,
            "program_sha256":inspection.program_sha256,
            "reference_id":reference_id,
            "camera_hash":camera["camera_hash"].clone(),
            "camera_object_sha256":camera_object.record.sha256.clone(),
            "renderer_hash":sha256_hex(b"forgecad-renderer-2"),
            "render_profile":render_profile.clone(),
            "render_profile_sha256":render_profile["canonical_sha256"].clone(),
            "aov_definition_sha256":render_profile["aov_definition_sha256"].clone(),
            "color_pipeline_sha256":render_profile["color_pipeline_sha256"].clone(),
            "id_palette_definition_sha256":render_profile["id_palette_definition_sha256"].clone(),
            "render_worker_build_cohort_sha256":render_worker_cohort.clone(),
            "render_worker_binding_status":render_worker_binding_status(render_worker_cohort.as_ref()),
            "width":512,
            "height":512,
            "passes":["beauty","silhouette","depth","normal","ao","part-id","material-id","wireframe","uv-stretch"],
            "pass_artifacts":pass_artifacts,
            "canonical_sha256":""
        });
        render_set["canonical_sha256"] = Value::String(canonical_json_hash(&render_set));
        validate_render_set_v2_output(&render_set)?;
        let render_set_bytes = canonical_json_bytes(&render_set)
            .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
        let render_set_object =
            self.put_object(&render_set_bytes, None, "application/json", "render-set-v2")?;
        let render_set_hash = render_set_object.record.sha256.clone();
        let mask_object = self.put_object(
            &reference_mask.png,
            None,
            "image/png",
            // reference_mask_prepare may already have admitted these exact
            // deterministic bytes. Reuse its stable CAS kind so the later
            // compare stage remains idempotent instead of colliding on
            // metadata for the same content hash.
            "reference-silhouette-mask-v1",
        )?;
        let model_mask = pass_bytes.get("silhouette").ok_or_else(|| {
            RuntimeError::InvalidInput("RENDER_REJECTED: silhouette pass missing".to_owned())
        })?;
        let metrics = compare_masks_with_parts(
            &reference_mask.mask,
            &decode_binary_mask(model_mask)?,
            view_spec,
            pass_bytes
                .get("part-id")
                .map(|bytes| (bytes.as_slice(), inspection.part_ids.as_slice())),
        );
        let annotation_readiness = reference_annotation_readiness(
            self,
            project_id,
            candidate_id,
            reference_id,
            target_sha256.as_deref(),
            view_spec,
            &camera,
        )?;
        let visual_status = if annotation_readiness.benchmark_eligibility == "READY_PARTIAL_VIEW"
            && visible_view_gate_passes(&metrics)
        {
            "PARTIAL_VISIBLE_VIEW_PASS"
        } else {
            "QUALITY_TARGET_NOT_MET"
        };
        let mut comparison = json!({
            "schema_version":"ReferenceComparisonReport@1",
            "report_id":format!("comparison-{}", &render_set_hash[..32]),
            "candidate_id":candidate_id,
            "artifact_sha256":artifact_sha256,
            "reference_id":reference_id,
            "reference_sha256":reference.object_sha256,
            "render_set_hash":render_set_hash,
            "camera_hash":camera["camera_hash"].clone(),
            "benchmark_eligibility":annotation_readiness.benchmark_eligibility,
            "mask":{"method":reference_mask_method,"revision":reference_mask_revision,"sha256":mask_object.record.sha256,"width":512,"height":512},
            "metrics":metrics,
            "status":visual_status,
            "canonical_sha256":""
        });
        comparison["canonical_sha256"] = Value::String(canonical_json_hash(&comparison));
        validate_reference_comparison_report(&comparison)?;
        let comparison_object = self.put_object(
            &canonical_json_bytes(&comparison)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            None,
            "application/json",
            "reference-comparison-report",
        )?;
        let comparison_hash = comparison_object.record.sha256.clone();
        let quality_id = format!("quality-c-{}", Uuid::new_v4().simple());
        let mut limitations = vec![
            "human_visual_review_not_run".to_owned(),
            "single_reference_view_only".to_owned(),
            "HQ_360_PASS_BLOCKED_REFERENCE_COVERAGE".to_owned(),
        ];
        limitations.push(format!(
            "benchmark_eligibility:{}",
            annotation_readiness.benchmark_eligibility
        ));
        limitations.extend(
            annotation_readiness
                .reasons
                .iter()
                .map(|reason| format!("reference_annotation:{reason}")),
        );
        let mut quality = json!({
            "schema_version":"QualityReport@2",
            "quality_report_id":quality_id,
            "candidate_id":candidate_id,
            "artifact_sha256":artifact_sha256,
            "program_sha256":inspection.program_sha256,
            "reference_id":reference_id,
            "reference_sha256":reference.object_sha256,
            "render_set_hash":render_set_hash,
            "comparison_report_hash":comparison_hash,
            "human_receipt_hash":Value::Null,
            "structural_status":"passed",
            "visual_status":visual_status,
            "hard_gate_passed":visual_status == "PARTIAL_VISIBLE_VIEW_PASS",
            "threshold_revision":VISIBLE_VIEW_THRESHOLD_REVISION,
            "threshold_policy_sha256":visible_view_threshold_policy_sha256(),
            "threshold_source":VISIBLE_VIEW_THRESHOLD_SOURCE,
            "metric_gate_results":visible_view_gate_checks(&metrics),
            "benchmark_eligibility":annotation_readiness.benchmark_eligibility,
            "limitations":limitations,
            "canonical_sha256":""
        });
        quality["canonical_sha256"] = Value::String(canonical_json_hash(&quality));
        validate_quality_report_v2_output(&quality)?;
        let quality_object = self.put_object(
            &canonical_json_bytes(&quality)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            None,
            "application/json",
            "quality-report-v2",
        )?;
        let now = now_string();
        self.store.upsert_visual_evidence(&VisualEvidenceRecord {
            candidate_id: candidate_id.to_owned(),
            project_id: project_id.to_owned(),
            reference_id: reference_id.to_owned(),
            target_sha256: target_sha256.clone(),
            render_set_object_sha256: render_set_object.record.sha256.clone(),
            comparison_report_object_sha256: Some(comparison_object.record.sha256.clone()),
            visual_review_object_sha256: None,
            quality_report_object_sha256: quality_object.record.sha256.clone(),
            human_receipt_object_sha256: None,
            created_at: now.clone(),
            updated_at: now,
        })?;
        Ok(json!({
            "schema_version":"ReferenceComparisonPrepareResult@1",
            "candidate_id":candidate_id,
            "reference_id":reference_id,
            "camera":camera,
            "camera_object_sha256":camera_object.record.sha256,
            "render_set":render_set,
            "render_set_hash":render_set_object.record.sha256,
            "render_set_object_sha256":render_set_object.record.sha256,
            "comparison_report":comparison,
            "comparison_report_hash":comparison_object.record.sha256,
            "comparison_report_object_sha256":comparison_object.record.sha256,
            "quality_report":quality,
            "quality_report_object_sha256":quality_object.record.sha256
        }))
    }

    pub fn render_pass_get(
        &self,
        render_set_hash: &str,
        pass_name: &str,
    ) -> Result<Value, RuntimeError> {
        if !forgecad_contracts::is_sha256(render_set_hash) {
            return Err(RuntimeError::InvalidInput(
                "RENDER_PASS_INVALID: render_set_hash is invalid".to_owned(),
            ));
        }
        let render_set: Value = serde_json::from_slice(&self.cas_read(render_set_hash)?)
            .map_err(|error| RuntimeError::InvalidInput(format!("RENDER_PASS_INVALID: {error}")))?;
        validate_render_set_v2_output(&render_set)?;
        let artifact = render_set
            .get("pass_artifacts")
            .and_then(|value| value.get(pass_name))
            .ok_or_else(|| RuntimeError::InvalidInput("RENDER_PASS_NOT_FOUND".to_owned()))?;
        let pass_hash = artifact
            .get("sha256")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                RuntimeError::InvalidInput("RENDER_PASS_INVALID: pass hash is missing".to_owned())
            })?;
        let png = self.cas_read(pass_hash)?;
        if !png.starts_with(b"\x89PNG\r\n\x1a\n") {
            return Err(RuntimeError::InvalidInput(
                "RENDER_PASS_INVALID: CAS bytes are not PNG".to_owned(),
            ));
        }
        Ok(
            json!({"schema_version":"RenderPassGet@1","render_set_hash":render_set_hash,"candidate_id":render_set["candidate_id"],"pass":pass_name,"mime":"image/png","width":512,"height":512,"sha256":pass_hash,"png_base64":base64::engine::general_purpose::STANDARD.encode(png)}),
        )
    }

    /// Return the candidate-bound visual evidence needed by the optional
    /// Viewer. Reports stay in CAS and are re-read/validated here; the
    /// projection contains no image bytes and performs no writes.
    pub fn visual_evidence(&self, candidate_id: &str) -> Result<Value, RuntimeError> {
        validate_id(candidate_id)?;
        let candidate = self.candidate(candidate_id)?.ok_or_else(|| {
            RuntimeError::InvalidInput(
                "VISUAL_EVIDENCE_UNAVAILABLE: candidate not found".to_owned(),
            )
        })?;
        let evidence = self
            .store
            .get_visual_evidence(candidate_id)?
            .ok_or_else(|| RuntimeError::InvalidInput("VISUAL_EVIDENCE_UNAVAILABLE".to_owned()))?;
        let reference = self.reference(&evidence.reference_id)?.ok_or_else(|| {
            RuntimeError::InvalidInput(
                "VISUAL_EVIDENCE_UNAVAILABLE: reference not found".to_owned(),
            )
        })?;
        if reference.project_id != candidate.project_id
            || evidence.project_id != candidate.project_id
        {
            return Err(RuntimeError::InvalidInput(
                "VISUAL_EVIDENCE_BINDING_MISMATCH: project differs".to_owned(),
            ));
        }
        let render_set: Value = serde_json::from_slice(
            &self.cas_read(&evidence.render_set_object_sha256)?,
        )
        .map_err(|error| {
            RuntimeError::InvalidInput(format!("VISUAL_EVIDENCE_INVALID: RenderSet: {error}"))
        })?;
        validate_render_set_v2_output(&render_set)?;
        if render_set.get("candidate_id").and_then(Value::as_str) != Some(candidate_id)
            || render_set.get("reference_id").and_then(Value::as_str)
                != Some(evidence.reference_id.as_str())
        {
            return Err(RuntimeError::InvalidInput(
                "VISUAL_EVIDENCE_BINDING_MISMATCH: RenderSet candidate differs".to_owned(),
            ));
        }
        let candidate_artifact_sha256 = candidate
            .prepared_object_sha256
            .as_deref()
            .or(candidate.manifest_hash.as_deref())
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "VISUAL_EVIDENCE_UNAVAILABLE: candidate artifact is missing".to_owned(),
                )
            })?;
        if !forgecad_contracts::is_sha256(candidate_artifact_sha256)
            || candidate
                .prepared_object_sha256
                .as_deref()
                .is_some_and(|hash| !forgecad_contracts::is_sha256(hash))
            || candidate
                .manifest_hash
                .as_deref()
                .is_some_and(|hash| !forgecad_contracts::is_sha256(hash))
            || candidate
                .prepared_object_sha256
                .as_deref()
                .zip(candidate.manifest_hash.as_deref())
                .is_some_and(|(prepared, manifest)| prepared != manifest)
            || render_set.get("artifact_sha256").and_then(Value::as_str)
                != Some(candidate_artifact_sha256)
        {
            return Err(RuntimeError::InvalidInput(
                "VISUAL_EVIDENCE_BINDING_MISMATCH: RenderSet artifact differs from candidate"
                    .to_owned(),
            ));
        }
        if let Some(target_sha256) = evidence.target_sha256.as_deref() {
            let target = self.read_silhouette_target(target_sha256)?;
            if target.get("reference_id").and_then(Value::as_str)
                != Some(evidence.reference_id.as_str())
                || target.get("reference_sha256").and_then(Value::as_str)
                    != Some(reference.object_sha256.as_str())
            {
                return Err(RuntimeError::InvalidInput(
                    "VISUAL_EVIDENCE_BINDING_MISMATCH: silhouette target differs from reference"
                        .to_owned(),
                ));
            }
        }
        let comparison_report = if let Some(hash) =
            evidence.comparison_report_object_sha256.as_deref()
        {
            let report: Value = serde_json::from_slice(&self.cas_read(hash)?).map_err(|error| {
                RuntimeError::InvalidInput(format!(
                    "VISUAL_EVIDENCE_INVALID: comparison report: {error}"
                ))
            })?;
            validate_reference_comparison_report(&report)?;
            if report.get("candidate_id").and_then(Value::as_str) != Some(candidate_id)
                || report.get("reference_id").and_then(Value::as_str)
                    != Some(evidence.reference_id.as_str())
                || report.get("artifact_sha256").and_then(Value::as_str)
                    != Some(candidate_artifact_sha256)
                || report.get("reference_sha256").and_then(Value::as_str)
                    != Some(reference.object_sha256.as_str())
                || report.get("render_set_hash").and_then(Value::as_str)
                    != Some(evidence.render_set_object_sha256.as_str())
                || report.get("camera_hash") != render_set.get("camera_hash")
            {
                return Err(RuntimeError::InvalidInput(
                    "VISUAL_EVIDENCE_BINDING_MISMATCH: comparison report lineage differs"
                        .to_owned(),
                ));
            }
            Some(report)
        } else {
            return Err(RuntimeError::InvalidInput(
                "VISUAL_EVIDENCE_UNAVAILABLE: comparison report is missing".to_owned(),
            ));
        };
        let quality_report = self.quality(candidate_id, Some(&evidence.reference_id))?;
        validate_quality_report_v2_output(&quality_report)?;
        if quality_report.get("candidate_id").and_then(Value::as_str) != Some(candidate_id)
            || quality_report
                .get("artifact_sha256")
                .and_then(Value::as_str)
                != Some(candidate_artifact_sha256)
            || quality_report.get("reference_id").and_then(Value::as_str)
                != Some(evidence.reference_id.as_str())
            || quality_report
                .get("reference_sha256")
                .and_then(Value::as_str)
                != Some(reference.object_sha256.as_str())
            || quality_report
                .get("render_set_hash")
                .and_then(Value::as_str)
                != Some(evidence.render_set_object_sha256.as_str())
            || quality_report
                .get("comparison_report_hash")
                .and_then(Value::as_str)
                != evidence.comparison_report_object_sha256.as_deref()
        {
            return Err(RuntimeError::InvalidInput(
                "VISUAL_EVIDENCE_BINDING_MISMATCH: QualityReport lineage differs".to_owned(),
            ));
        }
        Ok(json!({
            "schema_version":"ViewerVisualEvidence@1",
            "candidate_id":candidate_id,
            "project_id":evidence.project_id,
            "reference_id":evidence.reference_id,
            "target_sha256":evidence.target_sha256,
            "render_set_hash":evidence.render_set_object_sha256,
            "comparison_report_hash":evidence.comparison_report_object_sha256,
            "quality_report_hash":evidence.quality_report_object_sha256,
            "render_set":render_set,
            "comparison_report":comparison_report,
            "quality_report":quality_report
        }))
    }

    pub fn submit_visual_review(&self, request: Value) -> Result<Value, RuntimeError> {
        let object = request.as_object().ok_or_else(|| {
            RuntimeError::InvalidInput("visual review request must be an object".to_owned())
        })?;
        let candidate_id = required_value_id(object.get("candidate_id"), "candidate_id")?;
        let reference_id = required_value_id(object.get("reference_id"), "reference_id")?;
        let evidence = self
            .store
            .get_visual_evidence(candidate_id)?
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "VISUAL_REVIEW_UNAVAILABLE: run reference_compare_prepare first".to_owned(),
                )
            })?;
        if evidence.reference_id != reference_id {
            return Err(RuntimeError::InvalidInput(
                "REFERENCE_BINDING_MISMATCH: review reference differs from candidate evidence"
                    .to_owned(),
            ));
        }
        let render_set_hash = required_value_sha(object.get("render_set_hash"), "render_set_hash")?;
        let render_set: Value = serde_json::from_slice(
            &self.cas_read(&evidence.render_set_object_sha256)?,
        )
        .map_err(|error| {
            RuntimeError::InvalidInput(format!(
                "VISUAL_REVIEW_UNAVAILABLE: RenderSet is invalid: {error}"
            ))
        })?;
        validate_render_set_v2_output(&render_set)?;
        if evidence.render_set_object_sha256 != render_set_hash {
            return Err(RuntimeError::InvalidInput(
                "VISUAL_REVIEW_BINDING_MISMATCH: RenderSet hash is not candidate-bound".to_owned(),
            ));
        }
        let comparison_hash = required_value_sha(
            object.get("comparison_report_hash"),
            "comparison_report_hash",
        )?;
        let comparison_object_sha = evidence
            .comparison_report_object_sha256
            .as_deref()
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "VISUAL_REVIEW_UNAVAILABLE: comparison report is missing".to_owned(),
                )
            })?;
        let comparison: Value = serde_json::from_slice(&self.cas_read(comparison_object_sha)?)
            .map_err(|error| {
                RuntimeError::InvalidInput(format!(
                    "VISUAL_REVIEW_UNAVAILABLE: comparison report is invalid: {error}"
                ))
            })?;
        validate_reference_comparison_report(&comparison)?;
        if evidence.comparison_report_object_sha256.as_deref() != Some(comparison_hash) {
            return Err(RuntimeError::InvalidInput(
                "VISUAL_REVIEW_BINDING_MISMATCH: comparison report is not candidate-bound"
                    .to_owned(),
            ));
        }
        let mut report = json!({"schema_version":"VisualReviewReport@1","review_id":format!("review-{}",Uuid::new_v4().simple()),"candidate_id":candidate_id,"reference_id":reference_id,"render_set_hash":render_set_hash,"comparison_report_hash":comparison_hash,"round":object.get("round").cloned().unwrap_or(Value::Null),"stage":object.get("stage").cloned().unwrap_or(Value::Null),"issues":object.get("issues").cloned().unwrap_or(Value::Array(Vec::new())),"status":object.get("status").cloned().unwrap_or(Value::String("submitted".to_owned())),"canonical_sha256":""});
        report["canonical_sha256"] = Value::String(canonical_json_hash(&report));
        validate_visual_review_report(&report)?;
        let report_object = self.put_object(
            &canonical_json_bytes(&report)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            None,
            "application/json",
            "visual-review-report",
        )?;
        let now = now_string();
        self.store.upsert_visual_evidence(&VisualEvidenceRecord {
            visual_review_object_sha256: Some(report_object.record.sha256.clone()),
            updated_at: now.clone(),
            ..evidence
        })?;
        Ok(
            json!({"schema_version":"VisualReviewSubmitResult@1","review":report,"review_object_sha256":report_object.record.sha256}),
        )
    }

    pub fn submit_human_visual_review(&self, request: Value) -> Result<Value, RuntimeError> {
        let object = request.as_object().ok_or_else(|| {
            RuntimeError::InvalidInput("human visual review request must be an object".to_owned())
        })?;
        let candidate_id = required_value_id(object.get("candidate_id"), "candidate_id")?;
        let reference_id = required_value_id(object.get("reference_id"), "reference_id")?;
        let evidence = self
            .store
            .get_visual_evidence(candidate_id)?
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "HUMAN_REVIEW_UNAVAILABLE: run reference_compare_prepare first".to_owned(),
                )
            })?;
        if evidence.reference_id != reference_id {
            return Err(RuntimeError::InvalidInput("REFERENCE_BINDING_MISMATCH: human review reference differs from candidate evidence".to_owned()));
        }
        let render_set_hash = required_value_sha(object.get("render_set_hash"), "render_set_hash")?;
        let comparison_hash = required_value_sha(
            object.get("comparison_report_hash"),
            "comparison_report_hash",
        )?;
        let render_set: Value = serde_json::from_slice(
            &self.cas_read(&evidence.render_set_object_sha256)?,
        )
        .map_err(|error| {
            RuntimeError::InvalidInput(format!(
                "HUMAN_REVIEW_UNAVAILABLE: RenderSet is invalid: {error}"
            ))
        })?;
        validate_render_set_v2_output(&render_set)?;
        if evidence.render_set_object_sha256 != render_set_hash {
            return Err(RuntimeError::InvalidInput(
                "HUMAN_REVIEW_BINDING_MISMATCH: RenderSet hash is not candidate-bound".to_owned(),
            ));
        }
        let comparison_object_sha = evidence
            .comparison_report_object_sha256
            .as_deref()
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "HUMAN_REVIEW_UNAVAILABLE: comparison report is missing".to_owned(),
                )
            })?;
        let comparison: Value = serde_json::from_slice(&self.cas_read(comparison_object_sha)?)
            .map_err(|error| {
                RuntimeError::InvalidInput(format!(
                    "HUMAN_REVIEW_UNAVAILABLE: comparison report is invalid: {error}"
                ))
            })?;
        validate_reference_comparison_report(&comparison)?;
        if evidence.comparison_report_object_sha256.as_deref() != Some(comparison_hash) {
            return Err(RuntimeError::InvalidInput(
                "HUMAN_REVIEW_BINDING_MISMATCH: comparison report is not candidate-bound"
                    .to_owned(),
            ));
        }
        let scores = object
            .get("scores")
            .cloned()
            .ok_or_else(|| RuntimeError::InvalidInput("HUMAN_REVIEW_SCORES_REQUIRED".to_owned()))?;
        let mut receipt = json!({"schema_version":"HumanVisualReviewReceipt@1","receipt_id":format!("human-review-{}",Uuid::new_v4().simple()),"candidate_id":candidate_id,"reference_id":reference_id,"render_set_hash":render_set_hash,"comparison_report_hash":comparison_hash,"scores":scores,"approved":object.get("approved").cloned().unwrap_or(Value::Bool(false)),"recorded_at":now_string(),"canonical_sha256":""});
        receipt["canonical_sha256"] = Value::String(canonical_json_hash(&receipt));
        validate_human_review_receipt(&receipt)?;
        let receipt_object = self.put_object(
            &canonical_json_bytes(&receipt)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            None,
            "application/json",
            "human-visual-review-receipt",
        )?;
        let mut quality: Value =
            serde_json::from_slice(&self.cas_read(&evidence.quality_report_object_sha256)?)
                .map_err(|error| {
                    RuntimeError::InvalidInput(format!("QUALITY_REPORT_INVALID: {error}"))
                })?;
        quality["human_receipt_hash"] = Value::String(receipt_object.record.sha256.clone());
        quality["canonical_sha256"] = Value::String(String::new());
        quality["canonical_sha256"] = Value::String(canonical_json_hash(&quality));
        validate_quality_report_v2_output(&quality)?;
        let quality_object = self.put_object(
            &canonical_json_bytes(&quality)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            None,
            "application/json",
            "quality-report-v2",
        )?;
        let now = now_string();
        self.store.upsert_visual_evidence(&VisualEvidenceRecord {
            human_receipt_object_sha256: Some(receipt_object.record.sha256.clone()),
            quality_report_object_sha256: quality_object.record.sha256.clone(),
            updated_at: now,
            ..evidence
        })?;
        Ok(
            json!({"schema_version":"HumanVisualReviewSubmitResult@1","receipt":receipt,"receipt_object_sha256":receipt_object.record.sha256,"quality_report":quality,"quality_report_object_sha256":quality_object.record.sha256}),
        )
    }

    pub fn version_diff(
        &self,
        version_id: &str,
        compare_to_version_id: &str,
    ) -> Result<Value, RuntimeError> {
        validate_id(version_id)?;
        validate_id(compare_to_version_id)?;
        let version = self
            .version(version_id)?
            .ok_or_else(|| RuntimeError::InvalidInput("NOT_FOUND: version not found".to_owned()))?;
        let compare = self
            .version(compare_to_version_id)?
            .ok_or_else(|| RuntimeError::InvalidInput("NOT_FOUND: version not found".to_owned()))?;
        if version.project_id != compare.project_id {
            return Err(RuntimeError::InvalidInput(
                "PROJECT_SCOPE_DENIED: versions are from different projects".to_owned(),
            ));
        }
        let left = self.candidate(&version.candidate_id)?.ok_or_else(|| {
            RuntimeError::InvalidInput("NOT_FOUND: version candidate not found".to_owned())
        })?;
        let right = self.candidate(&compare.candidate_id)?.ok_or_else(|| {
            RuntimeError::InvalidInput("NOT_FOUND: comparison candidate not found".to_owned())
        })?;
        let left_parts = left
            .manifest_hash
            .as_deref()
            .and_then(|hash| self.cas_read(hash).ok())
            .and_then(|bytes| inspect_glb(&bytes).ok())
            .map(|inspection| inspection.part_ids)
            .unwrap_or_default();
        let right_parts = right
            .manifest_hash
            .as_deref()
            .and_then(|hash| self.cas_read(hash).ok())
            .and_then(|bytes| inspect_glb(&bytes).ok())
            .map(|inspection| inspection.part_ids)
            .unwrap_or_default();
        Ok(json!({
            "schema_version":"VersionDiff@1",
            "project_id":version.project_id,
            "version_id":version_id,
            "compare_to_version_id":compare_to_version_id,
            "same_artifact":version.manifest_hash == compare.manifest_hash,
            "request_changed":left.request_sha256 != right.request_sha256,
            "part_ids": {"version":left_parts,"compare_to_version":right_parts},
            "limitation":"MVP diff is hash/lineage based; mesh-space delta visualization remains post-MVP."
        }))
    }

    pub fn job(&self, id: &str) -> Result<Option<JobSummary>, RuntimeError> {
        validate_id(id)?;
        Ok(self.store.get_job(id)?)
    }

    pub fn job_events(
        &self,
        id: &str,
        after_sequence: i64,
    ) -> Result<Vec<JobEventRecord>, RuntimeError> {
        validate_id(id)?;
        if after_sequence < 0 {
            return Err(RuntimeError::InvalidInput(
                "negative event cursor".to_owned(),
            ));
        }
        Ok(self.store.list_job_events(id, after_sequence)?)
    }

    /// Read the CAS-backed result published by a Runtime Job.  The result is
    /// unavailable while the job is queued/running; callers poll `job_get` or
    /// `job_events_read` first.  Only a hash-bound object recorded by the Job
    /// terminal event can be returned.
    pub fn job_result(&self, id: &str) -> Result<Value, RuntimeError> {
        validate_id(id)?;
        let job = self
            .store
            .get_job(id)?
            .ok_or_else(|| RuntimeError::InvalidInput("NOT_FOUND: job not found".to_owned()))?;
        let events = self.store.list_job_events(id, 0)?;
        let result_sha256 = events
            .iter()
            .rev()
            .find(|event| event.kind == "completed")
            .and_then(|event| event.payload.get("result_sha256"))
            .and_then(Value::as_str)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(if job.status == "running" || job.status == "queued" {
                    "JOB_RESULT_PENDING".to_owned()
                } else {
                    "JOB_RESULT_UNAVAILABLE".to_owned()
                })
            })?;
        if !forgecad_contracts::is_sha256(result_sha256) {
            return Err(RuntimeError::InvalidInput(
                "JOB_RESULT_INVALID: result hash is not a SHA-256".to_owned(),
            ));
        }
        let result: Value =
            serde_json::from_slice(&self.cas_read(result_sha256)?).map_err(|_| {
                RuntimeError::InvalidInput(
                    "JOB_RESULT_INVALID: result CAS object is not JSON".to_owned(),
                )
            })?;
        Ok(json!({
            "schema_version": "RuntimeJobResult@1",
            "job": job,
            "result_sha256": result_sha256,
            "result": result,
        }))
    }

    /// Start an asynchronous Runtime-owned Primary Form search.  The request
    /// is admitted synchronously and the actual Geometry/Render Worker loop
    /// runs outside the MCP IPC deadline.  It creates no version and does not
    /// bypass the existing `primary_form_repair_prepare` acceptance path.
    pub fn primary_form_repair_job_prepare(
        &self,
        project_id: &str,
        base_version_id: Option<&str>,
        request: Value,
    ) -> Result<Value, RuntimeError> {
        validate_id(project_id)?;
        let object = request.as_object().ok_or_else(|| {
            RuntimeError::InvalidInput(
                "PRIMARY_FORM_REPAIR_JOB_INVALID: request must be an object".to_owned(),
            )
        })?;
        validate_request_keys(
            object,
            &[
                "project_id",
                "candidate_id",
                "target_sha256",
                "part_id",
                "rig",
                "base_camera",
                "optimizer",
                "view_spec",
                "base_version_id",
                "canonical_sha256",
            ],
            "primary_form_repair_job_prepare",
        )?;
        if object.get("project_id").and_then(Value::as_str) != Some(project_id) {
            return Err(RuntimeError::InvalidInput(
                "PROJECT_SCOPE_DENIED: Primary Form job project differs".to_owned(),
            ));
        }
        if object.get("base_version_id").and_then(Value::as_str) != base_version_id {
            return Err(RuntimeError::InvalidInput(
                "PRIMARY_FORM_REPAIR_JOB_INVALID: base_version_id argument is not bound to intent"
                    .to_owned(),
            ));
        }
        let intent_hash = required_value_sha(object.get("canonical_sha256"), "canonical_sha256")?;
        let mut intent_without_hash = request.clone();
        intent_without_hash["canonical_sha256"] = Value::String(String::new());
        if canonical_json_hash(&intent_without_hash) != intent_hash
            && canonical_json_hash(&normalize_json_numbers(&intent_without_hash)) != intent_hash
        {
            return Err(RuntimeError::InvalidInput(
                "PRIMARY_FORM_REPAIR_JOB_INVALID: canonical_sha256 does not bind intent".to_owned(),
            ));
        }
        let job_id = format!("job-primary-form-{}", Uuid::new_v4().simple());
        let request_sha256 = request_hash(&request);
        let now = now_string();
        let job = JobRecord {
            schema_version: "RuntimeJob@1".to_owned(),
            job_id: job_id.clone(),
            project_id: project_id.to_owned(),
            kind: "primary_form_repair".to_owned(),
            status: "queued".to_owned(),
            progress: 0,
            request_sha256: request_sha256.clone(),
            checkpoint_sha256: None,
            error_code: None,
            created_at: now.clone(),
            updated_at: now.clone(),
        };
        let event = JobEventRecord {
            schema_version: "RuntimeJobEvent@1".to_owned(),
            job_id: job_id.clone(),
            sequence: 1,
            kind: "queued".to_owned(),
            payload: json!({
                "stage": "primary-form",
                "request_sha256": request_sha256,
                "continuous_search_owner": "runtime",
            }),
            created_at: now,
        };
        self.store.insert_job_with_event(&job, &event)?;

        let worker_runtime = self.background_runtime();
        let worker_project_id = project_id.to_owned();
        let worker_base_version_id = base_version_id.map(str::to_owned);
        let worker_request = request;
        let worker_job_id = job_id.clone();
        thread::spawn(move || {
            let result = worker_runtime.primary_form_repair_prepare(
                &worker_project_id,
                worker_base_version_id.as_deref(),
                worker_request,
            );
            match result {
                Ok(result) => {
                    let result_bytes = match canonical_json_bytes(&result) {
                        Ok(bytes) => bytes,
                        Err(_) => {
                            let _ = worker_runtime.store.finish_job_with_event(
                                &worker_job_id,
                                "failed",
                                0,
                                Some("PRIMARY_FORM_REPAIR_JOB_RESULT_SERIALIZATION_FAILED"),
                                "failed",
                                &json!({"stage":"result","code":"PRIMARY_FORM_REPAIR_JOB_RESULT_SERIALIZATION_FAILED"}),
                                &now_string(),
                            );
                            return;
                        }
                    };
                    let result_object = match worker_runtime.put_object(
                        &result_bytes,
                        None,
                        "application/json",
                        "primary-form-repair-job-result",
                    ) {
                        Ok(object) => object,
                        Err(_) => {
                            let _ = worker_runtime.store.finish_job_with_event(
                                &worker_job_id,
                                "failed",
                                0,
                                Some("PRIMARY_FORM_REPAIR_JOB_RESULT_CAS_FAILED"),
                                "failed",
                                &json!({"stage":"result","code":"PRIMARY_FORM_REPAIR_JOB_RESULT_CAS_FAILED"}),
                                &now_string(),
                            );
                            return;
                        }
                    };
                    let prepared = result.get("status").and_then(Value::as_str) == Some("prepared");
                    let _ = worker_runtime.store.finish_job_with_event(
                        &worker_job_id,
                        "succeeded",
                        100,
                        None,
                        "completed",
                        &json!({
                            "stage": "primary-form",
                            "result_sha256": result_object.record.sha256,
                            "result_status": result.get("status").and_then(Value::as_str).unwrap_or("unknown"),
                            "candidate_staged": prepared,
                        }),
                        &now_string(),
                    );
                }
                Err(error) => {
                    let code = primary_form_job_error_code(&error);
                    let _ = worker_runtime.store.finish_job_with_event(
                        &worker_job_id,
                        "failed",
                        0,
                        Some(&code),
                        "failed",
                        &json!({"stage":"primary-form","code":code}),
                        &now_string(),
                    );
                }
            }
        });

        let job = self
            .store
            .get_job(&job_id)?
            .ok_or_else(|| RuntimeError::InvalidInput("PRIMARY_FORM_REPAIR_JOB_LOST".to_owned()))?;
        serde_json::to_value(job).map_err(|error| RuntimeError::InvalidInput(error.to_string()))
    }

    pub fn selection(&self) -> SelectionRecord {
        SelectionRecord {
            schema_version: "Selection@1".to_owned(),
            available: false,
            project_id: None,
            snapshot_id: None,
            version_id: None,
            part_ids: Vec::new(),
            limitation: Some(
                "Viewer selection is not connected to the MCP read model until MCP010.".to_owned(),
            ),
        }
    }

    pub fn resource_descriptors(&self) -> Result<Vec<RuntimeResourceDescriptor>, RuntimeError> {
        let mut resources = vec![RuntimeResourceDescriptor {
            schema_version: "RuntimeResource@1".to_owned(),
            uri: "forgecad://capabilities".to_owned(),
            name: "Runtime capabilities".to_owned(),
            description: "Live Runtime contract and capability state".to_owned(),
            mime_type: "application/json".to_owned(),
            read_only: true,
        }, RuntimeResourceDescriptor {
            schema_version: "RuntimeResource@1".to_owned(),
            uri: "forgecad://operators/catalog".to_owned(),
            name: "Geometry operator catalog".to_owned(),
            description: "Exact product-owned GeometryProgram@2 operators and canonical hash; unavailable operators are omitted".to_owned(),
            mime_type: "application/json".to_owned(),
            read_only: true,
        }];
        for project in self.projects()? {
            resources.push(RuntimeResourceDescriptor {
                schema_version: "RuntimeResource@1".to_owned(),
                uri: format!("forgecad://projects/{}/snapshot", project.project_id),
                name: format!("{} snapshot", project.name),
                description: "The project's current ActiveDesignSnapshot projection".to_owned(),
                mime_type: "application/json".to_owned(),
                read_only: true,
            });
            resources.push(RuntimeResourceDescriptor {
                schema_version: "RuntimeResource@1".to_owned(),
                uri: format!("forgecad://projects/{}/selection", project.project_id),
                name: format!("{} selection", project.name),
                description: "Ephemeral Viewer selection; never a version truth".to_owned(),
                mime_type: "application/json".to_owned(),
                read_only: true,
            });
            for reference in self.references(&project.project_id)? {
                resources.push(RuntimeResourceDescriptor {
                    schema_version: "RuntimeResource@1".to_owned(),
                    uri: format!("forgecad://references/{}", reference.reference_id),
                    name: format!("{} reference", reference.reference_id),
                    description:
                        "Hash-bound reference image evidence; original path is not retained"
                            .to_owned(),
                    mime_type: "application/json".to_owned(),
                    read_only: true,
                });
            }
        }
        for skill in self.skills()? {
            resources.push(RuntimeResourceDescriptor {
                schema_version: "RuntimeResource@1".to_owned(),
                uri: format!("forgecad://skills/{}/{}", skill.skill_id, skill.version),
                name: format!("{} Skill", skill.skill_id),
                description: "First-party development-only Skill manifest; no executable payload"
                    .to_owned(),
                mime_type: "application/json".to_owned(),
                read_only: true,
            });
        }
        Ok(resources)
    }

    pub fn read_resource(&self, uri: &str) -> Result<RuntimeResourceContents, RuntimeError> {
        let segments = resource_segments(uri)?;
        let value = match segments.as_slice() {
            ["capabilities"] => serde_json::to_value(self.capabilities())
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            ["operators", "catalog"] => operator_catalog(),
            ["projects", project_id, "snapshot"] => {
                let project = self
                    .project(project_id)?
                    .ok_or_else(|| RuntimeError::InvalidInput("project not found".to_owned()))?;
                let snapshot = project
                    .head_snapshot_id
                    .as_deref()
                    .map(|id| self.snapshot_record(id))
                    .transpose()?
                    .flatten();
                json!({
                    "schema_version": "ProjectSnapshotResource@1",
                    "project": project,
                    "snapshot": snapshot,
                })
            }
            ["projects", project_id, "selection"] => {
                if self.project(project_id)?.is_none() {
                    return Err(RuntimeError::InvalidInput("project not found".to_owned()));
                }
                serde_json::to_value(self.selection())
                    .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?
            }
            ["candidates", candidate_id] => serde_json::to_value(
                self.candidate(candidate_id)?
                    .ok_or_else(|| RuntimeError::InvalidInput("candidate not found".to_owned()))?,
            )
            .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            ["jobs", job_id] => {
                let job = self
                    .job(job_id)?
                    .ok_or_else(|| RuntimeError::InvalidInput("job not found".to_owned()))?;
                let events = self
                    .job_events(job_id, 0)?
                    .into_iter()
                    .take(128)
                    .collect::<Vec<_>>();
                json!({"schema_version":"RuntimeJobResource@1","job":job,"events":events})
            }
            ["versions", version_id] => serde_json::to_value(
                self.version(version_id)?
                    .ok_or_else(|| RuntimeError::InvalidInput("version not found".to_owned()))?,
            )
            .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            ["references", reference_id] => serde_json::to_value(ReferenceGetResult {
                schema_version: "ReferenceGetResult@1".to_owned(),
                reference: self
                    .reference(reference_id)?
                    .ok_or_else(|| RuntimeError::InvalidInput("reference not found".to_owned()))?,
            })
            .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            ["skills", skill_id, version] => {
                skill_registry::get_result(skill_id, version).map_err(RuntimeError::InvalidInput)?
            }
            ["renders", ..] | ["artifacts", ..] => {
                return Err(RuntimeError::InvalidInput(
                    "resource capability is unavailable".to_owned(),
                ));
            }
            _ => {
                return Err(RuntimeError::InvalidInput(
                    "unknown ForgeCAD resource".to_owned(),
                ))
            }
        };
        let text = serde_json::to_string(&value)
            .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
        Ok(RuntimeResourceContents {
            schema_version: "RuntimeResourceContents@1".to_owned(),
            uri: uri.to_owned(),
            mime_type: "application/json".to_owned(),
            size_bytes: text.len() as u64,
            text,
        })
    }

    pub fn create_project(&self, name: &str, policy: Value) -> Result<ProjectRecord, RuntimeError> {
        if name.trim().is_empty() || name.len() > 200 {
            return Err(RuntimeError::InvalidInput(
                "project name is invalid".to_owned(),
            ));
        }
        let project_id = format!("project-{}", Uuid::new_v4().simple());
        let timestamp = now_string();
        let digest_input = json!({
            "schema_version": "Project@1",
            "project_id": project_id,
            "name": name,
            "policy": policy,
            "created_at": timestamp,
        });
        let project = ProjectRecord {
            schema_version: "Project@1".to_owned(),
            project_id,
            name: name.to_owned(),
            policy,
            created_at: timestamp.clone(),
            updated_at: timestamp,
            active_snapshot_revision: 0,
            head_snapshot_id: None,
            canonical_sha256: canonical_json_hash(&digest_input),
        };
        self.store.insert_project(&project)?;
        Ok(project)
    }

    pub fn import_reference(
        &self,
        request: &ReferenceImportRequest,
    ) -> Result<ReferenceImportResult, RuntimeError> {
        validate_id(&request.project_id)?;
        if self.project(&request.project_id)?.is_none() {
            return Err(RuntimeError::InvalidInput(
                "PROJECT_SCOPE_DENIED: project not found".to_owned(),
            ));
        }
        validate_reference_authorization(&request.authorization)?;
        if let Some(expected) = request.expected_sha256.as_deref() {
            if !forgecad_contracts::is_sha256(expected) {
                return Err(RuntimeError::InvalidInput(
                    "REFERENCE_REJECTED: expected_sha256 is invalid".to_owned(),
                ));
            }
        }
        let (bytes, import_mode, declared_mime) = match &request.source {
            ReferenceImportSource::InlineContent {
                mime,
                content_base64,
            } => {
                if content_base64.len() > MAX_REFERENCE_INLINE_BASE64 {
                    return Err(RuntimeError::InvalidInput(
                        "REFERENCE_REJECTED: inline reference exceeds encoded capacity".to_owned(),
                    ));
                }
                let bytes = base64::engine::general_purpose::STANDARD
                    .decode(content_base64)
                    .map_err(|_| {
                        RuntimeError::InvalidInput(
                            "REFERENCE_REJECTED: inline reference is not valid base64".to_owned(),
                        )
                    })?;
                (bytes, "inline_content", Some(mime.as_str()))
            }
            ReferenceImportSource::CodexLocalFile { path } => {
                let bytes = read_authorized_attachment(path, &self.reference_attachment_roots)?;
                (bytes, "codex_local_file", None)
            }
        };
        let inspection = inspect_reference_bytes(&bytes, declared_mime)?;
        let object = self.put_object(
            &bytes,
            request.expected_sha256.as_deref(),
            inspection.mime,
            "reference-image",
        )?;
        let reference_id = format!("reference-{}", Uuid::new_v4().simple());
        let created_at = now_string();
        let canonical_sha256 = canonical_json_hash(&json!({
            "schema_version": "ReferenceEvidence@1",
            "reference_id": reference_id.clone(),
            "project_id": request.project_id.clone(),
            "object_sha256": object.record.sha256.clone(),
            "mime": inspection.mime,
            "size_bytes": object.record.size_bytes,
            "width": inspection.width,
            "height": inspection.height,
            "frame_count": 1,
            "import_mode": import_mode,
            "authorization": request.authorization.clone(),
            "derived_object_sha256": Value::Null,
            "created_at": created_at.clone(),
        }));
        let reference = ReferenceEvidenceRecord {
            schema_version: "ReferenceEvidence@1".to_owned(),
            reference_id,
            project_id: request.project_id.clone(),
            object_sha256: object.record.sha256.clone(),
            mime: inspection.mime.to_owned(),
            size_bytes: object.record.size_bytes,
            width: inspection.width,
            height: inspection.height,
            frame_count: 1,
            import_mode: import_mode.to_owned(),
            authorization: request.authorization.clone(),
            derived_object_sha256: None,
            canonical_sha256,
            created_at: created_at.clone(),
        };
        self.store.insert_reference_evidence(&reference)?;
        self.store
            .append_audit(&forgecad_contracts::AuditEventRecord {
                schema_version: "AuditEvent@1".to_owned(),
                audit_id: format!("audit-{}", Uuid::new_v4().simple()),
                project_id: Some(request.project_id.clone()),
                kind: "reference_imported".to_owned(),
                object_id: Some(reference.reference_id.clone()),
                request_sha256: Some(request_hash(
                    &serde_json::to_value(request)
                        .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
                )),
                payload: json!({
                    "reference_id": reference.reference_id,
                    "object_sha256": reference.object_sha256,
                    "mime": reference.mime,
                    "width": reference.width,
                    "height": reference.height,
                    "import_mode": reference.import_mode,
                }),
                created_at,
            })?;
        Ok(ReferenceImportResult {
            schema_version: "ReferenceImportResult@1".to_owned(),
            reference,
        })
    }

    /// Create the smallest Runtime-owned diagnostic candidate for the MVP
    /// transaction probe. This is deliberately a typed, non-visual object;
    /// it proves project/prepare/quality/confirm lineage without pretending
    /// that reference import or a Geometry/Quality Compiler is available.
    pub fn prepare_diagnostic_candidate(
        &self,
        project_id: &str,
        base_version_id: Option<&str>,
        request: Value,
    ) -> Result<CandidatePrepareResult, RuntimeError> {
        let object = request.as_object().ok_or_else(|| {
            RuntimeError::InvalidInput("diagnostic candidate request must be an object".to_owned())
        })?;
        if object.keys().any(|key| key != "typed" && key != "label") {
            return Err(RuntimeError::InvalidInput(
                "diagnostic candidate request contains an unsupported field".to_owned(),
            ));
        }
        if object.get("typed").and_then(Value::as_str) != Some("diagnostic") {
            return Err(RuntimeError::InvalidInput(
                "candidate_prepare requires typed=diagnostic when no CAS object is supplied"
                    .to_owned(),
            ));
        }
        let label = object
            .get("label")
            .and_then(Value::as_str)
            .unwrap_or("diagnostic")
            .trim();
        if label.is_empty() || label.len() > 128 {
            return Err(RuntimeError::InvalidInput(
                "diagnostic label is invalid".to_owned(),
            ));
        }
        let request_sha256 = request_hash(&request);
        let artifact = json!({
            "schema_version": "DiagnosticPreparedObject@1",
            "kind": "diagnostic",
            "label": label,
            "request_sha256": request_sha256,
            "visual": false,
        });
        let artifact_bytes = canonical_json_bytes(&artifact)
            .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
        let artifact_object = self.put_object(
            &artifact_bytes,
            None,
            "application/json",
            "diagnostic-prepared-object",
        )?;
        let prepared_object_id =
            format!("diagnostic-object-{}", &artifact_object.record.sha256[..32]);
        let prepared = self.prepare_candidate(
            project_id,
            base_version_id,
            &prepared_object_id,
            &artifact_object.record.sha256,
            request.clone(),
        )?;
        let quality_report = json!({
            "schema_version": "DiagnosticQualityReport@1",
            "scope": "contract-only",
            "candidate_id": prepared.candidate.candidate_id,
            "prepared_object_sha256": artifact_object.record.sha256,
            "checks": {
                "request_schema": true,
                "canonical_artifact": true,
                "cas_hash_binding": true,
                "visual_quality": "not_evaluated"
            },
            "hard_gate_passed": true,
        });
        let quality_bytes = canonical_json_bytes(&quality_report)
            .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
        let quality_object = self.put_object(
            &quality_bytes,
            None,
            "application/json",
            "diagnostic-quality-report",
        )?;
        let quality_report_id =
            format!("quality-diagnostic-{}", &quality_object.record.sha256[..32]);
        let candidate = self.mark_candidate_quality(
            &prepared.candidate.candidate_id,
            &quality_report_id,
            true,
        )?;
        Ok(CandidatePrepareResult {
            schema_version: prepared.schema_version,
            candidate,
            job: prepared.job,
        })
    }

    pub fn insert_candidate(&self, candidate: &CandidateRecord) -> Result<(), RuntimeError> {
        self.store.insert_candidate(candidate)?;
        Ok(())
    }

    /// Compile a bounded GeometryProgram into a real multi-part GLB and then
    /// enter the normal candidate/quality transaction. The compiler is a
    /// fixed, one-shot product-owned sibling Worker; no arbitrary code,
    /// command, environment, or path is accepted from MCP input.
    pub fn prepare_geometry_candidate(
        &self,
        project_id: &str,
        base_version_id: Option<&str>,
        request: Value,
    ) -> Result<Value, RuntimeError> {
        let object = request.as_object().ok_or_else(|| {
            RuntimeError::InvalidInput("geometry request must be an object".to_owned())
        })?;
        if object
            .keys()
            .any(|key| !matches!(key.as_str(), "typed" | "reference_id" | "geometry_program"))
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_REJECTED: geometry request contains an unsupported field".to_owned(),
            ));
        }
        if object.get("typed").and_then(Value::as_str) != Some("geometry") {
            return Err(RuntimeError::InvalidInput(
                "geometry request requires typed=geometry".to_owned(),
            ));
        }
        let program = object
            .get("geometry_program")
            .ok_or_else(|| RuntimeError::InvalidInput("geometry_program is required".to_owned()))?;
        if program.get("project_id").and_then(Value::as_str) != Some(project_id) {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_REJECTED: GeometryProgram project_id must match the target project"
                    .to_owned(),
            ));
        }
        let (reference_id, reference_sha256) = match object.get("reference_id") {
            None => (None, None),
            Some(Value::String(reference_id)) => {
                let reference = self.reference(reference_id)?.ok_or_else(|| {
                    RuntimeError::InvalidInput("NOT_FOUND: reference not found".to_owned())
                })?;
                if reference.project_id != project_id {
                    return Err(RuntimeError::InvalidInput(
                        "REFERENCE_SCOPE_DENIED: geometry reference is outside the target project"
                            .to_owned(),
                    ));
                }
                (Some(reference.reference_id), Some(reference.object_sha256))
            }
            Some(_) => {
                return Err(RuntimeError::InvalidInput(
                    "GEOMETRY_REJECTED: reference_id must be an identifier".to_owned(),
                ));
            }
        };
        let is_v2 =
            program.get("schema_version").and_then(Value::as_str) == Some("GeometryProgram@2");
        let artifact = compile_geometry_with_runtime_worker(program, None)
            .map_err(|error| RuntimeError::InvalidInput(format!("GEOMETRY_REJECTED: {error}")))?;
        let inspection = strict_glb_inspection(&artifact.glb)?;
        validate_worker_metadata(&artifact, &inspection)?;
        let hard_gate_passed = if is_v2 {
            inspection.hard_gate_passed
        } else {
            physical_geometry_passed(&inspection)
        };
        if !hard_gate_passed {
            return Err(RuntimeError::InvalidInput(format!(
                "GEOMETRY_REJECTED: strict GLB readback failed: {}",
                inspection.failure_codes.join(",")
            )));
        }
        let glb_object =
            self.put_object(&artifact.glb, None, "model/gltf-binary", "geometry-glb")?;
        let geometry_program_object = if is_v2 {
            let mut draft = program.clone();
            draft
                .as_object_mut()
                .expect("GeometryProgram was checked as an object")
                .remove("canonical_sha256");
            let bytes = canonical_json_bytes(&draft)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
            let object = self.put_object(
                &bytes,
                Some(&inspection.program_sha256),
                "application/json",
                "geometry-program-v2",
            )?;
            if object.record.sha256 != inspection.program_sha256 {
                return Err(RuntimeError::InvalidInput(
                    "GEOMETRY_REJECTED: canonical GeometryProgram hash does not match CAS"
                        .to_owned(),
                ));
            }
            Some(object)
        } else {
            None
        };
        let prepared = self.prepare_candidate(
            project_id,
            base_version_id,
            &format!("geometry-object-{}", &glb_object.record.sha256[..32]),
            &glb_object.record.sha256,
            request.clone(),
        )?;
        let readback = if is_v2 {
            artifact_readback_v2_value(
                &glb_object.record.sha256,
                &prepared.candidate.candidate_id,
                &inspection,
                glb_object.record.size_bytes,
            )
        } else {
            artifact_readback_v1_value(
                &glb_object.record.sha256,
                &prepared.candidate.candidate_id,
                &inspection,
                glb_object.record.size_bytes,
            )
        };
        if is_v2 {
            validate_artifact_readback_v2_output(&readback)?;
        }
        let readback_object = if is_v2 {
            let bytes = canonical_json_bytes(&readback)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
            Some(self.put_object(
                &bytes,
                None,
                "application/json",
                "geometry-artifact-readback-v2",
            )?)
        } else {
            None
        };
        let quality_report_id = if is_v2 {
            format!("quality-geometry-{}", Uuid::new_v4().simple())
        } else {
            String::new()
        };
        let mut quality_report = if is_v2 {
            json!({
                "schema_version":"GeometryQualityReport@2",
                "scope":"mcp010b-strict-glb-bin-accessor-hard-gates",
                "quality_report_id":quality_report_id,
                "candidate_id":prepared.candidate.candidate_id,
                "artifact_sha256":glb_object.record.sha256,
                "program_sha256":inspection.program_sha256,
                "operator_catalog_sha256":inspection.operator_catalog_sha256,
                "readback_config_sha256":inspection.readback_config_sha256,
                "artifact_readback_object_sha256":readback_object.as_ref().expect("V2 readback object").record.sha256,
                "integrity":strict_integrity_value(&inspection),
                "hard_gate_passed":hard_gate_passed,
                "canonical_sha256":""
            })
        } else {
            json!({
                "schema_version":"GeometryQualityReport@1",
                "scope":"legacy-compatible-physical-glb-readback",
                "candidate_id":prepared.candidate.candidate_id,
                "artifact_sha256":glb_object.record.sha256,
                "checks":{"non_empty_glb":inspection.triangle_count > 0,"finite_positions":inspection.non_finite_count == 0,"indices_in_bounds":inspection.invalid_index_count == 0,"no_degenerate_triangles":inspection.degenerate_triangle_count == 0,"part_lineage":inspection.part_coverage == 1.0,"budget":artifact.triangle_count > 0},
                "triangle_count":inspection.triangle_count,
                "part_ids":inspection.part_ids,
                "hard_gate_passed":hard_gate_passed
            })
        };
        if is_v2 {
            quality_report["canonical_sha256"] =
                Value::String(canonical_json_hash(&quality_report));
            validate_geometry_quality_report_v2_output(&quality_report)?;
        }
        let quality_bytes = canonical_json_bytes(&quality_report)
            .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
        let quality_object = self.put_object(
            &quality_bytes,
            None,
            "application/json",
            "geometry-quality-report",
        )?;
        let quality_report_id = if is_v2 {
            quality_report_id
        } else {
            format!("quality-geometry-{}", &quality_object.record.sha256[..32])
        };
        let candidate = if is_v2 {
            let program_object = geometry_program_object.as_ref().expect("V2 program object");
            let evidence = geometry_candidate_evidence_value(
                &prepared.candidate,
                reference_id.as_deref(),
                reference_sha256.as_deref(),
                &inspection,
                &program_object.record.sha256,
                &glb_object.record.sha256,
                &readback_object
                    .as_ref()
                    .expect("V2 readback object")
                    .record
                    .sha256,
                &quality_object.record.sha256,
                &quality_report_id,
            );
            validate_geometry_candidate_evidence_output(&evidence)?;
            let evidence: GeometryCandidateEvidenceRecord = serde_json::from_value(evidence)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
            self.store
                .record_geometry_candidate_evidence_and_mark_quality(
                    &evidence,
                    hard_gate_passed,
                    &now_string(),
                )?
        } else {
            self.mark_candidate_quality(
                &prepared.candidate.candidate_id,
                &quality_report_id,
                hard_gate_passed,
            )?
        };
        if is_v2 {
            let result = json!({
                "schema_version":"GeometryPrepareResult@2",
                "candidate":candidate,
                "job":prepared.job,
                "operator_catalog":operator_catalog(),
                "artifact":readback
            });
            validate_geometry_prepare_result_v2_output(&result)?;
            Ok(result)
        } else {
            Ok(json!({
                "schema_version":"GeometryPrepareResult@1",
                "candidate":candidate,
                "job":prepared.job,
                "artifact":readback
            }))
        }
    }

    fn load_modifier_apply_plan(
        &self,
        project_id: &str,
        base_version_id: Option<&str>,
        idempotency_key: &str,
        request: &Value,
        expected_apply_sha256: &str,
    ) -> Result<ModifierApplyPlan, RuntimeError> {
        const MAX_JSON_BYTES: usize = 1024 * 1024;
        let object = exact_object(
            request,
            &[
                "schema_version",
                "project_id",
                "source_candidate_id",
                "source_candidate_canonical_sha256",
                "source_artifact_sha256",
                "source_artifact_readback_sha256",
                "source_geometry_program_sha256",
                "source_operator_catalog_sha256",
                "source_readback_config_sha256",
                "source_part_id",
                "base_version_id",
                "modifiers",
                "idempotency_key",
                "max_response_bytes",
                "input_sha256",
            ],
            "GeometryModifierApplyRequest@1",
        )?;
        if object.get("schema_version").and_then(Value::as_str)
            != Some("GeometryModifierApplyRequest@1")
            || object.get("max_response_bytes").and_then(Value::as_u64)
                != Some(MAX_JSON_BYTES as u64)
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_INVALID: schema or response budget differs".to_owned(),
            ));
        }
        let nested_project_id = required_value_id(object.get("project_id"), "project_id")?;
        if nested_project_id != project_id {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SCOPE_DENIED: nested project differs".to_owned(),
            ));
        }
        let nested_base_version_id = match object.get("base_version_id") {
            Some(Value::Null) => None,
            Some(Value::String(value)) => {
                validate_id(value)?;
                Some(value.as_str())
            }
            _ => {
                return Err(RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_INVALID: base_version_id must be an identifier or null"
                        .to_owned(),
                ));
            }
        };
        if nested_base_version_id != base_version_id {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SCOPE_DENIED: nested base_version_id differs".to_owned(),
            ));
        }
        let nested_idempotency_key =
            required_value_id(object.get("idempotency_key"), "idempotency_key")?;
        if nested_idempotency_key != idempotency_key {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SCOPE_DENIED: nested idempotency_key differs".to_owned(),
            ));
        }
        let input_sha256 = required_value_sha(object.get("input_sha256"), "input_sha256")?;
        let mut input_binding = Value::Object(object.clone());
        input_binding
            .as_object_mut()
            .expect("request clone is an object")
            .remove("input_sha256");
        let expected_input_sha256 = canonical_json_hash(&input_binding);
        if input_sha256 != expected_input_sha256 {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_INPUT_HASH_MISMATCH".to_owned(),
            ));
        }
        if !is_sha256(expected_apply_sha256)
            || canonical_json_hash(request) != expected_apply_sha256
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_REQUEST_HASH_MISMATCH".to_owned(),
            ));
        }

        let source_candidate_id =
            required_value_id(object.get("source_candidate_id"), "source_candidate_id")?;
        let source_candidate_canonical_sha256 = required_value_sha(
            object.get("source_candidate_canonical_sha256"),
            "source_candidate_canonical_sha256",
        )?;
        let source_artifact_sha256 = required_value_sha(
            object.get("source_artifact_sha256"),
            "source_artifact_sha256",
        )?;
        let source_artifact_readback_sha256 = required_value_sha(
            object.get("source_artifact_readback_sha256"),
            "source_artifact_readback_sha256",
        )?;
        let source_geometry_program_sha256 = required_value_sha(
            object.get("source_geometry_program_sha256"),
            "source_geometry_program_sha256",
        )?;
        let source_operator_catalog_sha256 = required_value_sha(
            object.get("source_operator_catalog_sha256"),
            "source_operator_catalog_sha256",
        )?;
        let source_readback_config_sha256 = required_value_sha(
            object.get("source_readback_config_sha256"),
            "source_readback_config_sha256",
        )?;
        let source_part_id = required_value_id(object.get("source_part_id"), "source_part_id")?;

        let source_candidate = self.candidate(source_candidate_id)?.ok_or_else(|| {
            RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SOURCE_CANDIDATE_NOT_FOUND".to_owned(),
            )
        })?;
        if source_candidate.project_id != project_id
            || source_candidate.prepared_object_sha256.as_deref() != Some(source_artifact_sha256)
            || !source_candidate.quality_hard_gate_passed
            || !matches!(source_candidate.state.as_str(), "reviewable" | "confirmed")
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SOURCE_CANDIDATE_INVALID".to_owned(),
            ));
        }
        let mut candidate_value = serde_json::to_value(&source_candidate).map_err(|error| {
            RuntimeError::InvalidInput(format!(
                "GEOMETRY_MODIFIER_APPLY_SOURCE_CANDIDATE_INVALID: {error}"
            ))
        })?;
        let declared_candidate_hash = candidate_value
            .get("canonical_sha256")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_owned();
        candidate_value["canonical_sha256"] = Value::String(String::new());
        if declared_candidate_hash != source_candidate_canonical_sha256
            || canonical_json_hash(&candidate_value) != source_candidate_canonical_sha256
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SOURCE_CANDIDATE_CANONICAL_MISMATCH".to_owned(),
            ));
        }

        let source_evidence = self
            .store
            .get_geometry_candidate_evidence(source_candidate_id)?
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_SOURCE_EVIDENCE_NOT_FOUND".to_owned(),
                )
            })?;
        let source_evidence_value = serde_json::to_value(&source_evidence).map_err(|error| {
            RuntimeError::InvalidInput(format!(
                "GEOMETRY_MODIFIER_APPLY_SOURCE_EVIDENCE_INVALID: {error}"
            ))
        })?;
        validate_geometry_candidate_evidence_output(&source_evidence_value)?;
        if source_evidence.project_id != project_id
            || source_evidence.candidate_id != source_candidate_id
            || source_evidence.artifact_object_sha256 != source_artifact_sha256
            || source_evidence.geometry_program_sha256 != source_geometry_program_sha256
            || source_evidence.operator_catalog_sha256 != source_operator_catalog_sha256
            || source_evidence.readback_config_sha256 != source_readback_config_sha256
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SOURCE_EVIDENCE_BINDING_MISMATCH".to_owned(),
            ));
        }

        let artifact_record = self
            .store
            .get_object(source_artifact_sha256)?
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_SOURCE_ARTIFACT_NOT_FOUND".to_owned(),
                )
            })?;
        if artifact_record.mime != "model/gltf-binary"
            || !matches!(
                artifact_record.kind.as_str(),
                "geometry-glb" | "appearance-glb" | "appearance-v2-glb"
            )
            || artifact_record.reachability != "reachable"
            || artifact_record.size_bytes == 0
            || artifact_record.size_bytes as u64 > MAX_GEOMETRY_ARTIFACT_BYTES
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SOURCE_ARTIFACT_INVALID".to_owned(),
            ));
        }
        let source_artifact_bytes =
            self.cas_read_bounded(source_artifact_sha256, MAX_GEOMETRY_ARTIFACT_BYTES)?;
        if sha256_hex(&source_artifact_bytes) != source_artifact_sha256 {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SOURCE_ARTIFACT_HASH_MISMATCH".to_owned(),
            ));
        }
        let source_inspection = strict_glb_inspection(&source_artifact_bytes)?;
        self.revalidate_v2_geometry_evidence(
            &source_candidate,
            &source_inspection,
            &source_evidence,
        )?;
        let source_readback = self.artifact_readback_bounded(
            source_artifact_sha256,
            source_candidate_id,
            MAX_GEOMETRY_ARTIFACT_BYTES,
        )?;
        if source_readback
            .get("canonical_sha256")
            .and_then(Value::as_str)
            != Some(source_artifact_readback_sha256)
            || source_readback
                .get("program_sha256")
                .and_then(Value::as_str)
                != Some(source_geometry_program_sha256)
            || source_readback
                .get("operator_catalog_sha256")
                .and_then(Value::as_str)
                != Some(source_operator_catalog_sha256)
            || source_readback
                .get("readback_config_sha256")
                .and_then(Value::as_str)
                != Some(source_readback_config_sha256)
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SOURCE_READBACK_BINDING_MISMATCH".to_owned(),
            ));
        }

        let program_record = self
            .store
            .get_object(&source_evidence.geometry_program_object_sha256)?
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_SOURCE_PROGRAM_NOT_FOUND".to_owned(),
                )
            })?;
        if program_record.mime != "application/json"
            || program_record.kind != "geometry-program-v2"
            || program_record.reachability != "reachable"
            || program_record.size_bytes == 0
            || program_record.size_bytes as u64 > MAX_DERIVED_JSON_BYTES
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SOURCE_PROGRAM_INVALID".to_owned(),
            ));
        }
        let program_bytes = self.cas_read_bounded(
            &source_evidence.geometry_program_object_sha256,
            MAX_DERIVED_JSON_BYTES,
        )?;
        let mut source_program: Value =
            serde_json::from_slice(&program_bytes).map_err(|error| {
                RuntimeError::InvalidInput(format!(
                    "GEOMETRY_MODIFIER_APPLY_SOURCE_PROGRAM_INVALID: {error}"
                ))
            })?;
        if source_program.get("canonical_sha256").is_some()
            || source_program.get("schema_version").and_then(Value::as_str)
                != Some("GeometryProgram@2")
            || source_program.get("project_id").and_then(Value::as_str) != Some(project_id)
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SOURCE_PROGRAM_DRAFT_INVALID".to_owned(),
            ));
        }
        let source_program_hash = hash_geometry_program_with_runtime_worker(&source_program)
            .map_err(|error| {
                RuntimeError::InvalidInput(format!(
                    "GEOMETRY_MODIFIER_APPLY_SOURCE_PROGRAM_REJECTED: {error}"
                ))
            })?;
        if source_program_hash
            .get("canonical_sha256")
            .and_then(Value::as_str)
            != Some(source_geometry_program_sha256)
            || source_program_hash
                .get("operator_catalog_sha256")
                .and_then(Value::as_str)
                != Some(source_operator_catalog_sha256)
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SOURCE_PROGRAM_HASH_MISMATCH".to_owned(),
            ));
        }
        source_program["canonical_sha256"] =
            Value::String(source_geometry_program_sha256.to_owned());

        let source_first =
            compile_geometry_with_runtime_worker(&source_program, None).map_err(|error| {
                RuntimeError::InvalidInput(format!(
                    "GEOMETRY_MODIFIER_APPLY_SOURCE_WORKER_REPLAY_FAILED: {error}"
                ))
            })?;
        let source_repeat =
            compile_geometry_with_runtime_worker(&source_program, None).map_err(|error| {
                RuntimeError::InvalidInput(format!(
                    "GEOMETRY_MODIFIER_APPLY_SOURCE_WORKER_REPEAT_FAILED: {error}"
                ))
            })?;
        let expected_cohort = build_cohort_sha256()
            .filter(|value| is_sha256(value))
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_WORKER_COHORT_UNAVAILABLE".to_owned(),
                )
            })?;
        if source_first.glb != source_artifact_bytes
            || source_repeat.glb != source_artifact_bytes
            || source_first.glb != source_repeat.glb
            || source_first.program_sha256 != source_geometry_program_sha256
            || source_repeat.program_sha256 != source_geometry_program_sha256
            || source_first.build_cohort_sha256.as_deref() != Some(expected_cohort.as_str())
            || source_repeat.build_cohort_sha256.as_deref() != Some(expected_cohort.as_str())
            || source_first.part_ids != source_repeat.part_ids
            || source_first.material_zone_ids != source_repeat.material_zone_ids
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SOURCE_WORKER_REPLAY_MISMATCH".to_owned(),
            ));
        }
        validate_worker_metadata(&source_first, &source_inspection)?;

        let nodes = source_program
            .get("nodes")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_SOURCE_PROGRAM_NODES_MISSING".to_owned(),
                )
            })?;
        let part_outputs = source_program
            .get("part_outputs")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_SOURCE_PART_OUTPUTS_MISSING".to_owned(),
                )
            })?;
        let matching_parts = part_outputs
            .iter()
            .filter(|part| part.get("part_id").and_then(Value::as_str) == Some(source_part_id))
            .collect::<Vec<_>>();
        if matching_parts.len() != 1 {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_TARGET_PART_AMBIGUOUS".to_owned(),
            ));
        }
        let target_part = matching_parts[0];
        let target_inputs = target_part
            .get("input_node_ids")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_TARGET_PART_INPUTS_INVALID".to_owned(),
                )
            })?;
        if target_inputs.len() != 1 {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_TARGET_PART_REQUIRES_SINGLE_INPUT".to_owned(),
            ));
        }
        let source_terminal_node_id = target_inputs[0].as_str().ok_or_else(|| {
            RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_TARGET_PART_INPUT_ID_INVALID".to_owned(),
            )
        })?;
        let matching_nodes = nodes
            .iter()
            .filter(|node| {
                node.get("node_id").and_then(Value::as_str) == Some(source_terminal_node_id)
            })
            .collect::<Vec<_>>();
        if matching_nodes.len() != 1 {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_TARGET_NODE_AMBIGUOUS".to_owned(),
            ));
        }
        let source_terminal_node = matching_nodes[0];
        if source_terminal_node
            .get("inputs")
            .and_then(Value::as_array)
            .is_none_or(|inputs| !inputs.is_empty())
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_TARGET_NODE_MUST_BE_DIRECT_SOURCE".to_owned(),
            ));
        }
        if nodes.iter().any(|node| {
            node.get("inputs")
                .and_then(Value::as_array)
                .is_some_and(|inputs| {
                    inputs
                        .iter()
                        .any(|input| input.as_str() == Some(source_terminal_node_id))
                })
        }) || part_outputs.iter().any(|part| {
            part.get("part_id").and_then(Value::as_str) != Some(source_part_id)
                && part
                    .get("input_node_ids")
                    .and_then(Value::as_array)
                    .is_some_and(|inputs| {
                        inputs
                            .iter()
                            .any(|input| input.as_str() == Some(source_terminal_node_id))
                    })
        }) {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_TARGET_NODE_HAS_DOWNSTREAM_CONSUMER".to_owned(),
            ));
        }
        let bindings = source_readback
            .get("part_bindings")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_SOURCE_READBACK_PART_BINDINGS_MISSING".to_owned(),
                )
            })?;
        let exact_binding = bindings
            .iter()
            .filter(|binding| {
                binding.get("part_id").and_then(Value::as_str) == Some(source_part_id)
                    && binding.get("source_node_id").and_then(Value::as_str)
                        == Some(source_terminal_node_id)
                    && binding.get("material_zone_id").and_then(Value::as_str)
                        == target_part.get("material_zone_id").and_then(Value::as_str)
                    && binding.get("solid").and_then(Value::as_bool)
                        == target_part.get("solid").and_then(Value::as_bool)
            })
            .count();
        if exact_binding != 1 {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_SOURCE_PART_BINDING_MISMATCH".to_owned(),
            ));
        }
        let source_part_bindings = bindings.clone();

        let modifiers = object
            .get("modifiers")
            .and_then(Value::as_array)
            .filter(|values| (1..=8).contains(&values.len()))
            .ok_or_else(|| {
                RuntimeError::InvalidInput("GEOMETRY_MODIFIER_APPLY_MODIFIERS_INVALID".to_owned())
            })?
            .clone();
        let representation_plan_sha256 = source_program
            .get("representation_plan_sha256")
            .and_then(Value::as_str)
            .filter(|value| is_sha256(value))
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_SOURCE_PROGRAM_REPRESENTATION_INVALID".to_owned(),
                )
            })?;
        let material_zone_id = target_part
            .get("material_zone_id")
            .and_then(Value::as_str)
            .filter(|value| is_opaque_id(value))
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_TARGET_MATERIAL_ZONE_INVALID".to_owned(),
                )
            })?;
        let solid = target_part
            .get("solid")
            .and_then(Value::as_bool)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_TARGET_SOLID_INVALID".to_owned(),
                )
            })?;
        let mut evaluation_request = json!({
            "schema_version":"GeometryModifierEvaluationRequest@2",
            "project_id":project_id,
            "representation_plan_sha256":representation_plan_sha256,
            "part_id":source_part_id,
            "material_zone_id":material_zone_id,
            "solid":solid,
            "base_node":source_terminal_node,
            "modifiers":modifiers.clone(),
            "previous_evaluation":null,
            "input_sha256":""
        });
        let mut evaluation_input = evaluation_request.clone();
        evaluation_input
            .as_object_mut()
            .expect("internal modifier evaluation request is an object")
            .remove("input_sha256");
        evaluation_request["input_sha256"] = Value::String(canonical_json_hash(&evaluation_input));
        let evaluation = self.geometry_modifier_evaluation_v2(
            evaluation_request
                .as_object()
                .expect("internal modifier evaluation request is an object"),
        )?;
        validate_geometry_modifier_evaluation_result(&evaluation)?;
        let modifier_evaluation_canonical_sha256 = evaluation
            .get("canonical_sha256")
            .and_then(Value::as_str)
            .filter(|value| is_sha256(value))
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_EVALUATION_CANONICAL_INVALID".to_owned(),
                )
            })?
            .to_owned();
        let enabled_count = modifiers
            .iter()
            .filter(|modifier| modifier.get("enabled").and_then(Value::as_bool) == Some(true))
            .count();
        if enabled_count == 0 {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_NO_ENABLED_MODIFIER".to_owned(),
            ));
        }

        let apply_lineage_seed = canonical_json_hash(&json!({
            "schema_version":"GeometryModifierApplyLineage@1",
            "source_candidate_id":source_candidate_id,
            "source_candidate_canonical_sha256":source_candidate_canonical_sha256,
            "source_geometry_program_sha256":source_geometry_program_sha256,
            "source_part_id":source_part_id,
            "source_terminal_node_id":source_terminal_node_id,
            "modifier_apply_request_sha256":expected_apply_sha256,
            "modifier_evaluation_canonical_sha256":modifier_evaluation_canonical_sha256
        }));
        let mut derived_program = source_program.clone();
        derived_program
            .as_object_mut()
            .expect("validated source program")
            .remove("canonical_sha256");
        let derived_nodes = derived_program
            .get_mut("nodes")
            .and_then(Value::as_array_mut)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_DERIVED_NODES_INVALID".to_owned(),
                )
            })?;
        let existing_node_ids = nodes
            .iter()
            .filter_map(|node| node.get("node_id").and_then(Value::as_str))
            .collect::<HashSet<_>>();
        let mut previous_node_id = source_terminal_node_id.to_owned();
        let mut enabled_index = 0usize;
        for modifier in modifiers {
            if modifier.get("enabled").and_then(Value::as_bool) != Some(true) {
                continue;
            }
            let operator_id = modifier
                .get("operator_id")
                .and_then(Value::as_str)
                .ok_or_else(|| {
                    RuntimeError::InvalidInput(
                        "GEOMETRY_MODIFIER_APPLY_MODIFIER_OPERATOR_INVALID".to_owned(),
                    )
                })?;
            if !is_geometry_modifier_operator(Some(operator_id)) {
                return Err(RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_MODIFIER_NOT_ALLOWLISTED".to_owned(),
                ));
            }
            let node_id = format!(
                "modifier-apply-{}-{}",
                &apply_lineage_seed[..16],
                enabled_index
            );
            enabled_index += 1;
            if existing_node_ids.contains(node_id.as_str())
                || derived_nodes.iter().any(|node| {
                    node.get("node_id").and_then(Value::as_str) == Some(node_id.as_str())
                })
            {
                return Err(RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_NODE_ID_COLLISION".to_owned(),
                ));
            }
            derived_nodes.push(json!({
                "node_id":node_id,
                "operator_id":operator_id,
                "inputs":[previous_node_id],
                "parameters":modifier.get("parameters").cloned().ok_or_else(|| RuntimeError::InvalidInput("GEOMETRY_MODIFIER_APPLY_MODIFIER_PARAMETERS_INVALID".to_owned()))?
            }));
            previous_node_id = node_id;
        }
        let derived_outputs = derived_program
            .get_mut("part_outputs")
            .and_then(Value::as_array_mut)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_DERIVED_PART_OUTPUTS_INVALID".to_owned(),
                )
            })?;
        let mut target_replaced = false;
        let mut preserved_part_ids = Vec::new();
        for part in derived_outputs.iter_mut() {
            if part.get("part_id").and_then(Value::as_str) == Some(source_part_id) {
                part["input_node_ids"] = json!([previous_node_id]);
                target_replaced = true;
            } else if let Some(part_id) = part.get("part_id").and_then(Value::as_str) {
                preserved_part_ids.push(part_id.to_owned());
            }
        }
        if !target_replaced {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_TARGET_PART_NOT_REPLACED".to_owned(),
            ));
        }
        let derived_hash =
            hash_geometry_program_with_runtime_worker(&derived_program).map_err(|error| {
                RuntimeError::InvalidInput(format!(
                    "GEOMETRY_MODIFIER_APPLY_DERIVED_PROGRAM_REJECTED: {error}"
                ))
            })?;
        let derived_program_sha256 = derived_hash
            .get("canonical_sha256")
            .and_then(Value::as_str)
            .filter(|value| is_sha256(value))
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_DERIVED_PROGRAM_HASH_INVALID".to_owned(),
                )
            })?;
        if derived_hash
            .get("operator_catalog_sha256")
            .and_then(Value::as_str)
            != Some(source_operator_catalog_sha256)
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_DERIVED_CATALOG_MISMATCH".to_owned(),
            ));
        }
        derived_program["canonical_sha256"] = Value::String(derived_program_sha256.to_owned());

        Ok(ModifierApplyPlan {
            source_reference_id: source_evidence.reference_id.clone(),
            source_reference_sha256: source_evidence.reference_sha256.clone(),
            source_candidate,
            source_evidence,
            source_artifact_sha256: source_artifact_sha256.to_owned(),
            source_artifact_readback_sha256: source_artifact_readback_sha256.to_owned(),
            source_geometry_program_sha256: source_geometry_program_sha256.to_owned(),
            source_operator_catalog_sha256: source_operator_catalog_sha256.to_owned(),
            source_readback_config_sha256: source_readback_config_sha256.to_owned(),
            source_worker_build_cohort_sha256: expected_cohort,
            source_part_id: source_part_id.to_owned(),
            source_material_zone_id: material_zone_id.to_owned(),
            source_solid: solid,
            source_part_bindings,
            source_terminal_node_id: source_terminal_node_id.to_owned(),
            derived_terminal_node_id: previous_node_id,
            preserved_part_ids,
            modifier_apply_request_sha256: expected_apply_sha256.to_owned(),
            modifier_evaluation: evaluation,
            derived_program,
        })
    }

    fn load_modifier_apply_bevel_v2_plan(
        &self,
        project_id: &str,
        base_version_id: Option<&str>,
        idempotency_key: &str,
        request: &Value,
        expected_apply_sha256: &str,
    ) -> Result<ModifierApplyBevelV2Plan, RuntimeError> {
        const MAX_JSON_BYTES: usize = 1024 * 1024;
        const AUTHORING_TOPOLOGY_POLICY_SHA256: &str =
            "a6fb36a530e49537673b66d65ecb6e4fb4f51ffb3e7d01a0980be71f28cb367d";
        let object = exact_object(
            request,
            &[
                "schema_version",
                "project_id",
                "source_candidate_id",
                "source_candidate_canonical_sha256",
                "source_artifact_sha256",
                "source_artifact_readback_sha256",
                "source_geometry_program_sha256",
                "source_operator_catalog_sha256",
                "source_readback_config_sha256",
                "source_part_id",
                "source_terminal_node_id",
                "source_authoring_topology_sha256",
                "source_edge_id",
                "bevel_m",
                "segments",
                "profile",
                "clamp_overlap",
                "base_version_id",
                "idempotency_key",
                "max_response_bytes",
                "input_sha256",
            ],
            "GeometryModifierApplyRequest@2",
        )?;
        if object.get("schema_version").and_then(Value::as_str)
            != Some("GeometryModifierApplyRequest@2")
            || object.get("max_response_bytes").and_then(Value::as_u64)
                != Some(MAX_JSON_BYTES as u64)
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_INVALID: schema or response budget differs".to_owned(),
            ));
        }
        let nested_project_id = required_value_id(object.get("project_id"), "project_id")?;
        if nested_project_id != project_id {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SCOPE_DENIED: nested project differs".to_owned(),
            ));
        }
        let nested_base_version_id = match object.get("base_version_id") {
            Some(Value::Null) => None,
            Some(Value::String(value)) => {
                validate_id(value)?;
                Some(value.as_str())
            }
            _ => {
                return Err(RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_INVALID: base_version_id must be an identifier or null"
                        .to_owned(),
                ));
            }
        };
        if nested_base_version_id != base_version_id {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SCOPE_DENIED: nested base_version_id differs"
                    .to_owned(),
            ));
        }
        let nested_idempotency_key =
            required_value_id(object.get("idempotency_key"), "idempotency_key")?;
        if nested_idempotency_key != idempotency_key {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SCOPE_DENIED: nested idempotency_key differs"
                    .to_owned(),
            ));
        }
        let input_sha256 = required_value_sha(object.get("input_sha256"), "input_sha256")?;
        let mut input_binding = Value::Object(object.clone());
        input_binding
            .as_object_mut()
            .expect("request clone is an object")
            .remove("input_sha256");
        if input_sha256 != canonical_json_hash(&input_binding) {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_INPUT_HASH_MISMATCH".to_owned(),
            ));
        }
        if !is_sha256(expected_apply_sha256)
            || canonical_json_hash(request) != expected_apply_sha256
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_REQUEST_HASH_MISMATCH".to_owned(),
            ));
        }

        let source_candidate_id =
            required_value_id(object.get("source_candidate_id"), "source_candidate_id")?;
        let source_candidate_canonical_sha256 = required_value_sha(
            object.get("source_candidate_canonical_sha256"),
            "source_candidate_canonical_sha256",
        )?;
        let source_artifact_sha256 = required_value_sha(
            object.get("source_artifact_sha256"),
            "source_artifact_sha256",
        )?;
        let source_artifact_readback_sha256 = required_value_sha(
            object.get("source_artifact_readback_sha256"),
            "source_artifact_readback_sha256",
        )?;
        let source_geometry_program_sha256 = required_value_sha(
            object.get("source_geometry_program_sha256"),
            "source_geometry_program_sha256",
        )?;
        let source_operator_catalog_sha256 = required_value_sha(
            object.get("source_operator_catalog_sha256"),
            "source_operator_catalog_sha256",
        )?;
        let source_readback_config_sha256 = required_value_sha(
            object.get("source_readback_config_sha256"),
            "source_readback_config_sha256",
        )?;
        let source_part_id = required_value_id(object.get("source_part_id"), "source_part_id")?;
        let source_terminal_node_id = required_value_id(
            object.get("source_terminal_node_id"),
            "source_terminal_node_id",
        )?;
        let source_authoring_topology_sha256 = required_value_sha(
            object.get("source_authoring_topology_sha256"),
            "source_authoring_topology_sha256",
        )?;
        let source_edge_id = required_value_id(object.get("source_edge_id"), "source_edge_id")?;
        let bevel_m = object
            .get("bevel_m")
            .and_then(Value::as_f64)
            .filter(|value| value.is_finite() && *value > 0.0 && *value <= 0.25)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_BEVEL_OUT_OF_BOUNDS".to_owned(),
                )
            })?;
        if !(bevel_m as f32).is_finite() || bevel_m as f32 <= 0.0 {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_BEVEL_OUT_OF_BOUNDS".to_owned(),
            ));
        }
        let segments = object
            .get("segments")
            .and_then(Value::as_u64)
            .filter(|value| (1..=4).contains(value))
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_SEGMENTS_OUT_OF_BOUNDS".to_owned(),
                )
            })?;
        let profile = object
            .get("profile")
            .and_then(Value::as_f64)
            .filter(|value| value.is_finite() && (0.25..=0.75).contains(value))
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_PROFILE_OUT_OF_BOUNDS".to_owned(),
                )
            })?;
        if !(profile as f32).is_finite() {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_PROFILE_OUT_OF_BOUNDS".to_owned(),
            ));
        }
        let clamp_overlap = object
            .get("clamp_overlap")
            .and_then(Value::as_bool)
            .ok_or_else(|| {
                RuntimeError::InvalidInput("GEOMETRY_MODIFIER_APPLY_V2_CLAMP_INVALID".to_owned())
            })?;

        let source_candidate = self.candidate(source_candidate_id)?.ok_or_else(|| {
            RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_CANDIDATE_NOT_FOUND".to_owned(),
            )
        })?;
        if source_candidate.project_id != project_id
            || source_candidate.prepared_object_sha256.as_deref() != Some(source_artifact_sha256)
            || !source_candidate.quality_hard_gate_passed
            || !matches!(source_candidate.state.as_str(), "reviewable" | "confirmed")
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_CANDIDATE_INVALID".to_owned(),
            ));
        }
        let mut candidate_value = serde_json::to_value(&source_candidate).map_err(|error| {
            RuntimeError::InvalidInput(format!(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_CANDIDATE_INVALID: {error}"
            ))
        })?;
        let declared_candidate_hash = candidate_value
            .get("canonical_sha256")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_owned();
        candidate_value["canonical_sha256"] = Value::String(String::new());
        if declared_candidate_hash != source_candidate_canonical_sha256
            || canonical_json_hash(&candidate_value) != source_candidate_canonical_sha256
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_CANDIDATE_CANONICAL_MISMATCH".to_owned(),
            ));
        }

        let source_evidence = self
            .store
            .get_geometry_candidate_evidence(source_candidate_id)?
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_EVIDENCE_NOT_FOUND".to_owned(),
                )
            })?;
        let source_evidence_value = serde_json::to_value(&source_evidence).map_err(|error| {
            RuntimeError::InvalidInput(format!(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_EVIDENCE_INVALID: {error}"
            ))
        })?;
        validate_geometry_candidate_evidence_output(&source_evidence_value)?;
        if source_evidence.project_id != project_id
            || source_evidence.candidate_id != source_candidate_id
            || source_evidence.artifact_object_sha256 != source_artifact_sha256
            || source_evidence.geometry_program_sha256 != source_geometry_program_sha256
            || source_evidence.operator_catalog_sha256 != source_operator_catalog_sha256
            || source_evidence.readback_config_sha256 != source_readback_config_sha256
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_EVIDENCE_BINDING_MISMATCH".to_owned(),
            ));
        }

        let source_readback = self.artifact_readback_bounded(
            source_artifact_sha256,
            source_candidate_id,
            MAX_GEOMETRY_ARTIFACT_BYTES,
        )?;
        if source_readback
            .get("canonical_sha256")
            .and_then(Value::as_str)
            != Some(source_artifact_readback_sha256)
            || source_readback
                .get("program_sha256")
                .and_then(Value::as_str)
                != Some(source_geometry_program_sha256)
            || source_readback
                .get("operator_catalog_sha256")
                .and_then(Value::as_str)
                != Some(source_operator_catalog_sha256)
            || source_readback
                .get("readback_config_sha256")
                .and_then(Value::as_str)
                != Some(source_readback_config_sha256)
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_READBACK_BINDING_MISMATCH".to_owned(),
            ));
        }

        // Delegate all authoring-mesh source replay, direct-node checks and
        // Runtime-owned topology hashing to the existing topology producer.
        let topology_request = json!({
            "schema_version":"AuthoringTopologyRequest@1",
            "project_id":project_id,
            "candidate_id":source_candidate_id,
            "artifact_id":source_artifact_sha256,
            "artifact_readback_sha256":source_artifact_readback_sha256,
            "program_sha256":source_geometry_program_sha256,
            "operator_catalog_sha256":source_operator_catalog_sha256,
            "readback_config_sha256":source_readback_config_sha256,
            "authoring_node_id":source_terminal_node_id,
            "part_id":source_part_id,
            "authoring_topology_policy_sha256":AUTHORING_TOPOLOGY_POLICY_SHA256,
            "max_response_bytes":MAX_JSON_BYTES
        });
        let topology = authoring_topology::get(self, &topology_request).map_err(|error| {
            RuntimeError::InvalidInput(format!(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_TOPOLOGY_INVALID: {error}"
            ))
        })?;
        if topology.get("schema_version").and_then(Value::as_str) != Some("AuthoringTopology@1")
            || topology.get("project_id").and_then(Value::as_str) != Some(project_id)
            || topology.get("candidate_id").and_then(Value::as_str) != Some(source_candidate_id)
            || topology.get("artifact_id").and_then(Value::as_str) != Some(source_artifact_sha256)
            || topology.get("authoring_node_id").and_then(Value::as_str)
                != Some(source_terminal_node_id)
            || topology.get("part_id").and_then(Value::as_str) != Some(source_part_id)
            || topology.get("topology_sha256").and_then(Value::as_str)
                != Some(source_authoring_topology_sha256)
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_TOPOLOGY_BINDING_MISMATCH".to_owned(),
            ));
        }
        let topology_edges = topology
            .get("edges")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_TOPOLOGY_EDGES_MISSING".to_owned(),
                )
            })?;
        if topology_edges
            .iter()
            .filter(|edge| edge.get("element_id").and_then(Value::as_str) == Some(source_edge_id))
            .count()
            != 1
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_EDGE_NOT_FOUND".to_owned(),
            ));
        }

        let artifact_bytes =
            self.cas_read_bounded(source_artifact_sha256, MAX_GEOMETRY_ARTIFACT_BYTES)?;
        if sha256_hex(&artifact_bytes) != source_artifact_sha256 {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_ARTIFACT_HASH_MISMATCH".to_owned(),
            ));
        }
        let source_inspection = strict_glb_inspection(&artifact_bytes)?;
        let program_record = self
            .store
            .get_object(&source_evidence.geometry_program_object_sha256)?
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_PROGRAM_NOT_FOUND".to_owned(),
                )
            })?;
        if program_record.mime != "application/json"
            || program_record.kind != "geometry-program-v2"
            || program_record.reachability != "reachable"
            || program_record.size_bytes == 0
            || program_record.size_bytes as u64 > MAX_DERIVED_JSON_BYTES
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_PROGRAM_INVALID".to_owned(),
            ));
        }
        let program_bytes = self.cas_read_bounded(
            &source_evidence.geometry_program_object_sha256,
            MAX_DERIVED_JSON_BYTES,
        )?;
        let mut source_program: Value =
            serde_json::from_slice(&program_bytes).map_err(|error| {
                RuntimeError::InvalidInput(format!(
                    "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_PROGRAM_INVALID: {error}"
                ))
            })?;
        if source_program.get("canonical_sha256").is_some()
            || source_program.get("schema_version").and_then(Value::as_str)
                != Some("GeometryProgram@2")
            || source_program.get("project_id").and_then(Value::as_str) != Some(project_id)
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_PROGRAM_DRAFT_INVALID".to_owned(),
            ));
        }
        let source_program_hash = hash_geometry_program_with_runtime_worker(&source_program)
            .map_err(|error| {
                RuntimeError::InvalidInput(format!(
                    "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_PROGRAM_REJECTED: {error}"
                ))
            })?;
        if source_program_hash
            .get("canonical_sha256")
            .and_then(Value::as_str)
            != Some(source_geometry_program_sha256)
            || source_program_hash
                .get("operator_catalog_sha256")
                .and_then(Value::as_str)
                != Some(source_operator_catalog_sha256)
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_PROGRAM_HASH_MISMATCH".to_owned(),
            ));
        }
        source_program["canonical_sha256"] =
            Value::String(source_geometry_program_sha256.to_owned());
        let source_first =
            compile_geometry_with_runtime_worker(&source_program, None).map_err(|error| {
                RuntimeError::InvalidInput(format!(
                    "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_WORKER_REPLAY_FAILED: {error}"
                ))
            })?;
        let source_repeat =
            compile_geometry_with_runtime_worker(&source_program, None).map_err(|error| {
                RuntimeError::InvalidInput(format!(
                    "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_WORKER_REPEAT_FAILED: {error}"
                ))
            })?;
        let expected_cohort = build_cohort_sha256()
            .filter(|value| is_sha256(value))
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_WORKER_COHORT_UNAVAILABLE".to_owned(),
                )
            })?;
        if source_first.glb != artifact_bytes
            || source_repeat.glb != artifact_bytes
            || source_first.glb != source_repeat.glb
            || source_first.program_sha256 != source_geometry_program_sha256
            || source_repeat.program_sha256 != source_geometry_program_sha256
            || source_first.build_cohort_sha256.as_deref() != Some(expected_cohort.as_str())
            || source_repeat.build_cohort_sha256.as_deref() != Some(expected_cohort.as_str())
            || source_first.part_ids != source_repeat.part_ids
            || source_first.material_zone_ids != source_repeat.material_zone_ids
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_WORKER_REPLAY_MISMATCH".to_owned(),
            ));
        }
        validate_worker_metadata(&source_first, &source_inspection)?;

        let nodes = source_program
            .get("nodes")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_PROGRAM_NODES_MISSING".to_owned(),
                )
            })?;
        let part_outputs = source_program
            .get("part_outputs")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_PART_OUTPUTS_MISSING".to_owned(),
                )
            })?;
        let target_part = part_outputs
            .iter()
            .find(|part| part.get("part_id").and_then(Value::as_str) == Some(source_part_id))
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_TARGET_PART_NOT_FOUND".to_owned(),
                )
            })?;
        let target_inputs = target_part
            .get("input_node_ids")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_TARGET_PART_INPUTS_INVALID".to_owned(),
                )
            })?;
        if target_inputs.len() != 1 || target_inputs[0].as_str() != Some(source_terminal_node_id) {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_TERMINAL_BINDING_MISMATCH".to_owned(),
            ));
        }
        let source_terminal_node = nodes
            .iter()
            .find(|node| {
                node.get("node_id").and_then(Value::as_str) == Some(source_terminal_node_id)
            })
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_TERMINAL_NOT_FOUND".to_owned(),
                )
            })?;
        if source_terminal_node
            .get("operator_id")
            .and_then(Value::as_str)
            != Some("forgecad.geometry.authoring-mesh@1")
            || source_terminal_node
                .get("inputs")
                .and_then(Value::as_array)
                .is_none_or(|inputs| !inputs.is_empty())
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_TERMINAL_MUST_BE_DIRECT_AUTHORING_MESH"
                    .to_owned(),
            ));
        }
        if nodes.iter().any(|node| {
            node.get("inputs")
                .and_then(Value::as_array)
                .is_some_and(|inputs| {
                    inputs
                        .iter()
                        .any(|input| input.as_str() == Some(source_terminal_node_id))
                })
        }) || part_outputs.iter().any(|part| {
            part.get("part_id").and_then(Value::as_str) != Some(source_part_id)
                && part
                    .get("input_node_ids")
                    .and_then(Value::as_array)
                    .is_some_and(|inputs| {
                        inputs
                            .iter()
                            .any(|input| input.as_str() == Some(source_terminal_node_id))
                    })
        }) {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_TERMINAL_HAS_DOWNSTREAM_CONSUMER".to_owned(),
            ));
        }
        let source_material_zone_id = target_part
            .get("material_zone_id")
            .and_then(Value::as_str)
            .filter(|value| is_opaque_id(value))
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_TARGET_MATERIAL_ZONE_INVALID".to_owned(),
                )
            })?;
        let source_solid = target_part
            .get("solid")
            .and_then(Value::as_bool)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_TARGET_SOLID_INVALID".to_owned(),
                )
            })?;
        let source_part_bindings = source_readback
            .get("part_bindings")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_PART_BINDINGS_MISSING".to_owned(),
                )
            })?
            .clone();
        if source_part_bindings
            .iter()
            .filter(|binding| {
                binding.get("part_id").and_then(Value::as_str) == Some(source_part_id)
                    && binding.get("source_node_id").and_then(Value::as_str)
                        == Some(source_terminal_node_id)
                    && binding.get("material_zone_id").and_then(Value::as_str)
                        == Some(source_material_zone_id)
                    && binding.get("solid").and_then(Value::as_bool) == Some(source_solid)
            })
            .count()
            != 1
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_SOURCE_PART_BINDING_MISMATCH".to_owned(),
            ));
        }

        let bevel_parameters = json!({
            "shape":"bevel",
            "source_edge_ids":[source_edge_id],
            "width_m":object.get("bevel_m").cloned().expect("validated bevel_m"),
            "segments":segments,
            "profile":object.get("profile").cloned().expect("validated profile"),
            "clamp_overlap":clamp_overlap
        });
        let lineage_seed = canonical_json_hash(&json!({
            "schema_version":"GeometryModifierApplyLineage@2",
            "source_candidate_id":source_candidate_id,
            "source_candidate_canonical_sha256":source_candidate_canonical_sha256,
            "source_geometry_program_sha256":source_geometry_program_sha256,
            "source_part_id":source_part_id,
            "source_terminal_node_id":source_terminal_node_id,
            "source_authoring_topology_sha256":source_authoring_topology_sha256,
            "source_edge_id":source_edge_id,
            "modifier_apply_request_sha256":expected_apply_sha256,
            "bevel_parameters":bevel_parameters
        }));
        let derived_terminal_node_id = format!("modifier-apply-bevel-v2-{}", &lineage_seed[..16]);
        if nodes.iter().any(|node| {
            node.get("node_id").and_then(Value::as_str) == Some(derived_terminal_node_id.as_str())
        }) {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_NODE_ID_COLLISION".to_owned(),
            ));
        }
        let mut derived_program = source_program.clone();
        derived_program
            .as_object_mut()
            .expect("validated source program")
            .remove("canonical_sha256");
        derived_program
            .get_mut("nodes")
            .and_then(Value::as_array_mut)
            .expect("validated source nodes")
            .push(json!({
                "node_id":derived_terminal_node_id,
                "operator_id":"forgecad.geometry.bevel@2",
                "inputs":[source_terminal_node_id],
                "parameters":bevel_parameters
            }));
        let derived_outputs = derived_program
            .get_mut("part_outputs")
            .and_then(Value::as_array_mut)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_DERIVED_PART_OUTPUTS_INVALID".to_owned(),
                )
            })?;
        let mut target_replaced = false;
        let mut preserved_part_ids = Vec::new();
        for part in derived_outputs.iter_mut() {
            if part.get("part_id").and_then(Value::as_str) == Some(source_part_id) {
                if target_replaced {
                    return Err(RuntimeError::InvalidInput(
                        "GEOMETRY_MODIFIER_APPLY_V2_TARGET_PART_AMBIGUOUS".to_owned(),
                    ));
                }
                part["input_node_ids"] = json!([derived_terminal_node_id]);
                target_replaced = true;
            } else if let Some(part_id) = part.get("part_id").and_then(Value::as_str) {
                preserved_part_ids.push(part_id.to_owned());
            }
        }
        if !target_replaced {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_TARGET_PART_NOT_REPLACED".to_owned(),
            ));
        }
        let derived_hash =
            hash_geometry_program_with_runtime_worker(&derived_program).map_err(|error| {
                RuntimeError::InvalidInput(format!(
                    "GEOMETRY_MODIFIER_APPLY_V2_DERIVED_PROGRAM_REJECTED: {error}"
                ))
            })?;
        let derived_program_sha256 = derived_hash
            .get("canonical_sha256")
            .and_then(Value::as_str)
            .filter(|value| is_sha256(value))
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_V2_DERIVED_PROGRAM_HASH_INVALID".to_owned(),
                )
            })?;
        if derived_hash
            .get("operator_catalog_sha256")
            .and_then(Value::as_str)
            != Some(source_operator_catalog_sha256)
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_MODIFIER_APPLY_V2_DERIVED_CATALOG_MISMATCH".to_owned(),
            ));
        }
        derived_program["canonical_sha256"] = Value::String(derived_program_sha256.to_owned());

        Ok(ModifierApplyBevelV2Plan {
            source_reference_id: source_evidence.reference_id.clone(),
            source_reference_sha256: source_evidence.reference_sha256.clone(),
            source_candidate,
            source_evidence,
            source_artifact_sha256: source_artifact_sha256.to_owned(),
            source_artifact_readback_sha256: source_artifact_readback_sha256.to_owned(),
            source_geometry_program_sha256: source_geometry_program_sha256.to_owned(),
            source_operator_catalog_sha256: source_operator_catalog_sha256.to_owned(),
            source_readback_config_sha256: source_readback_config_sha256.to_owned(),
            source_worker_build_cohort_sha256: expected_cohort,
            source_part_id: source_part_id.to_owned(),
            source_material_zone_id: source_material_zone_id.to_owned(),
            source_solid,
            source_part_bindings,
            source_terminal_node_id: source_terminal_node_id.to_owned(),
            derived_terminal_node_id,
            preserved_part_ids,
            source_authoring_topology_sha256: source_authoring_topology_sha256.to_owned(),
            source_edge_id: source_edge_id.to_owned(),
            bevel_parameters,
            modifier_apply_request_sha256: expected_apply_sha256.to_owned(),
            derived_program,
        })
    }

    /// Strict GeometryProgram@2 prepare with an explicit nullable head and a
    /// Runtime/Store-owned exact idempotency transaction. The legacy method
    /// above intentionally remains unchanged for callers that omit an
    /// idempotency key.
    pub fn prepare_geometry_candidate_exact(
        &self,
        project_id: &str,
        base_version_id: Option<&str>,
        idempotency_key: &str,
        request: Value,
    ) -> Result<Value, RuntimeError> {
        const TOOL: &str = "geometry_prepare";
        const MAX_JSON_BYTES: usize = 1024 * 1024;

        validate_id(project_id)?;
        validate_id(idempotency_key)?;
        if let Some(base_version_id) = base_version_id {
            validate_id(base_version_id)?;
        }
        let object = request.as_object().ok_or_else(|| {
            RuntimeError::InvalidInput("geometry request must be an object".to_owned())
        })?;
        if object.keys().any(|key| {
            !matches!(
                key.as_str(),
                "typed"
                    | "reference_id"
                    | "geometry_program"
                    | "modifier_evaluation_request"
                    | "modifier_evaluation_sha256"
                    | "modifier_apply_request"
                    | "modifier_apply_sha256"
                    | "modifier_apply_request_v2"
                    | "modifier_apply_request_v2_sha256"
            )
        }) {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_REJECTED: geometry request contains an unsupported field".to_owned(),
            ));
        }
        if object.get("typed").and_then(Value::as_str) != Some("geometry") {
            return Err(RuntimeError::InvalidInput(
                "geometry request requires typed=geometry".to_owned(),
            ));
        }
        let has_program = object.contains_key("geometry_program");
        let has_modifier_evaluation = object.contains_key("modifier_evaluation_request");
        let has_modifier_evaluation_sha256 = object.contains_key("modifier_evaluation_sha256");
        let has_modifier_apply = object.contains_key("modifier_apply_request");
        let has_modifier_apply_sha256 = object.contains_key("modifier_apply_sha256");
        let has_modifier_apply_v2 = object.contains_key("modifier_apply_request_v2");
        let has_modifier_apply_v2_sha256 = object.contains_key("modifier_apply_request_v2_sha256");
        let modifier_apply_v2_nested = object
            .get("modifier_apply_request")
            .and_then(|value| value.get("schema_version"))
            .and_then(Value::as_str)
            == Some("GeometryModifierApplyRequest@2");
        let direct_program_shape = has_program
            && !has_modifier_evaluation
            && !has_modifier_evaluation_sha256
            && !has_modifier_apply
            && !has_modifier_apply_sha256
            && !has_modifier_apply_v2
            && !has_modifier_apply_v2_sha256;
        let modifier_evaluation_shape = !has_program
            && has_modifier_evaluation
            && has_modifier_evaluation_sha256
            && !has_modifier_apply
            && !has_modifier_apply_sha256
            && !has_modifier_apply_v2
            && !has_modifier_apply_v2_sha256;
        let modifier_apply_shape = !has_program
            && !has_modifier_evaluation
            && !has_modifier_evaluation_sha256
            && has_modifier_apply
            && has_modifier_apply_sha256
            && !modifier_apply_v2_nested
            && !has_modifier_apply_v2
            && !has_modifier_apply_v2_sha256;
        let modifier_apply_bevel_v2_shape = !has_program
            && !has_modifier_evaluation
            && !has_modifier_evaluation_sha256
            && ((has_modifier_apply_v2
                && has_modifier_apply_v2_sha256
                && !has_modifier_apply
                && !has_modifier_apply_sha256)
                || (has_modifier_apply
                    && has_modifier_apply_sha256
                    && modifier_apply_v2_nested
                    && !has_modifier_apply_v2
                    && !has_modifier_apply_v2_sha256));
        if !direct_program_shape
            && !modifier_evaluation_shape
            && !modifier_apply_shape
            && !modifier_apply_bevel_v2_shape
        {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_EXACT_INPUT_REQUIRED: exact prepare requires exactly one of geometry_program, modifier_evaluation_request, modifier_apply_request or modifier_apply_request_v2"
                    .to_owned(),
            ));
        }

        let request_envelope = json!({
            "project_id":project_id,
            "tool":TOOL,
            "base_version_id_present":true,
            "base_version_id":base_version_id,
            "request":request.clone(),
        });
        let request_bytes = canonical_json_bytes(&request_envelope)
            .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
        if request_bytes.is_empty() || request_bytes.len() > MAX_JSON_BYTES {
            return Err(RuntimeError::InvalidInput(
                "GEOMETRY_PREPARE_REQUEST_TOO_LARGE: exact request exceeds 1 MiB".to_owned(),
            ));
        }
        let request_sha256 = sha256_hex(&request_bytes);
        if let Some(stored_response) = self.store.geometry_prepare_idempotency_response(
            project_id,
            TOOL,
            idempotency_key,
            &request_sha256,
        )? {
            let stored: Value = serde_json::from_str(&stored_response).map_err(|error| {
                RuntimeError::InvalidInput(format!(
                    "GEOMETRY_PREPARE_RESPONSE_INVALID: stored response is invalid: {error}"
                ))
            })?;
            validate_geometry_prepare_result_v2_output(&stored)?;
            return Ok(stored);
        }

        let single_flight = self.store.begin_geometry_prepare_single_flight(
            project_id,
            TOOL,
            idempotency_key,
            &request_sha256,
        )?;
        if !single_flight.is_owner() {
            return match self
                .store
                .wait_geometry_prepare_single_flight(&single_flight)?
            {
                GeometryPrepareSingleFlightOutcome::Committed(response_json) => {
                    let stored: Value = serde_json::from_str(&response_json).map_err(|error| {
                        RuntimeError::InvalidInput(format!(
                            "GEOMETRY_PREPARE_RESPONSE_INVALID: single-flight response is invalid: {error}"
                        ))
                    })?;
                    validate_geometry_prepare_result_v2_output(&stored)?;
                    Ok(stored)
                }
                GeometryPrepareSingleFlightOutcome::Failed(message) => {
                    Err(RuntimeError::InvalidInput(message))
                }
            };
        }
        let cas_reservation = self.store.begin_cas_reservation();

        let owner_result = (|| -> Result<Value, RuntimeError> {
            self.project(project_id)?.ok_or_else(|| {
                RuntimeError::InvalidInput("PROJECT_SCOPE_DENIED: project not found".to_owned())
            })?;
            let current_head_version_id = self
                .store
                .latest_version_for_project(project_id)?
                .map(|version| version.version_id);
            if current_head_version_id.as_deref() != base_version_id {
                return Err(RuntimeError::InvalidInput(
                    "STALE_HEAD: exact base_version_id is not the current project head".to_owned(),
                ));
            }

            let modifier_apply_plan = if modifier_apply_shape {
                let apply_request = object.get("modifier_apply_request").ok_or_else(|| {
                    RuntimeError::InvalidInput(
                        "GEOMETRY_MODIFIER_APPLY_INVALID: modifier_apply_request is required"
                            .to_owned(),
                    )
                })?;
                let expected_apply_sha256 = required_value_sha(
                    object.get("modifier_apply_sha256"),
                    "modifier_apply_sha256",
                )?;
                Some(self.load_modifier_apply_plan(
                    project_id,
                    base_version_id,
                    idempotency_key,
                    apply_request,
                    expected_apply_sha256,
                )?)
            } else {
                None
            };
            let modifier_apply_bevel_v2_plan = if modifier_apply_bevel_v2_shape {
                let apply_request = object
                    .get("modifier_apply_request_v2")
                    .or_else(|| object.get("modifier_apply_request"))
                    .ok_or_else(|| {
                        RuntimeError::InvalidInput(
                        "GEOMETRY_MODIFIER_APPLY_V2_INVALID: modifier_apply_request_v2 is required"
                            .to_owned(),
                    )
                    })?;
                let (apply_sha256_value, apply_sha256_key) = if has_modifier_apply_v2 {
                    (
                        object.get("modifier_apply_request_v2_sha256"),
                        "modifier_apply_request_v2_sha256",
                    )
                } else {
                    (object.get("modifier_apply_sha256"), "modifier_apply_sha256")
                };
                let expected_apply_sha256 =
                    required_value_sha(apply_sha256_value, apply_sha256_key)?;
                Some(self.load_modifier_apply_bevel_v2_plan(
                    project_id,
                    base_version_id,
                    idempotency_key,
                    apply_request,
                    expected_apply_sha256,
                )?)
            } else {
                None
            };

            let (reference_id, reference_sha256) = match object.get("reference_id") {
                None if modifier_apply_plan.is_some() || modifier_apply_bevel_v2_plan.is_some() => {
                    if let Some(plan) = modifier_apply_bevel_v2_plan.as_ref() {
                        (
                            plan.source_reference_id.clone(),
                            plan.source_reference_sha256.clone(),
                        )
                    } else {
                        (
                            modifier_apply_plan
                                .as_ref()
                                .and_then(|plan| plan.source_reference_id.clone()),
                            modifier_apply_plan
                                .as_ref()
                                .and_then(|plan| plan.source_reference_sha256.clone()),
                        )
                    }
                }
                None => (None, None),
                Some(Value::String(_))
                    if modifier_apply_plan.is_some() || modifier_apply_bevel_v2_plan.is_some() =>
                {
                    return Err(RuntimeError::InvalidInput(
                        "GEOMETRY_MODIFIER_APPLY_REFERENCE_MUST_COME_FROM_SOURCE_CANDIDATE"
                            .to_owned(),
                    ));
                }
                Some(Value::String(reference_id)) => {
                    let reference = self.reference(reference_id)?.ok_or_else(|| {
                        RuntimeError::InvalidInput("NOT_FOUND: reference not found".to_owned())
                    })?;
                    if reference.project_id != project_id {
                        return Err(RuntimeError::InvalidInput(
                        "REFERENCE_SCOPE_DENIED: geometry reference is outside the target project"
                            .to_owned(),
                    ));
                    }
                    (Some(reference.reference_id), Some(reference.object_sha256))
                }
                Some(_) => {
                    return Err(RuntimeError::InvalidInput(
                        "GEOMETRY_REJECTED: reference_id must be an identifier".to_owned(),
                    ));
                }
            };

            // The exact request hash above binds the caller's complete authoring
            // intent before any Worker call. A modifier apply is a one-call
            // lowering of the already-closed read-only v2 evaluation request into
            // the same GeometryProgram@2 staging transaction; it is not a second
            // candidate writer or a Blender/Python execution path.
            let (program, modifier_evaluation) = if let Some(program) =
                object.get("geometry_program")
            {
                if program.get("schema_version").and_then(Value::as_str)
                    != Some("GeometryProgram@2")
                {
                    return Err(RuntimeError::InvalidInput(
                    "GEOMETRY_EXACT_V2_REQUIRED: exact geometry prepare accepts GeometryProgram@2 only"
                        .to_owned(),
                ));
                }
                (program.clone(), None)
            } else if modifier_evaluation_shape {
                let modifier_request = object
                .get("modifier_evaluation_request")
                .and_then(Value::as_object)
                .ok_or_else(|| {
                    RuntimeError::InvalidInput(
                        "GEOMETRY_MODIFIER_APPLY_INVALID: modifier_evaluation_request must be an object"
                            .to_owned(),
                    )
                })?;
                if modifier_request.get("project_id").and_then(Value::as_str) != Some(project_id) {
                    return Err(RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_SCOPE_DENIED: modifier request project_id must match the target project"
                        .to_owned(),
                ));
                }
                let evaluation = self.geometry_modifier_evaluation_v2(modifier_request)?;
                validate_geometry_modifier_evaluation_result(&evaluation)?;
                let expected_evaluation_sha256 = required_value_sha(
                    object.get("modifier_evaluation_sha256"),
                    "modifier_evaluation_sha256",
                )?;
                if evaluation.get("canonical_sha256").and_then(Value::as_str)
                    != Some(expected_evaluation_sha256)
                {
                    return Err(RuntimeError::InvalidInput(
                    "GEOMETRY_MODIFIER_APPLY_EVALUATION_MISMATCH: Runtime evaluation differs from the caller-bound canonical result"
                        .to_owned(),
                ));
                }
                let program = evaluation.get("geometry_program").cloned().ok_or_else(|| {
                    RuntimeError::InvalidInput(
                        "GEOMETRY_MODIFIER_APPLY_INVALID: evaluation omitted GeometryProgram@2"
                            .to_owned(),
                    )
                })?;
                (program, Some(evaluation))
            } else if let Some(plan) = modifier_apply_bevel_v2_plan.as_ref() {
                (plan.derived_program.clone(), None)
            } else {
                let plan = modifier_apply_plan.as_ref().ok_or_else(|| {
                    RuntimeError::InvalidInput(
                        "GEOMETRY_MODIFIER_APPLY_INVALID: source plan is unavailable".to_owned(),
                    )
                })?;
                (plan.derived_program.clone(), None)
            };
            if program.get("project_id").and_then(Value::as_str) != Some(project_id) {
                return Err(RuntimeError::InvalidInput(
                    "GEOMETRY_REJECTED: GeometryProgram project_id must match the target project"
                        .to_owned(),
                ));
            }

            let first = geometry_worker::compile_geometry(&program, None).map_err(|error| {
                RuntimeError::InvalidInput(format!("GEOMETRY_REJECTED: {error}"))
            })?;
            let repeat = geometry_worker::compile_geometry(&program, None).map_err(|error| {
                RuntimeError::InvalidInput(format!("GEOMETRY_REJECTED: {error}"))
            })?;
            let expected_cohort = build_cohort_sha256()
                .filter(|value| is_sha256(value))
                .ok_or_else(|| {
                    RuntimeError::InvalidInput(
                        "GEOMETRY_WORKER_COHORT_UNAVAILABLE: exact prepare requires a build cohort"
                            .to_owned(),
                    )
                })?;
            if first.build_cohort_sha256.as_deref() != Some(expected_cohort.as_str())
                || repeat.build_cohort_sha256.as_deref() != Some(expected_cohort.as_str())
                || first.build_cohort_sha256 != repeat.build_cohort_sha256
                || first.glb != repeat.glb
                || first.part_ids != repeat.part_ids
                || first.triangle_count != repeat.triangle_count
                || first.program_sha256 != repeat.program_sha256
                || first.uv_status != repeat.uv_status
                || first.tangent_status != repeat.tangent_status
                || first.material_zone_ids != repeat.material_zone_ids
            {
                return Err(RuntimeError::InvalidInput(
                "GEOMETRY_WORKER_REPLAY_MISMATCH: exact prepare requires byte-exact same-cohort replay"
                    .to_owned(),
            ));
            }
            let inspection = strict_glb_inspection(&first.glb)?;
            let repeat_inspection = strict_glb_inspection(&repeat.glb)?;
            validate_worker_metadata(&first, &inspection)?;
            validate_worker_metadata(&repeat, &repeat_inspection)?;
            let replay_artifact_sha256 = sha256_hex(&first.glb);
            if artifact_readback_v2_value(
                &replay_artifact_sha256,
                "candidate-replay-check",
                &inspection,
                first.glb.len() as u64,
            ) != artifact_readback_v2_value(
                &replay_artifact_sha256,
                "candidate-replay-check",
                &repeat_inspection,
                repeat.glb.len() as u64,
            ) {
                return Err(RuntimeError::InvalidInput(
                    "GEOMETRY_WORKER_REPLAY_MISMATCH: strict readback projections differ"
                        .to_owned(),
                ));
            }
            if !inspection.hard_gate_passed
                || inspection.program_sha256 != repeat_inspection.program_sha256
                || inspection.operator_catalog_sha256 != repeat_inspection.operator_catalog_sha256
                || inspection.readback_config_sha256 != repeat_inspection.readback_config_sha256
            {
                return Err(RuntimeError::InvalidInput(format!(
                    "GEOMETRY_REJECTED: strict GLB replay/readback failed: {}",
                    inspection.failure_codes.join(",")
                )));
            }
            if let Some(plan) = modifier_apply_plan.as_ref() {
                let mut source_part_ids = HashSet::new();
                for source_binding in &plan.source_part_bindings {
                    let source_part_id = source_binding
                        .get("part_id")
                        .and_then(Value::as_str)
                        .filter(|value| is_opaque_id(value))
                        .ok_or_else(|| {
                            RuntimeError::InvalidInput(
                                "GEOMETRY_MODIFIER_APPLY_SOURCE_BINDING_INVALID".to_owned(),
                            )
                        })?;
                    if !source_part_ids.insert(source_part_id.to_owned()) {
                        return Err(RuntimeError::InvalidInput(
                            "GEOMETRY_MODIFIER_APPLY_SOURCE_BINDING_DUPLICATE_PART".to_owned(),
                        ));
                    }
                }
                if source_part_ids.len() != inspection.part_bindings.len()
                    || !source_part_ids.contains(plan.source_part_id.as_str())
                {
                    return Err(RuntimeError::InvalidInput(
                        "GEOMETRY_MODIFIER_APPLY_DERIVED_PART_SET_MISMATCH".to_owned(),
                    ));
                }
                let mut derived_target_count = 0usize;
                for derived_binding in &inspection.part_bindings {
                    let source_binding = plan
                        .source_part_bindings
                        .iter()
                        .find(|binding| {
                            binding.get("part_id").and_then(Value::as_str)
                                == Some(derived_binding.part_id.as_str())
                        })
                        .ok_or_else(|| {
                            RuntimeError::InvalidInput(
                                "GEOMETRY_MODIFIER_APPLY_DERIVED_PART_SET_MISMATCH".to_owned(),
                            )
                        })?;
                    let source_material_zone = source_binding
                        .get("material_zone_id")
                        .and_then(Value::as_str);
                    let source_solid = source_binding.get("solid").and_then(Value::as_bool);
                    if derived_binding.part_id == plan.source_part_id {
                        derived_target_count += 1;
                        if derived_binding.source_node_id != plan.derived_terminal_node_id
                            || source_material_zone != Some(plan.source_material_zone_id.as_str())
                            || source_solid != Some(plan.source_solid)
                        {
                            return Err(RuntimeError::InvalidInput(
                                "GEOMETRY_MODIFIER_APPLY_DERIVED_TARGET_BINDING_MISMATCH"
                                    .to_owned(),
                            ));
                        }
                    } else if source_binding.get("source_node_id").and_then(Value::as_str)
                        != Some(derived_binding.source_node_id.as_str())
                        || source_material_zone != Some(derived_binding.material_zone_id.as_str())
                        || source_solid != Some(derived_binding.solid)
                        || source_binding.get("triangle_count").and_then(Value::as_u64)
                            != Some(derived_binding.triangle_count)
                    {
                        return Err(RuntimeError::InvalidInput(
                            "GEOMETRY_MODIFIER_APPLY_NON_TARGET_BINDING_MISMATCH".to_owned(),
                        ));
                    }
                }
                if derived_target_count != 1 {
                    return Err(RuntimeError::InvalidInput(
                        "GEOMETRY_MODIFIER_APPLY_DERIVED_TARGET_BINDING_MISMATCH".to_owned(),
                    ));
                }
            }
            if let Some(plan) = modifier_apply_bevel_v2_plan.as_ref() {
                let source_part_ids = plan
                    .source_part_bindings
                    .iter()
                    .filter_map(|binding| binding.get("part_id").and_then(Value::as_str))
                    .collect::<HashSet<_>>();
                if source_part_ids.len() != plan.source_part_bindings.len()
                    || source_part_ids.len() != inspection.part_bindings.len()
                    || !source_part_ids.contains(plan.source_part_id.as_str())
                {
                    return Err(RuntimeError::InvalidInput(
                        "GEOMETRY_MODIFIER_APPLY_V2_DERIVED_PART_SET_MISMATCH".to_owned(),
                    ));
                }
                let mut derived_target_count = 0usize;
                for derived_binding in &inspection.part_bindings {
                    let source_binding = plan
                        .source_part_bindings
                        .iter()
                        .find(|binding| {
                            binding.get("part_id").and_then(Value::as_str)
                                == Some(derived_binding.part_id.as_str())
                        })
                        .ok_or_else(|| {
                            RuntimeError::InvalidInput(
                                "GEOMETRY_MODIFIER_APPLY_V2_DERIVED_PART_SET_MISMATCH".to_owned(),
                            )
                        })?;
                    let source_material_zone = source_binding
                        .get("material_zone_id")
                        .and_then(Value::as_str);
                    let source_solid = source_binding.get("solid").and_then(Value::as_bool);
                    if derived_binding.part_id == plan.source_part_id {
                        derived_target_count += 1;
                        if derived_binding.source_node_id != plan.derived_terminal_node_id
                            || source_material_zone != Some(plan.source_material_zone_id.as_str())
                            || source_solid != Some(plan.source_solid)
                        {
                            return Err(RuntimeError::InvalidInput(
                                "GEOMETRY_MODIFIER_APPLY_V2_DERIVED_TARGET_BINDING_MISMATCH"
                                    .to_owned(),
                            ));
                        }
                    } else if source_binding.get("source_node_id").and_then(Value::as_str)
                        != Some(derived_binding.source_node_id.as_str())
                        || source_material_zone != Some(derived_binding.material_zone_id.as_str())
                        || source_solid != Some(derived_binding.solid)
                        || source_binding.get("triangle_count").and_then(Value::as_u64)
                            != Some(derived_binding.triangle_count)
                    {
                        return Err(RuntimeError::InvalidInput(
                            "GEOMETRY_MODIFIER_APPLY_V2_NON_TARGET_BINDING_MISMATCH".to_owned(),
                        ));
                    }
                }
                if derived_target_count != 1 {
                    return Err(RuntimeError::InvalidInput(
                        "GEOMETRY_MODIFIER_APPLY_V2_DERIVED_TARGET_BINDING_MISMATCH".to_owned(),
                    ));
                }
            }

            let mut program_draft = program;
            program_draft
                .as_object_mut()
                .expect("GeometryProgram@2 was checked as an object")
                .remove("canonical_sha256");
            let program_bytes = canonical_json_bytes(&program_draft)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
            if program_bytes.is_empty() || program_bytes.len() > MAX_JSON_BYTES {
                return Err(RuntimeError::InvalidInput(
                    "GEOMETRY_REJECTED: canonical GeometryProgram exceeds 1 MiB".to_owned(),
                ));
            }
            if sha256_hex(&program_bytes) != inspection.program_sha256 {
                return Err(RuntimeError::InvalidInput(
                    "GEOMETRY_REJECTED: canonical GeometryProgram hash differs from readback"
                        .to_owned(),
                ));
            }

            let mut created_objects = Vec::<CasObject>::new();
            let materialized = (|| -> Result<(Value, bool), RuntimeError> {
                let glb_object = self.store.put_object_reserved(
                    &cas_reservation,
                    &first.glb,
                    Some(&sha256_hex(&first.glb)),
                    "model/gltf-binary",
                    "geometry-glb",
                    &now_string(),
                )?;
                created_objects.push(glb_object.clone());
                let program_object = self.store.put_object_reserved(
                    &cas_reservation,
                    &program_bytes,
                    Some(&inspection.program_sha256),
                    "application/json",
                    "geometry-program-v2",
                    &now_string(),
                )?;
                created_objects.push(program_object.clone());

                let timestamp = now_string();
                let candidate_id = format!("candidate-{}", Uuid::new_v4().simple());
                let quality_report_id = format!("quality-geometry-{}", Uuid::new_v4().simple());
                let readback = artifact_readback_v2_value(
                    &glb_object.record.sha256,
                    &candidate_id,
                    &inspection,
                    glb_object.record.size_bytes,
                );
                validate_artifact_readback_v2_output(&readback)?;
                let readback_bytes = canonical_json_bytes(&readback)
                    .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
                if readback_bytes.len() > MAX_JSON_BYTES {
                    return Err(RuntimeError::InvalidInput(
                        "GEOMETRY_REJECTED: artifact readback exceeds 1 MiB".to_owned(),
                    ));
                }
                let readback_object = self.store.put_object_reserved(
                    &cas_reservation,
                    &readback_bytes,
                    None,
                    "application/json",
                    "geometry-artifact-readback-v2",
                    &now_string(),
                )?;
                created_objects.push(readback_object.clone());

                let mut quality_report = json!({
                    "schema_version":"GeometryQualityReport@2",
                    "scope":"mcp010b-strict-glb-bin-accessor-hard-gates",
                    "quality_report_id":quality_report_id,
                    "candidate_id":candidate_id,
                    "artifact_sha256":glb_object.record.sha256,
                    "program_sha256":inspection.program_sha256,
                    "operator_catalog_sha256":inspection.operator_catalog_sha256,
                    "readback_config_sha256":inspection.readback_config_sha256,
                    "artifact_readback_object_sha256":readback_object.record.sha256,
                    "integrity":strict_integrity_value(&inspection),
                    "hard_gate_passed":true,
                    "canonical_sha256":""
                });
                quality_report["canonical_sha256"] =
                    Value::String(canonical_json_hash(&quality_report));
                validate_geometry_quality_report_v2_output(&quality_report)?;
                let quality_bytes = canonical_json_bytes(&quality_report)
                    .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
                if quality_bytes.len() > MAX_JSON_BYTES {
                    return Err(RuntimeError::InvalidInput(
                        "GEOMETRY_REJECTED: quality report exceeds 1 MiB".to_owned(),
                    ));
                }
                let quality_object = self.store.put_object_reserved(
                    &cas_reservation,
                    &quality_bytes,
                    None,
                    "application/json",
                    "geometry-quality-report",
                    &now_string(),
                )?;
                created_objects.push(quality_object.clone());
                let mut modifier_apply_result: Option<Value> = None;
                let mut modifier_apply_bevel_v2_result: Option<Value> = None;
                let mut modifier_sidecar_object = if let Some(evaluation) = &modifier_evaluation {
                    let bytes = canonical_json_bytes(evaluation)
                        .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
                    if bytes.is_empty() || bytes.len() > MAX_JSON_BYTES {
                        return Err(RuntimeError::InvalidInput(
                        "GEOMETRY_MODIFIER_APPLY_EVIDENCE_TOO_LARGE: evaluation sidecar exceeds 1 MiB"
                            .to_owned(),
                    ));
                    }
                    let object = self.store.put_object_reserved(
                        &cas_reservation,
                        &bytes,
                        None,
                        "application/json",
                        "geometry-modifier-evaluation-result-v2",
                        &now_string(),
                    )?;
                    created_objects.push(object.clone());
                    Some(object)
                } else {
                    None
                };

                let mut candidate = CandidateRecord {
                    schema_version: "Candidate@1".to_owned(),
                    candidate_id: candidate_id.clone(),
                    project_id: project_id.to_owned(),
                    base_version_id: base_version_id.map(str::to_owned),
                    source_version_id: None,
                    prepared_object_id: Some(format!(
                        "geometry-object-{}",
                        &glb_object.record.sha256[..32]
                    )),
                    prepared_object_sha256: Some(glb_object.record.sha256.clone()),
                    state: "reviewable".to_owned(),
                    request_sha256: request_sha256.clone(),
                    manifest_hash: Some(glb_object.record.sha256.clone()),
                    quality_report_id: Some(quality_report_id.clone()),
                    quality_hard_gate_passed: true,
                    canonical_sha256: String::new(),
                    error_code: None,
                    created_at: timestamp.clone(),
                    updated_at: timestamp.clone(),
                };
                candidate.canonical_sha256 = canonical_json_hash(
                    &serde_json::to_value(&candidate)
                        .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
                );
                let evidence_value = geometry_candidate_evidence_value(
                    &candidate,
                    reference_id.as_deref(),
                    reference_sha256.as_deref(),
                    &inspection,
                    &program_object.record.sha256,
                    &glb_object.record.sha256,
                    &readback_object.record.sha256,
                    &quality_object.record.sha256,
                    &quality_report_id,
                );
                validate_geometry_candidate_evidence_output(&evidence_value)?;
                let evidence: GeometryCandidateEvidenceRecord =
                    serde_json::from_value(evidence_value)
                        .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
                if let Some(plan) = modifier_apply_plan.as_ref() {
                    let apply_result = geometry_modifier_apply_result_value(
                        plan,
                        &candidate,
                        base_version_id,
                        &inspection,
                        &program_object.record.sha256,
                        &glb_object.record.sha256,
                        &readback,
                        &evidence,
                        first.build_cohort_sha256.as_deref(),
                    )?;
                    validate_geometry_modifier_apply_result(&apply_result)?;
                    let bytes = canonical_json_bytes(&apply_result)
                        .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
                    if bytes.is_empty() || bytes.len() > MAX_JSON_BYTES {
                        return Err(RuntimeError::InvalidInput(
                            "GEOMETRY_MODIFIER_APPLY_RESULT_TOO_LARGE: sidecar exceeds 1 MiB"
                                .to_owned(),
                        ));
                    }
                    let object = self.store.put_object_reserved(
                        &cas_reservation,
                        &bytes,
                        None,
                        "application/json",
                        "geometry-modifier-apply-result-v1",
                        &now_string(),
                    )?;
                    created_objects.push(object.clone());
                    modifier_apply_result = Some(apply_result);
                    modifier_sidecar_object = Some(object);
                }
                if let Some(plan) = modifier_apply_bevel_v2_plan.as_ref() {
                    let apply_result = geometry_modifier_apply_bevel_v2_result_value(
                        plan,
                        &candidate,
                        base_version_id,
                        &inspection,
                        &program_object.record.sha256,
                        &glb_object.record.sha256,
                        &readback,
                        &evidence,
                        first.build_cohort_sha256.as_deref(),
                    )?;
                    validate_geometry_modifier_apply_bevel_v2_result(&apply_result)?;
                    let bytes = canonical_json_bytes(&apply_result)
                        .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
                    if bytes.is_empty() || bytes.len() > MAX_JSON_BYTES {
                        return Err(RuntimeError::InvalidInput(
                            "GEOMETRY_MODIFIER_APPLY_V2_RESULT_TOO_LARGE: sidecar exceeds 1 MiB"
                                .to_owned(),
                        ));
                    }
                    let object = self.store.put_object_reserved(
                        &cas_reservation,
                        &bytes,
                        None,
                        "application/json",
                        "geometry-modifier-apply-result-v2",
                        &now_string(),
                    )?;
                    created_objects.push(object.clone());
                    modifier_apply_bevel_v2_result = Some(apply_result);
                    modifier_sidecar_object = Some(object);
                }
                let job_id = format!("job-{}", Uuid::new_v4().simple());
                let job = JobRecord {
                    schema_version: "RuntimeJob@1".to_owned(),
                    job_id: job_id.clone(),
                    project_id: project_id.to_owned(),
                    kind: "geometry_prepare".to_owned(),
                    status: "succeeded".to_owned(),
                    progress: 100,
                    request_sha256: request_sha256.clone(),
                    checkpoint_sha256: None,
                    error_code: None,
                    created_at: timestamp.clone(),
                    updated_at: timestamp.clone(),
                };
                let mut event_payload = json!({
                    "candidate_id":candidate_id,
                    "artifact_sha256":glb_object.record.sha256,
                    "program_sha256":inspection.program_sha256,
                    "worker_build_cohort_sha256":expected_cohort,
                });
                if let (Some(evaluation), Some(evaluation_object)) =
                    (&modifier_evaluation, &modifier_sidecar_object)
                {
                    let payload = event_payload
                        .as_object_mut()
                        .expect("geometry prepared payload is an object");
                    payload.insert(
                        "modifier_evaluation_object_sha256".to_owned(),
                        Value::String(evaluation_object.record.sha256.clone()),
                    );
                    for (payload_key, evaluation_key) in [
                        ("modifier_evaluation_canonical_sha256", "canonical_sha256"),
                        ("modifier_source_input_sha256", "source_input_sha256"),
                        (
                            "modifier_stack_definition_sha256",
                            "stack_definition_sha256",
                        ),
                        ("modifier_evaluation_sha256", "evaluation_sha256"),
                        ("modifier_output_sha256", "output_sha256"),
                        (
                            "modifier_evaluation_policy_sha256",
                            "evaluation_policy_sha256",
                        ),
                        (
                            "modifier_operator_catalog_sha256",
                            "operator_catalog_sha256",
                        ),
                        ("modifier_catalog_cohort_sha256", "catalog_cohort_sha256"),
                        ("modifier_cache_key_sha256", "cache_key_sha256"),
                    ] {
                        payload.insert(
                        payload_key.to_owned(),
                        evaluation.get(evaluation_key).cloned().ok_or_else(|| {
                            RuntimeError::InvalidInput(format!(
                                "GEOMETRY_MODIFIER_APPLY_EVIDENCE_INVALID: evaluation omitted {evaluation_key}"
                            ))
                        })?,
                    );
                    }
                }
                if let (Some(plan), Some(apply_result), Some(sidecar_object)) = (
                    modifier_apply_plan.as_ref(),
                    modifier_apply_result.as_ref(),
                    modifier_sidecar_object.as_ref(),
                ) {
                    let payload = event_payload
                        .as_object_mut()
                        .expect("geometry prepared payload is an object");
                    payload.insert(
                        "modifier_apply_result_object_sha256".to_owned(),
                        Value::String(sidecar_object.record.sha256.clone()),
                    );
                    payload.insert(
                        "modifier_apply_result_canonical_sha256".to_owned(),
                        apply_result
                            .get("canonical_sha256")
                            .cloned()
                            .ok_or_else(|| {
                                RuntimeError::InvalidInput(
                            "GEOMETRY_MODIFIER_APPLY_RESULT_INVALID: canonical hash is unavailable"
                                .to_owned(),
                        )
                            })?,
                    );
                    for (key, value) in [
                    (
                        "modifier_apply_source_candidate_id",
                        Value::String(plan.source_candidate.candidate_id.clone()),
                    ),
                    (
                        "modifier_apply_source_candidate_canonical_sha256",
                        Value::String(plan.source_candidate.canonical_sha256.clone()),
                    ),
                    (
                        "modifier_apply_source_artifact_sha256",
                        Value::String(plan.source_artifact_sha256.clone()),
                    ),
                    (
                        "modifier_apply_source_artifact_readback_sha256",
                        Value::String(plan.source_artifact_readback_sha256.clone()),
                    ),
                    (
                        "modifier_apply_source_geometry_candidate_evidence_sha256",
                        Value::String(plan.source_evidence.canonical_sha256.clone()),
                    ),
                    (
                        "modifier_apply_source_geometry_program_sha256",
                        Value::String(plan.source_geometry_program_sha256.clone()),
                    ),
                    (
                        "modifier_apply_source_operator_catalog_sha256",
                        Value::String(plan.source_operator_catalog_sha256.clone()),
                    ),
                    (
                        "modifier_apply_source_readback_config_sha256",
                        Value::String(plan.source_readback_config_sha256.clone()),
                    ),
                    (
                        "modifier_apply_source_part_id",
                        Value::String(plan.source_part_id.clone()),
                    ),
                    (
                        "modifier_apply_derived_geometry_program_sha256",
                        apply_result
                            .get("derived_geometry_program_sha256")
                            .cloned()
                            .ok_or_else(|| RuntimeError::InvalidInput(
                                "GEOMETRY_MODIFIER_APPLY_RESULT_INVALID: derived program hash is unavailable"
                                    .to_owned(),
                            ))?,
                    ),
                    (
                        "modifier_apply_derived_artifact_sha256",
                        apply_result
                            .get("derived_artifact_sha256")
                            .cloned()
                            .ok_or_else(|| RuntimeError::InvalidInput(
                                "GEOMETRY_MODIFIER_APPLY_RESULT_INVALID: derived artifact hash is unavailable"
                                    .to_owned(),
                            ))?,
                    ),
                    (
                        "modifier_apply_derived_artifact_readback_sha256",
                        apply_result
                            .get("derived_artifact_readback_sha256")
                            .cloned()
                            .ok_or_else(|| RuntimeError::InvalidInput(
                                "GEOMETRY_MODIFIER_APPLY_RESULT_INVALID: derived readback hash is unavailable"
                                    .to_owned(),
                            ))?,
                    ),
                    (
                        "modifier_apply_derived_geometry_candidate_evidence_sha256",
                        apply_result
                            .get("derived_geometry_candidate_evidence_sha256")
                            .cloned()
                            .ok_or_else(|| RuntimeError::InvalidInput(
                                "GEOMETRY_MODIFIER_APPLY_RESULT_INVALID: derived evidence hash is unavailable"
                                    .to_owned(),
                            ))?,
                    ),
                    (
                        "modifier_apply_derived_operator_catalog_sha256",
                        Value::String(
                            inspection
                                .operator_catalog_sha256
                                .clone()
                                .ok_or_else(|| {
                                    RuntimeError::InvalidInput(
                                        "GEOMETRY_MODIFIER_APPLY_RESULT_INVALID: derived operator catalog is unavailable"
                                            .to_owned(),
                                    )
                                })?,
                        ),
                    ),
                    (
                        "modifier_apply_derived_readback_config_sha256",
                        Value::String(inspection.readback_config_sha256.clone()),
                    ),
                ] {
                    payload.insert(key.to_owned(), value);
                }
                }
                if let (Some(plan), Some(apply_result), Some(sidecar_object)) = (
                    modifier_apply_bevel_v2_plan.as_ref(),
                    modifier_apply_bevel_v2_result.as_ref(),
                    modifier_sidecar_object.as_ref(),
                ) {
                    let payload = event_payload
                        .as_object_mut()
                        .expect("geometry prepared payload is an object");
                    payload.insert(
                        "modifier_apply_v2_result_object_sha256".to_owned(),
                        Value::String(sidecar_object.record.sha256.clone()),
                    );
                    // Store's exact geometry transaction validates a generic
                    // modifier-apply sidecar binding. Keep that durable
                    // compatibility key alongside the versioned @2 evidence
                    // keys; the two paths are mutually exclusive.
                    payload.insert(
                        "modifier_apply_result_object_sha256".to_owned(),
                        Value::String(sidecar_object.record.sha256.clone()),
                    );
                    payload.insert(
                        "modifier_apply_result_canonical_sha256".to_owned(),
                        apply_result
                            .get("canonical_sha256")
                            .cloned()
                            .ok_or_else(|| {
                                RuntimeError::InvalidInput(
                                    "GEOMETRY_MODIFIER_APPLY_V2_RESULT_INVALID: canonical hash is unavailable"
                                        .to_owned(),
                                )
                            })?,
                    );
                    // The Store owns the exact source/derived FK and CAS
                    // validation for every candidate-bound modifier apply.
                    // Feed its stable generic binding vocabulary as aliases
                    // of the more explicit versioned @2 evidence fields.
                    for (key, value) in [
                        (
                            "modifier_apply_source_candidate_id",
                            Value::String(plan.source_candidate.candidate_id.clone()),
                        ),
                        (
                            "modifier_apply_source_candidate_canonical_sha256",
                            Value::String(plan.source_candidate.canonical_sha256.clone()),
                        ),
                        (
                            "modifier_apply_source_artifact_sha256",
                            Value::String(plan.source_artifact_sha256.clone()),
                        ),
                        (
                            "modifier_apply_source_artifact_readback_sha256",
                            Value::String(plan.source_artifact_readback_sha256.clone()),
                        ),
                        (
                            "modifier_apply_source_geometry_candidate_evidence_sha256",
                            Value::String(plan.source_evidence.canonical_sha256.clone()),
                        ),
                        (
                            "modifier_apply_source_geometry_program_sha256",
                            Value::String(plan.source_geometry_program_sha256.clone()),
                        ),
                        (
                            "modifier_apply_source_operator_catalog_sha256",
                            Value::String(plan.source_operator_catalog_sha256.clone()),
                        ),
                        (
                            "modifier_apply_source_readback_config_sha256",
                            Value::String(plan.source_readback_config_sha256.clone()),
                        ),
                        (
                            "modifier_apply_source_part_id",
                            Value::String(plan.source_part_id.clone()),
                        ),
                        (
                            "modifier_apply_derived_geometry_program_sha256",
                            apply_result
                                .get("derived_geometry_program_sha256")
                                .cloned()
                                .ok_or_else(|| {
                                    RuntimeError::InvalidInput(
                                        "GEOMETRY_MODIFIER_APPLY_V2_RESULT_INVALID: derived program hash is unavailable"
                                            .to_owned(),
                                    )
                                })?,
                        ),
                        (
                            "modifier_apply_derived_artifact_sha256",
                            apply_result
                                .get("derived_artifact_sha256")
                                .cloned()
                                .ok_or_else(|| {
                                    RuntimeError::InvalidInput(
                                        "GEOMETRY_MODIFIER_APPLY_V2_RESULT_INVALID: derived artifact hash is unavailable"
                                            .to_owned(),
                                    )
                                })?,
                        ),
                        (
                            "modifier_apply_derived_artifact_readback_sha256",
                            apply_result
                                .get("derived_artifact_readback_sha256")
                                .cloned()
                                .ok_or_else(|| {
                                    RuntimeError::InvalidInput(
                                        "GEOMETRY_MODIFIER_APPLY_V2_RESULT_INVALID: derived readback hash is unavailable"
                                            .to_owned(),
                                    )
                                })?,
                        ),
                        (
                            "modifier_apply_derived_geometry_candidate_evidence_sha256",
                            apply_result
                                .get("derived_geometry_candidate_evidence_sha256")
                                .cloned()
                                .ok_or_else(|| {
                                    RuntimeError::InvalidInput(
                                        "GEOMETRY_MODIFIER_APPLY_V2_RESULT_INVALID: derived evidence hash is unavailable"
                                            .to_owned(),
                                    )
                                })?,
                        ),
                        (
                            "modifier_apply_derived_operator_catalog_sha256",
                            Value::String(
                                inspection
                                    .operator_catalog_sha256
                                    .clone()
                                    .ok_or_else(|| {
                                        RuntimeError::InvalidInput(
                                            "GEOMETRY_MODIFIER_APPLY_V2_RESULT_INVALID: derived operator catalog is unavailable"
                                                .to_owned(),
                                        )
                                    })?,
                            ),
                        ),
                        (
                            "modifier_apply_derived_readback_config_sha256",
                            Value::String(inspection.readback_config_sha256.clone()),
                        ),
                    ] {
                        payload.insert(key.to_owned(), value);
                    }
                    payload.insert(
                        "modifier_apply_v2_result_canonical_sha256".to_owned(),
                        apply_result
                            .get("canonical_sha256")
                            .cloned()
                            .ok_or_else(|| {
                                RuntimeError::InvalidInput(
                                    "GEOMETRY_MODIFIER_APPLY_V2_RESULT_INVALID: canonical hash is unavailable"
                                        .to_owned(),
                                )
                            })?,
                    );
                    for (key, value) in [
                        (
                            "modifier_apply_v2_source_candidate_id",
                            Value::String(plan.source_candidate.candidate_id.clone()),
                        ),
                        (
                            "modifier_apply_v2_source_candidate_canonical_sha256",
                            Value::String(plan.source_candidate.canonical_sha256.clone()),
                        ),
                        (
                            "modifier_apply_v2_source_artifact_sha256",
                            Value::String(plan.source_artifact_sha256.clone()),
                        ),
                        (
                            "modifier_apply_v2_source_artifact_readback_sha256",
                            Value::String(plan.source_artifact_readback_sha256.clone()),
                        ),
                        (
                            "modifier_apply_v2_source_geometry_program_sha256",
                            Value::String(plan.source_geometry_program_sha256.clone()),
                        ),
                        (
                            "modifier_apply_v2_source_part_id",
                            Value::String(plan.source_part_id.clone()),
                        ),
                        (
                            "modifier_apply_v2_source_terminal_node_id",
                            Value::String(plan.source_terminal_node_id.clone()),
                        ),
                        (
                            "modifier_apply_v2_source_authoring_topology_sha256",
                            Value::String(plan.source_authoring_topology_sha256.clone()),
                        ),
                        (
                            "modifier_apply_v2_source_edge_id",
                            Value::String(plan.source_edge_id.clone()),
                        ),
                        (
                            "modifier_apply_v2_derived_geometry_program_sha256",
                            apply_result
                                .get("derived_geometry_program_sha256")
                                .cloned()
                                .ok_or_else(|| {
                                    RuntimeError::InvalidInput(
                                        "GEOMETRY_MODIFIER_APPLY_V2_RESULT_INVALID: derived program hash is unavailable"
                                            .to_owned(),
                                    )
                                })?,
                        ),
                        (
                            "modifier_apply_v2_derived_artifact_sha256",
                            apply_result
                                .get("derived_artifact_sha256")
                                .cloned()
                                .ok_or_else(|| {
                                    RuntimeError::InvalidInput(
                                        "GEOMETRY_MODIFIER_APPLY_V2_RESULT_INVALID: derived artifact hash is unavailable"
                                            .to_owned(),
                                    )
                                })?,
                        ),
                        (
                            "modifier_apply_v2_non_target_part_bindings_sha256",
                            apply_result
                                .get("non_target_part_bindings_sha256")
                                .cloned()
                                .ok_or_else(|| {
                                    RuntimeError::InvalidInput(
                                        "GEOMETRY_MODIFIER_APPLY_V2_RESULT_INVALID: non-target binding hash is unavailable"
                                            .to_owned(),
                                    )
                                })?,
                        ),
                    ] {
                        payload.insert(key.to_owned(), value);
                    }
                }
                let event = JobEventRecord {
                    schema_version: "RuntimeJobEvent@1".to_owned(),
                    job_id: job_id.clone(),
                    sequence: 1,
                    kind: "geometry_prepared".to_owned(),
                    payload: event_payload,
                    created_at: timestamp.clone(),
                };
                let audit = forgecad_contracts::AuditEventRecord {
                    schema_version: "AuditEvent@1".to_owned(),
                    audit_id: format!("audit-{}", Uuid::new_v4().simple()),
                    project_id: Some(project_id.to_owned()),
                    kind: "geometry_prepared".to_owned(),
                    object_id: Some(candidate_id.clone()),
                    request_sha256: Some(request_sha256.clone()),
                    payload: event.payload.clone(),
                    created_at: timestamp.clone(),
                };
                let job_summary = JobSummary {
                    job_id: job.job_id.clone(),
                    project_id: job.project_id.clone(),
                    kind: job.kind.clone(),
                    status: job.status.clone(),
                    progress: job.progress,
                    error_code: job.error_code.clone(),
                    created_at: job.created_at.clone(),
                    updated_at: job.updated_at.clone(),
                };
                let result = json!({
                    "schema_version":"GeometryPrepareResult@2",
                    "candidate":candidate,
                    "job":job_summary,
                    "operator_catalog":operator_catalog(),
                    "artifact":readback,
                });
                validate_geometry_prepare_result_v2_output(&result)?;
                let response_json = serde_json::to_string(&result)
                    .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
                if response_json.len() > MAX_JSON_BYTES {
                    return Err(RuntimeError::InvalidInput(
                        "GEOMETRY_PREPARE_RESPONSE_TOO_LARGE: exact response exceeds 1 MiB"
                            .to_owned(),
                    ));
                }
                let stored_response = self.store.commit_geometry_prepare(
                    project_id,
                    current_head_version_id.as_deref(),
                    base_version_id,
                    TOOL,
                    idempotency_key,
                    &request_sha256,
                    &candidate,
                    &job,
                    &event,
                    &audit,
                    &evidence,
                    &response_json,
                    [
                        program_object.record.sha256.as_str(),
                        glb_object.record.sha256.as_str(),
                        readback_object.record.sha256.as_str(),
                        quality_object.record.sha256.as_str(),
                    ],
                    modifier_sidecar_object
                        .as_ref()
                        .map(|object| object.record.sha256.as_str()),
                    true,
                    &timestamp,
                )?;
                let stored: Value = serde_json::from_str(&stored_response).map_err(|error| {
                    RuntimeError::InvalidInput(format!(
                        "GEOMETRY_PREPARE_RESPONSE_INVALID: stored response is invalid: {error}"
                    ))
                })?;
                validate_geometry_prepare_result_v2_output(&stored)?;
                Ok((stored, stored_response != response_json))
            })();

            let release_reservations = |cleanup_temporary: bool| -> Option<RuntimeError> {
                let mut first_error = None;
                for created in created_objects.iter().rev() {
                    if let Err(error) = self.store.release_cas_reservation_object(
                        &cas_reservation,
                        created,
                        cleanup_temporary,
                    ) {
                        if first_error.is_none() {
                            first_error = Some(RuntimeError::Store(error));
                        }
                    }
                }
                first_error
            };
            match materialized {
                Ok((value, cleanup_temporary)) => {
                    // A committed response remains authoritative even if best-
                    // effort cleanup encounters an I/O error; the reservation
                    // Drop below still releases all in-memory ownership tokens.
                    let _ = release_reservations(cleanup_temporary);
                    Ok(value)
                }
                Err(error) => {
                    // Never let cleanup of one CAS object hide the owner error;
                    // every object is still attempted before the flight completes.
                    let _ = release_reservations(true);
                    Err(error)
                }
            }
        })();

        match owner_result {
            Ok(value) => {
                let response_json = serde_json::to_string(&value)
                    .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
                self.store.complete_geometry_prepare_single_flight(
                    &single_flight,
                    GeometryPrepareSingleFlightOutcome::Committed(response_json),
                )?;
                Ok(value)
            }
            Err(error) => {
                let message = error.to_string();
                // Preserve the original owner error for the caller and for
                // waiters; a broken cleanup path must not replace it.
                let _ = self.store.complete_geometry_prepare_single_flight(
                    &single_flight,
                    GeometryPrepareSingleFlightOutcome::Failed(message),
                );
                Err(error)
            }
        }
    }

    /// Compile the same bounded geometry with a hash-bound AppearanceProgram,
    /// store fixed render evidence, and keep the result in the normal
    /// reviewable-candidate transaction. No version is created here.
    pub fn prepare_appearance_candidate(
        &self,
        project_id: &str,
        base_version_id: Option<&str>,
        request: Value,
    ) -> Result<Value, RuntimeError> {
        let object = request.as_object().ok_or_else(|| {
            RuntimeError::InvalidInput("appearance request must be an object".to_owned())
        })?;
        if object.get("typed").and_then(Value::as_str) != Some("appearance") {
            return Err(RuntimeError::InvalidInput(
                "appearance request requires typed=appearance".to_owned(),
            ));
        }
        let geometry_program = object
            .get("geometry_program")
            .ok_or_else(|| RuntimeError::InvalidInput("geometry_program is required".to_owned()))?;
        let appearance_program = object.get("appearance_program").ok_or_else(|| {
            RuntimeError::InvalidInput("appearance_program is required".to_owned())
        })?;
        let geometry_is_v2 = geometry_program
            .get("schema_version")
            .and_then(Value::as_str)
            == Some("GeometryProgram@2");
        let appearance_schema = appearance_program
            .get("schema_version")
            .and_then(Value::as_str);
        let appearance_is_v2 = matches!(
            appearance_schema,
            Some("AppearanceProgram@2" | "AppearanceProgram@3")
        );
        if geometry_is_v2 != appearance_is_v2 {
            return Err(RuntimeError::InvalidInput(
                "APPEARANCE_REJECTED: GeometryProgram@2 must use AppearanceProgram@2/@3 and the legacy V1 pair must remain V1".to_owned(),
            ));
        }
        let artifact =
            compile_geometry_with_runtime_worker(geometry_program, Some(appearance_program))
                .map_err(|error| {
                    RuntimeError::InvalidInput(format!("APPEARANCE_REJECTED: {error}"))
                })?;
        if appearance_is_v2 {
            return self.prepare_appearance_candidate_v2(
                project_id,
                base_version_id,
                request.clone(),
                artifact,
            );
        }
        let inspection = strict_glb_inspection(&artifact.glb)?;
        validate_worker_metadata(&artifact, &inspection)?;
        let hard_gate_passed = physical_geometry_passed(&inspection);
        if !hard_gate_passed {
            return Err(RuntimeError::InvalidInput(format!(
                "APPEARANCE_REJECTED: physical GLB readback failed: {}",
                inspection.failure_codes.join(",")
            )));
        }
        // Rendering remains inside the isolated Worker and runs before any
        // candidate/GLB/render CAS object is persisted. A timeout, crash or
        // malformed response therefore leaves no candidate/version/CAS write.
        let render_passes = render_fixed_with_runtime_worker(geometry_program, appearance_program)
            .map_err(|error| RuntimeError::InvalidInput(format!("RENDER_REJECTED: {error}")))?;
        let glb_object =
            self.put_object(&artifact.glb, None, "model/gltf-binary", "appearance-glb")?;
        let prepared = self.prepare_candidate(
            project_id,
            base_version_id,
            &format!("appearance-object-{}", &glb_object.record.sha256[..32]),
            &glb_object.record.sha256,
            request.clone(),
        )?;
        let mut pass_artifacts = serde_json::Map::new();
        for pass in &render_passes {
            let object = self.put_object(
                &pass.png,
                None,
                "image/png",
                &format!("fixed-render-{}", pass.pass),
            )?;
            pass_artifacts.insert(
                pass.pass.clone(),
                json!({"sha256":object.record.sha256,"mime":"image/png","size_bytes":object.record.size_bytes,"width":pass.width,"height":pass.height}),
            );
        }
        let camera_hash = canonical_json_hash(&json!({
            "projection":"orthographic",
            "azimuth_degrees":28,
            "elevation_degrees":12,
            "resolution":[256,256],
        }));
        let renderer_hash = sha256_hex(b"forgecad-software-fixed-renderer@1");
        let render_set_id = format!("render-set-{}", &glb_object.record.sha256[..32]);
        let mut render_set = json!({
            "schema_version":"RenderSet@1",
            "render_set_id":render_set_id,
            "candidate_id":prepared.candidate.candidate_id,
            "passes":render_passes.iter().map(|pass| pass.pass.clone()).collect::<Vec<_>>(),
            "camera_hash":camera_hash,
            "renderer_hash":renderer_hash,
            "pass_artifacts":pass_artifacts,
            "canonical_sha256":""
        });
        let render_set_hash = canonical_json_hash(&render_set);
        render_set["canonical_sha256"] = Value::String(render_set_hash.clone());
        let render_set_bytes = canonical_json_bytes(&render_set)
            .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
        let render_set_object =
            self.put_object(&render_set_bytes, None, "application/json", "render-set")?;
        let quality_report_id = format!("quality-appearance-{}", &glb_object.record.sha256[..32]);
        let mut quality_report = json!({
            "schema_version":"QualityReport@1",
            "quality_report_id":quality_report_id,
            "candidate_id":prepared.candidate.candidate_id,
            "hard_gate_passed":hard_gate_passed,
            "checks":[
                {"check_id":"uv_in_range","status":if inspection.uv_non_finite_count == 0 && inspection.zero_area_uv_triangle_count == 0 {"passed"} else {"failed"},"message":"UV values are read back from the GLB BIN"},
                {"check_id":"tangent_basis","status":if inspection.tangent_non_finite_count == 0 && inspection.tangent_orthogonality_error_count == 0 && inspection.tangent_handedness_error_count == 0 {"passed"} else {"failed"},"message":"tangent attributes are read back from the GLB BIN"},
                {"check_id":"pbr_material_zones","status":if !inspection.material_zone_ids.is_empty() {"passed"} else {"failed"},"message":"typed material zones are present in GLB lineage"},
                {"check_id":"fixed_render","status":"passed","message":"beauty, silhouette, normal and part-id passes are in CAS"},
                {"check_id":"render_set_object","status":"passed","message":format!("render set {} is CAS-backed", render_set_object.record.sha256)},
            ],
            "canonical_sha256":""
        });
        let quality_hash = canonical_json_hash(&quality_report);
        quality_report["canonical_sha256"] = Value::String(quality_hash);
        let quality_bytes = canonical_json_bytes(&quality_report)
            .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
        let quality_object = self.put_object(
            &quality_bytes,
            None,
            "application/json",
            "appearance-quality-report",
        )?;
        let candidate = self.mark_candidate_quality(
            &prepared.candidate.candidate_id,
            &quality_report_id,
            hard_gate_passed,
        )?;
        let readback = artifact_readback_v1_value(
            &glb_object.record.sha256,
            &candidate.candidate_id,
            &inspection,
            glb_object.record.size_bytes,
        );
        Ok(json!({
            "schema_version":"AppearancePrepareResult@1",
            "candidate":candidate,
            "job":prepared.job,
            "artifact":readback,
            "render_set":render_set,
            "render_set_object_sha256":render_set_object.record.sha256,
            "quality_report_object_sha256":quality_object.record.sha256
        }))
    }

    fn prepare_appearance_candidate_v2(
        &self,
        project_id: &str,
        base_version_id: Option<&str>,
        request: Value,
        artifact: geometry_worker::GeometryArtifact,
    ) -> Result<Value, RuntimeError> {
        let reference_id = request
            .get("reference_id")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "APPEARANCE_V2_REFERENCE_REQUIRED: supply reference_id for RenderSet@2 binding"
                        .to_owned(),
                )
            })?;
        let reference = self.reference(reference_id)?.ok_or_else(|| {
            RuntimeError::InvalidInput("NOT_FOUND: appearance reference not found".to_owned())
        })?;
        if reference.project_id != project_id {
            return Err(RuntimeError::InvalidInput(
                "REFERENCE_SCOPE_DENIED: appearance reference is outside the target project"
                    .to_owned(),
            ));
        }
        let inspection = strict_glb_inspection(&artifact.glb)?;
        validate_worker_metadata(&artifact, &inspection)?;
        let appearance_program = request
            .get("appearance_program")
            .and_then(Value::as_object)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "APPEARANCE_V2_MATERIAL_PACK_REQUIRED: appearance_program is missing"
                        .to_owned(),
                )
            })?;
        let pack_id = appearance_program
            .get("material_pack_id")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "APPEARANCE_V2_MATERIAL_PACK_REQUIRED: material_pack_id is missing".to_owned(),
                )
            })?;
        let requested_manifest_hash = appearance_program
            .get("material_pack_manifest_sha256")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "APPEARANCE_V2_MATERIAL_PACK_REQUIRED: manifest hash is missing".to_owned(),
                )
            })?;
        let manifest = material_pack_manifest_by_id(pack_id).ok_or_else(|| {
            RuntimeError::InvalidInput(
                "APPEARANCE_V2_MATERIAL_PACK_REJECTED: pack is not allowlisted".to_owned(),
            )
        })?;
        let manifest_hash = manifest
            .get("canonical_sha256")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "APPEARANCE_V2_MATERIAL_PACK_REJECTED: manifest hash is missing".to_owned(),
                )
            })?;
        if manifest_hash != requested_manifest_hash {
            return Err(RuntimeError::InvalidInput(
                "APPEARANCE_V2_MATERIAL_PACK_REJECTED: requested manifest hash drifted".to_owned(),
            ));
        }
        validate_glb_material_pack_identity(&artifact.glb, pack_id, manifest_hash)?;
        if !inspection.hard_gate_passed {
            return Err(RuntimeError::InvalidInput(format!(
                "APPEARANCE_REJECTED: physical GLB readback failed: {}",
                inspection.failure_codes.join(",")
            )));
        }
        let glb_object = self.put_object(
            &artifact.glb,
            None,
            "model/gltf-binary",
            "appearance-v2-glb",
        )?;
        let prepared = self.prepare_candidate(
            project_id,
            base_version_id,
            &format!("appearance-v2-object-{}", &glb_object.record.sha256[..32]),
            &glb_object.record.sha256,
            request.clone(),
        )?;
        let readback = artifact_readback_v2_value(
            &glb_object.record.sha256,
            &prepared.candidate.candidate_id,
            &inspection,
            glb_object.record.size_bytes,
        );
        validate_artifact_readback_v2_output(&readback)?;
        let readback_object = self.put_object(
            &canonical_json_bytes(&readback)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            None,
            "application/json",
            "appearance-v2-artifact-readback",
        )?;

        let camera = default_camera_calibration();
        let camera_object = self.put_object(
            &canonical_json_bytes(&camera)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            None,
            "application/json",
            "camera-calibration",
        )?;
        let render_result = render_glb_with_runtime_worker_identity(&artifact.glb, &camera)
            .map_err(|error| RuntimeError::InvalidInput(format!("RENDER_REJECTED: {error}")))?;
        let render_worker_cohort = render_result.build_cohort_sha256.clone();
        let render_profile = render_result.render_profile.clone();
        let render_passes = render_result.passes;
        let mut pass_artifacts = serde_json::Map::new();
        for pass in &render_passes {
            let object = self.put_object(
                &pass.png,
                None,
                "image/png",
                &format!("appearance-v2-render-{}", pass.pass),
            )?;
            let color_space = if pass.pass == "beauty" {
                "srgb"
            } else {
                "data"
            };
            pass_artifacts.insert(
                pass.pass.clone(),
                json!({"sha256":object.record.sha256,"mime":"image/png","size_bytes":object.record.size_bytes,"width":512,"height":512,"channels":"rgba8","color_space":color_space}),
            );
        }
        // RenderSet@2 binds the CameraCalibration identity, not the hash of
        // the already-canonicalized receipt object. Keeping this conversion
        // in one Runtime helper prevents Appearance from drifting from the
        // Primary Form/reference comparison camera contract.
        let camera_hash = camera_identity_hash(&camera)?;
        let renderer_hash = sha256_hex(b"forgecad-renderer-2");
        let mut render_set = json!({
            "schema_version":"RenderSet@2",
            "render_set_id":format!("render-set-v2-{}", &glb_object.record.sha256[..32]),
            "candidate_id":prepared.candidate.candidate_id,
            "artifact_sha256":glb_object.record.sha256,
            "program_sha256":inspection.program_sha256,
            "reference_id":reference_id,
            "camera_hash":camera_hash,
            "camera_object_sha256":camera_object.record.sha256.clone(),
            "renderer_hash":renderer_hash,
            "render_profile":render_profile.clone(),
            "render_profile_sha256":render_profile["canonical_sha256"].clone(),
            "aov_definition_sha256":render_profile["aov_definition_sha256"].clone(),
            "color_pipeline_sha256":render_profile["color_pipeline_sha256"].clone(),
            "id_palette_definition_sha256":render_profile["id_palette_definition_sha256"].clone(),
            "render_worker_build_cohort_sha256":render_worker_cohort.clone(),
            "render_worker_binding_status":render_worker_binding_status(render_worker_cohort.as_ref()),
            "width":512,
            "height":512,
            "passes":render_passes.iter().map(|pass| pass.pass.clone()).collect::<Vec<_>>(),
            "pass_artifacts":pass_artifacts,
            "canonical_sha256":""
        });
        render_set["canonical_sha256"] = Value::String(canonical_json_hash(&render_set));
        validate_render_set_v2_output(&render_set)?;
        let render_set_object = self.put_object(
            &canonical_json_bytes(&render_set)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            None,
            "application/json",
            "appearance-v2-render-set",
        )?;

        let _manifest_object = self.put_object(
            &canonical_json_bytes(&manifest)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            None,
            "application/json",
            "material-pack-manifest",
        )?;
        let receipt = if pack_id == "forgecad-fictional-energy-weapon-2k" {
            let forgecad = glb_forgecad_metadata(&artifact.glb)?;
            let texture_build = forgecad
                .get("texture_build")
                .and_then(Value::as_object)
                .ok_or_else(|| {
                    RuntimeError::InvalidInput(
                        "APPEARANCE_V2_2K_RECEIPT_REJECTED: physical texture build is missing"
                            .to_owned(),
                    )
                })?;
            let source_inputs = manifest
                .get("source_textures")
                .and_then(Value::as_array)
                .ok_or_else(|| {
                    RuntimeError::InvalidInput(
                        "APPEARANCE_V2_2K_RECEIPT_REJECTED: source inventory is missing".to_owned(),
                    )
                })?
                .iter()
                .map(|source| {
                    json!({
                        "texture_id":source["texture_id"],
                        "sha256":source["sha256"],
                        "width":source["width"],
                        "height":source["height"],
                        "mime":"image/png",
                        "semantic":source["semantic"],
                        "color_space":source["color_space"],
                        "normal_convention":source["normal_convention"]
                    })
                })
                .collect::<Vec<_>>();
            json!({
                "schema_version":"TextureBuildReceipt@2",
                "pack_id":pack_id,
                "pack_version":manifest.get("version").and_then(Value::as_str).unwrap_or("1.0.0"),
                "material_pack_manifest_sha256":manifest_hash,
                "recipe_id":texture_build["recipe_id"],
                "algorithm":texture_build["algorithm"],
                "worker_algorithm_sha256":texture_build["worker_algorithm_sha256"],
                "build_budget_ms":texture_build["build_budget_ms"],
                "source_inputs":source_inputs,
                "outputs":texture_build["outputs"],
                "color_management":"baseColor-sRGB-data-maps-linear",
                "normal_convention":"OpenGL+Y",
                "derivation_label":"first-party-deterministic-synthetic-microdetail",
                "bake_status":"not-a-geometry-bake",
                "embedded_only":true,
                "external_uri":false,
                "network_at_runtime":false,
                "canonical_sha256":""
            })
        } else {
            json!({
                "schema_version":"TextureBuildReceipt@1",
                "pack_id":pack_id,
                "pack_version":manifest.get("version").and_then(Value::as_str).unwrap_or("1.0.0"),
                "recipe_id":format!("{pack_id}-512-png@1"),
                "toolchain":"forgecad-geometry-worker embedded offline PNG pack",
                "source_archive_policy":"raw archives remain in the local adoption cache",
                "color_management":"baseColor/emissive sRGB; normal/metallic/roughness/AO linear; OpenGL +Y",
                "external_uri":false,
                "network_at_runtime":false,
                "canonical_sha256":""
            })
        };
        let mut receipt = receipt;
        receipt["canonical_sha256"] = Value::String(canonical_json_hash(&receipt));
        let receipt_object = self.put_object(
            &canonical_json_bytes(&receipt)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            None,
            "application/json",
            "texture-build-receipt",
        )?;
        let quality_id = format!("quality-appearance-v2-{}", &glb_object.record.sha256[..24]);
        let mut quality = json!({
            "schema_version":"QualityReport@2",
            "quality_report_id":quality_id,
            "candidate_id":prepared.candidate.candidate_id,
            "artifact_sha256":glb_object.record.sha256,
            "program_sha256":inspection.program_sha256,
            "reference_id":reference_id,
            "reference_sha256":reference.object_sha256,
            "render_set_hash":render_set_object.record.sha256,
            "comparison_report_hash":sha256_hex(b"reference-comparison-not-run"),
            "human_receipt_hash":Value::Null,
            "structural_status":"passed",
            "visual_status":"not-run",
            "hard_gate_passed":false,
            "threshold_revision":VISIBLE_VIEW_THRESHOLD_REVISION,
            "threshold_policy_sha256":visible_view_threshold_policy_sha256(),
            "threshold_source":VISIBLE_VIEW_THRESHOLD_SOURCE,
            "metric_gate_results":[],
            "limitations":["MCP010E material/UV/PBR structural gate; reference comparison and human visual review are separate MCP010C evidence."],
            "canonical_sha256":""
        });
        quality["canonical_sha256"] = Value::String(canonical_json_hash(&quality));
        validate_quality_report_v2_output(&quality)?;
        let quality_object = self.put_object(
            &canonical_json_bytes(&quality)
                .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
            None,
            "application/json",
            "appearance-v2-quality-report",
        )?;
        let candidate = self.mark_candidate_quality(
            &prepared.candidate.candidate_id,
            quality
                .get("quality_report_id")
                .and_then(Value::as_str)
                .unwrap_or("quality-appearance-v2"),
            true,
        )?;
        let surface_bake_receipt_object = if appearance_program
            .get("schema_version")
            .and_then(Value::as_str)
            == Some("AppearanceProgram@3")
        {
            let forgecad = glb_forgecad_metadata(&artifact.glb)?;
            let surface_bake = forgecad
                .get("surface_bake")
                .and_then(Value::as_object)
                .ok_or_else(|| {
                    RuntimeError::InvalidInput(
                        "APPEARANCE_V3_SURFACE_BAKE_REJECTED: physical surface bake metadata is missing"
                            .to_owned(),
                    )
                })?;
            let image_indices = glb_image_indices(&artifact.glb)?;
            let outputs = surface_bake
                .get("outputs")
                .and_then(Value::as_array)
                .ok_or_else(|| {
                    RuntimeError::InvalidInput(
                        "APPEARANCE_V3_SURFACE_BAKE_REJECTED: output inventory is missing"
                            .to_owned(),
                    )
                })?
                .iter()
                .map(|output| {
                    let texture_id = output
                        .get("texture_id")
                        .and_then(Value::as_str)
                        .ok_or_else(|| {
                            RuntimeError::InvalidInput(
                                "APPEARANCE_V3_SURFACE_BAKE_REJECTED: output ID is missing"
                                    .to_owned(),
                            )
                        })?;
                    let semantic = match output.get("semantic").and_then(Value::as_str) {
                        Some("layered-baseColor") => "baseColor",
                        Some("candidate-surface-normal") => "normal",
                        Some("layered-metallicRoughness") => "metallicRoughness",
                        Some("candidate-self-occlusion") => "ao",
                        Some("zone-clearcoat-factor") => "clearcoat",
                        Some("zone-clearcoat-roughness") => "clearcoatRoughness",
                        _ => {
                            return Err(RuntimeError::InvalidInput(
                                "APPEARANCE_V3_SURFACE_BAKE_REJECTED: output semantic drifted"
                                    .to_owned(),
                            ))
                        }
                    };
                    let image_index = image_indices.get(texture_id).ok_or_else(|| {
                        RuntimeError::InvalidInput(format!(
                            "APPEARANCE_V3_SURFACE_BAKE_REJECTED: output image is missing: {texture_id}"
                        ))
                    })?;
                    Ok(json!({
                        "texture_id":texture_id,
                        "semantic":semantic,
                        "sha256":output["sha256"],
                        "size_bytes":output["size_bytes"],
                        "width":output["width"],
                        "height":output["height"],
                        "mime":output["mime"],
                        "storage":"embedded-glb-bin",
                        "glb_image_index":image_index,
                        "color_space":output["color_space"],
                        "normal_convention":output["normal_convention"]
                    }))
                })
                .collect::<Result<Vec<_>, RuntimeError>>()?;
            let worker_build_cohort_sha256 = artifact
                .build_cohort_sha256
                .clone()
                .or_else(build_cohort_sha256);
            #[cfg(any(test, feature = "test-geometry-worker-fallback"))]
            let worker_build_cohort_sha256 = worker_build_cohort_sha256
                .unwrap_or_else(|| sha256_hex(b"forgecad-source-test-fallback-worker-cohort"));
            #[cfg(not(any(test, feature = "test-geometry-worker-fallback")))]
            let worker_build_cohort_sha256 = worker_build_cohort_sha256.ok_or_else(|| {
                RuntimeError::InvalidInput(
                    "APPEARANCE_V3_SURFACE_BAKE_REJECTED: Geometry Worker cohort is unavailable"
                        .to_owned(),
                )
            })?;
            let appearance_program_sha256 = appearance_program
                .get("canonical_sha256")
                .and_then(Value::as_str)
                .ok_or_else(|| {
                    RuntimeError::InvalidInput(
                        "APPEARANCE_V3_SURFACE_BAKE_REJECTED: appearance hash is missing"
                            .to_owned(),
                    )
                })?;
            let uv_binding_sha256 =
                canonical_json_hash(forgecad.get("uv_atlas").ok_or_else(|| {
                    RuntimeError::InvalidInput(
                        "APPEARANCE_V3_SURFACE_BAKE_REJECTED: UV binding is missing".to_owned(),
                    )
                })?);
            let bake_policy_sha256 = canonical_json_hash(&json!({
                "normal_bake_policy":surface_bake["normal_bake_policy"],
                "ao_bake_policy":surface_bake["ao_bake_policy"],
                "layer_lowering":surface_bake["layer_lowering"],
                "resolution":surface_bake["resolution"],
                "padding_texels":surface_bake["padding_texels"]
            }));
            let lineage_sha256 = canonical_json_hash(&json!({
                "candidate_id":candidate.candidate_id,
                "candidate_canonical_sha256":candidate.canonical_sha256,
                "artifact_sha256":glb_object.record.sha256,
                "artifact_readback_sha256":readback_object.record.sha256,
                "geometry_program_sha256":inspection.program_sha256,
                "appearance_program_sha256":appearance_program_sha256,
                "material_layer_stack_sha256":surface_bake["material_layer_stack_sha256"],
                "outputs":outputs
            }));
            let mut surface_receipt = json!({
                "schema_version":"CandidateSurfaceBakeReceipt@1",
                "bake_id":format!("surface-bake-{}", &glb_object.record.sha256[..24]),
                "project_id":project_id,
                "source_candidate_id":Value::Null,
                "source_candidate_canonical_sha256":Value::Null,
                "candidate_id":candidate.candidate_id,
                "candidate_canonical_sha256":candidate.canonical_sha256,
                "artifact_sha256":glb_object.record.sha256,
                "artifact_readback_sha256":readback_object.record.sha256,
                "geometry_program_sha256":inspection.program_sha256,
                "appearance_program_sha256":appearance_program_sha256,
                "material_pack_id":pack_id,
                "material_pack_manifest_sha256":manifest_hash,
                "input_texture_receipt_sha256":receipt_object.record.sha256,
                "uv_binding_sha256":uv_binding_sha256,
                "material_layer_stack_sha256":surface_bake["material_layer_stack_sha256"],
                "bake_policy_sha256":bake_policy_sha256,
                "worker_algorithm_sha256":surface_bake["worker_algorithm_sha256"],
                "worker_build_cohort_sha256":worker_build_cohort_sha256,
                "budget":{"resolution":2048,"padding_texels":8,"ao_ray_count":8,"max_output_textures":8,"max_output_bytes":67108864,"max_runtime_ms":120000},
                "outputs":outputs,
                "lineage_sha256":lineage_sha256,
                "validator_status":"strict-glb-physical-output-readback-pass",
                "hard_gate_passed":true,
                "materialization_status":"runtime-owned-cas-receipt",
                "runtime_write_performed":true,
                "external_uri":false,
                "network_at_runtime":false,
                "quality_status":"structural-only-quality-not-evaluated",
                "limitations":[
                    "Candidate tangent-space normal is evaluated from the candidate surface and source microdetail; it is not a high-to-low cage bake.",
                    "AO is deterministic candidate self-occlusion from eight fixed hemisphere rays; visual likeness and human review remain not run."
                ],
                "canonical_sha256":""
            });
            surface_receipt["canonical_sha256"] =
                Value::String(canonical_json_hash(&surface_receipt));
            validate_candidate_surface_bake_receipt_output(&surface_receipt)?;
            Some(
                self.put_object(
                    &canonical_json_bytes(&surface_receipt)
                        .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?,
                    None,
                    "application/json",
                    "candidate-surface-bake-receipt",
                )?,
            )
        } else {
            None
        };
        let mut result = json!({
            "schema_version":"AppearancePrepareResult@2",
            "candidate":candidate,
            "job":prepared.job,
            "artifact":readback,
            "render_set":render_set,
            "render_set_object_sha256":render_set_object.record.sha256,
            "quality_report_object_sha256":quality_object.record.sha256,
            "material_pack_manifest_sha256":manifest_hash,
            "texture_build_receipt_sha256":receipt_object.record.sha256
        });
        if let Some(surface_bake_receipt_object) = surface_bake_receipt_object {
            result["schema_version"] = Value::String("AppearancePrepareResult@3".to_owned());
            result["candidate_surface_bake_receipt_sha256"] =
                Value::String(surface_bake_receipt_object.record.sha256);
            validate_appearance_prepare_result_v3_output(&result)?;
        } else {
            validate_appearance_prepare_result_v2_output(&result)?;
        }
        Ok(result)
    }

    /// Prepare one bounded stable-Part edit against the current immutable
    /// version. The edited GeometryProgram/AppearanceProgram are still sent
    /// explicitly by Codex; Runtime only validates the small change envelope,
    /// requires a non-null base version, and reuses the same appearance/render
    /// compiler. This keeps the MVP honest: it records a typed change intent,
    /// but does not pretend to implement a general mesh-delta engine.
    pub fn prepare_change_candidate(
        &self,
        project_id: &str,
        base_version_id: Option<&str>,
        request: Value,
    ) -> Result<Value, RuntimeError> {
        let base_version_id = base_version_id.ok_or_else(|| {
            RuntimeError::InvalidInput(
                "CHANGE_BASE_REQUIRED: change_prepare requires base_version_id".to_owned(),
            )
        })?;
        let object = request.as_object().ok_or_else(|| {
            RuntimeError::InvalidInput("change request must be an object".to_owned())
        })?;
        if object.get("typed").and_then(Value::as_str) != Some("change") {
            return Err(RuntimeError::InvalidInput(
                "change request requires typed=change".to_owned(),
            ));
        }
        let change_set = object
            .get("change_set")
            .ok_or_else(|| RuntimeError::InvalidInput("change_set is required".to_owned()))?;
        let change = change_set
            .as_object()
            .ok_or_else(|| RuntimeError::InvalidInput("change_set must be an object".to_owned()))?;
        let part_id = change
            .get("part_id")
            .and_then(Value::as_str)
            .filter(|value| is_opaque_id(value))
            .ok_or_else(|| {
                RuntimeError::InvalidInput("change_set.part_id is invalid".to_owned())
            })?;
        let operation = change
            .get("operation")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                RuntimeError::InvalidInput("change_set.operation is required".to_owned())
            })?;
        if !matches!(
            operation,
            "transform" | "material_update" | "replace_geometry"
        ) {
            return Err(RuntimeError::InvalidInput(
                "change_set.operation is outside the MVP allowlist".to_owned(),
            ));
        }
        let parameters = change
            .get("parameters")
            .and_then(Value::as_object)
            .ok_or_else(|| {
                RuntimeError::InvalidInput("change_set.parameters must be an object".to_owned())
            })?;
        if parameters.len() > 16
            || change.keys().any(|key| {
                !matches!(
                    key.as_str(),
                    "part_id" | "operation" | "parameters" | "reason"
                )
            })
        {
            return Err(RuntimeError::InvalidInput(
                "change_set contains unsupported or oversized fields".to_owned(),
            ));
        }
        let geometry_program = object.get("geometry_program").ok_or_else(|| {
            RuntimeError::InvalidInput("geometry_program is required for change_prepare".to_owned())
        })?;
        let has_part = geometry_program
            .get("nodes")
            .and_then(Value::as_array)
            .map(|nodes| {
                nodes
                    .iter()
                    .any(|node| node.get("part_id").and_then(Value::as_str) == Some(part_id))
            })
            .unwrap_or(false);
        if !has_part {
            return Err(RuntimeError::InvalidInput(
                "CHANGE_PART_NOT_FOUND: change part_id is absent from the new GeometryProgram"
                    .to_owned(),
            ));
        }
        let appearance_program = object.get("appearance_program").ok_or_else(|| {
            RuntimeError::InvalidInput(
                "appearance_program is required for change_prepare".to_owned(),
            )
        })?;
        let mut appearance_request = object.clone();
        appearance_request.insert("typed".to_owned(), Value::String("appearance".to_owned()));
        appearance_request.insert("geometry_program".to_owned(), geometry_program.clone());
        appearance_request.insert("appearance_program".to_owned(), appearance_program.clone());
        let result = self.prepare_appearance_candidate(
            project_id,
            Some(base_version_id),
            Value::Object(appearance_request),
        )?;
        let mut output = result.as_object().cloned().ok_or_else(|| {
            RuntimeError::InvalidInput("appearance compiler returned an invalid result".to_owned())
        })?;
        output.insert(
            "schema_version".to_owned(),
            Value::String("ChangePrepareResult@1".to_owned()),
        );
        output.insert("change_set".to_owned(), change_set.clone());
        Ok(Value::Object(output))
    }

    pub fn artifact_readback(
        &self,
        artifact_id: &str,
        candidate_id: &str,
    ) -> Result<Value, RuntimeError> {
        self.artifact_readback_bounded(artifact_id, candidate_id, MAX_GEOMETRY_ARTIFACT_BYTES)
    }

    pub(crate) fn artifact_readback_bounded(
        &self,
        artifact_id: &str,
        candidate_id: &str,
        max_bytes: u64,
    ) -> Result<Value, RuntimeError> {
        validate_id(artifact_id)?;
        validate_id(candidate_id)?;
        if !forgecad_contracts::is_sha256(artifact_id) {
            return Err(RuntimeError::InvalidInput(
                "artifact_id must be a GLB SHA-256".to_owned(),
            ));
        }
        self.ensure_candidate_artifact_binding(candidate_id, artifact_id)?;
        let record = self.store.get_object(artifact_id)?.ok_or_else(|| {
            RuntimeError::InvalidInput("artifact readback object is unavailable".to_owned())
        })?;
        if record.mime != "model/gltf-binary"
            || !matches!(
                record.kind.as_str(),
                "geometry-glb" | "appearance-glb" | "appearance-v2-glb"
            )
        {
            return Err(RuntimeError::InvalidInput(
                "artifact is not a ForgeCAD GLB".to_owned(),
            ));
        }
        let bytes = self.cas_read_bounded(artifact_id, max_bytes)?;
        let inspection = strict_glb_inspection(&bytes)?;
        if inspection.artifact_schema_version == "ArtifactReadback@2" {
            if !v2_readback_shape_is_serializable(&inspection) {
                return Err(RuntimeError::InvalidInput(
                    "STRICT_GLB_READBACK_FAILED: V2 artifact lineage or catalog binding is not contract-safe"
                        .to_owned(),
                ));
            }
            Ok(artifact_readback_v2_value(
                artifact_id,
                candidate_id,
                &inspection,
                record.size_bytes,
            ))
        } else {
            Ok(artifact_readback_v1_value(
                artifact_id,
                candidate_id,
                &inspection,
                record.size_bytes,
            ))
        }
    }

    /// Project one bounded semantic Part into explicit vertex/edge/face/corner
    /// topology.  This is a read-only view of the admitted triangulated GLB,
    /// not an authoring cage and not a promise of cross-version element IDs.
    pub fn topology_snapshot(
        &self,
        project_id: &str,
        artifact_id: &str,
        candidate_id: &str,
        part_id: &str,
        artifact_readback_sha256: &str,
        program_sha256: &str,
        operator_catalog_sha256: &str,
        readback_config_sha256: &str,
        snapshot_policy_sha256: &str,
        max_face_count: u64,
    ) -> Result<Value, RuntimeError> {
        validate_id(project_id)?;
        validate_id(artifact_id)?;
        validate_id(candidate_id)?;
        validate_id(part_id)?;
        if [
            artifact_id,
            artifact_readback_sha256,
            program_sha256,
            operator_catalog_sha256,
            readback_config_sha256,
            snapshot_policy_sha256,
        ]
        .into_iter()
        .any(|value| !is_sha256(value))
        {
            return Err(RuntimeError::InvalidInput(
                "TOPOLOGY_SNAPSHOT_BINDING_INVALID: all binding hashes must be SHA-256".to_owned(),
            ));
        }
        if !(1..=512).contains(&max_face_count) {
            return Err(RuntimeError::InvalidInput(
                "TOPOLOGY_SNAPSHOT_BUDGET_INVALID: max_face_count must be 1..512".to_owned(),
            ));
        }
        if sha256_hex(TOPOLOGY_SNAPSHOT_POLICY.as_bytes()) != snapshot_policy_sha256 {
            return Err(RuntimeError::InvalidInput(
                "TOPOLOGY_SNAPSHOT_POLICY_MISMATCH: caller policy hash differs".to_owned(),
            ));
        }
        let candidate = self
            .candidate(candidate_id)?
            .ok_or_else(|| RuntimeError::InvalidInput("TOPOLOGY_CANDIDATE_NOT_FOUND".to_owned()))?;
        if candidate.project_id != project_id {
            return Err(RuntimeError::InvalidInput(
                "TOPOLOGY_PROJECT_SCOPE_DENIED: candidate belongs to another project".to_owned(),
            ));
        }
        let readback = self.artifact_readback(artifact_id, candidate_id)?;
        if readback.get("schema_version").and_then(Value::as_str) != Some("ArtifactReadback@2")
            || readback.get("validator_status").and_then(Value::as_str) != Some("passed")
            || readback.get("hard_gate_passed").and_then(Value::as_bool) != Some(true)
        {
            return Err(RuntimeError::InvalidInput(
                "TOPOLOGY_SNAPSHOT_REQUIRES_V2: strict ArtifactReadback@2 must pass first"
                    .to_owned(),
            ));
        }
        if readback.get("canonical_sha256").and_then(Value::as_str)
            != Some(artifact_readback_sha256)
        {
            return Err(RuntimeError::InvalidInput(
                "TOPOLOGY_SNAPSHOT_READBACK_MISMATCH: expected readback hash differs".to_owned(),
            ));
        }
        for (field, expected) in [
            ("program_sha256", program_sha256),
            ("operator_catalog_sha256", operator_catalog_sha256),
            ("readback_config_sha256", readback_config_sha256),
        ] {
            if readback.get(field).and_then(Value::as_str) != Some(expected) {
                return Err(RuntimeError::InvalidInput(format!(
                    "TOPOLOGY_SNAPSHOT_BINDING_MISMATCH: {field} differs"
                )));
            }
        }
        if !readback
            .get("part_ids")
            .and_then(Value::as_array)
            .is_some_and(|parts| parts.iter().any(|part| part.as_str() == Some(part_id)))
        {
            return Err(RuntimeError::InvalidInput(
                "TOPOLOGY_PART_NOT_FOUND: requested Part is absent from ArtifactReadback@2"
                    .to_owned(),
            ));
        }
        let bytes = self.cas_read_bounded(artifact_id, MAX_GEOMETRY_ARTIFACT_BYTES)?;
        let mesh = integrity::extract_topology_part_mesh(&bytes, part_id, max_face_count as usize)
            .map_err(|error| {
                RuntimeError::InvalidInput(format!("TOPOLOGY_SNAPSHOT_FAILED: {error}"))
            })?;
        let value = topology_snapshot_value(
            artifact_id,
            candidate_id,
            project_id,
            part_id,
            artifact_readback_sha256,
            snapshot_policy_sha256,
            max_face_count,
            &readback,
            &mesh,
        )?;
        let encoded = canonical_json_bytes(&value)
            .map_err(|error| RuntimeError::InvalidInput(error.to_string()))?;
        if encoded.len() > 1024 * 1024 {
            return Err(RuntimeError::InvalidInput(
                "TOPOLOGY_SNAPSHOT_BUDGET_EXCEEDED: canonical response exceeds 1 MiB".to_owned(),
            ));
        }
        validate_topology_snapshot_output(&value)?;
        Ok(value)
    }

