    fn authoring_bevel_v2_source_program(project_id: &str) -> Value {
        let vertex_values = [
            ("v000", [-1.0, -1.0, -1.0]),
            ("v001", [-1.0, -1.0, 1.0]),
            ("v010", [-1.0, 1.0, -1.0]),
            ("v011", [-1.0, 1.0, 1.0]),
            ("v100", [1.0, -1.0, -1.0]),
            ("v101", [1.0, -1.0, 1.0]),
            ("v110", [1.0, 1.0, -1.0]),
            ("v111", [1.0, 1.0, 1.0]),
        ];
        let face_values = [
            ("f-back", ["v000", "v010", "v110", "v100"]),
            ("f-bottom", ["v000", "v100", "v101", "v001"]),
            ("f-front", ["v001", "v101", "v111", "v011"]),
            ("f-left", ["v000", "v001", "v011", "v010"]),
            ("f-right", ["v100", "v110", "v111", "v101"]),
            ("f-top", ["v010", "v011", "v111", "v110"]),
        ];
        let vertices = vertex_values
            .iter()
            .map(
                |(element_id, position_m)| json!({"element_id":element_id,"position_m":position_m}),
            )
            .collect::<Vec<_>>();
        let mut edge_pairs = BTreeSet::new();
        for (_, face_vertices) in &face_values {
            for ordinal in 0..face_vertices.len() {
                let left = face_vertices[ordinal];
                let right = face_vertices[(ordinal + 1) % face_vertices.len()];
                edge_pairs.insert(if left < right {
                    (left, right)
                } else {
                    (right, left)
                });
            }
        }
        let edges = edge_pairs
            .iter()
            .map(|(left, right)| {
                json!({
                    "element_id":format!("e-{left}-{right}"),
                    "vertex_ids":[left,right]
                })
            })
            .collect::<Vec<_>>();
        let mut loops = Vec::new();
        let mut faces = Vec::new();
        for (face_id, face_vertices) in &face_values {
            let mut loop_ids = Vec::new();
            for ordinal in 0..face_vertices.len() {
                let start = face_vertices[ordinal];
                let end = face_vertices[(ordinal + 1) % face_vertices.len()];
                let (left, right) = if start < end {
                    (start, end)
                } else {
                    (end, start)
                };
                let loop_id = format!("l-{face_id}-{ordinal}");
                loops.push(json!({
                    "element_id":loop_id,
                    "face_id":face_id,
                    "ordinal":ordinal,
                    "vertex_id":start,
                    "edge_id":format!("e-{left}-{right}"),
                    "edge_forward":start == left
                }));
                loop_ids.push(json!(format!("l-{face_id}-{ordinal}")));
            }
            faces.push(json!({"element_id":face_id,"loop_ids":loop_ids}));
        }
        let mut program = json!({
            "schema_version":"GeometryProgram@2",
            "project_id":project_id,
            "representation_plan_sha256":"c".repeat(64),
            "operator_catalog_sha256":operator_catalog_sha256(),
            "units":{"length":"meter","angle":"radian","coordinate_system":"right-handed-y-up"},
            "budgets":{"max_nodes":3,"max_triangles":128,"max_glb_bytes":67108864,"max_worker_memory_bytes":536870912,"max_runtime_ms":10000},
            "nodes":[
                {"node_id":"authoring-box","operator_id":"forgecad.geometry.authoring-mesh@1","inputs":[],"parameters":{
                    "shape":"authoring-mesh",
                    "topology_policy":"triangle-quad-manifold-with-boundary@1",
                    "vertices":vertices,
                    "edges":edges,
                    "loops":loops,
                    "faces":faces,
                    "position_m":[0.0,0.0,0.0],
                    "rotation_rad":[0.0,0.0,0.0]
                }},
                {"node_id":"preserved-box","operator_id":"forgecad.geometry.primitive@2","inputs":[],"parameters":{
                    "shape":"box",
                    "size_m":[0.25,0.25,0.25],
                    "position_m":[2.0,0.0,0.0],
                    "rotation_rad":[0.0,0.0,0.0]
                }}
            ],
            "part_outputs":[
                {"part_id":"beveled-part","input_node_ids":["authoring-box"],"material_zone_id":"zone-authored-shell","solid":true},
                {"part_id":"preserved-part","input_node_ids":["preserved-box"],"material_zone_id":"zone-preserved-shell","solid":true}
            ]
        });
        program["canonical_sha256"] = Value::String(canonical_json_hash(&program));
        program
    }

    fn bevel_v2_request(
        runtime: &Runtime,
        project_id: &str,
        source: &Value,
        idempotency_key: &str,
        source_edge_id: &str,
    ) -> Value {
        let source_candidate = &source["candidate"];
        let source_artifact = &source["artifact"];
        let source_candidate_id = source_candidate["candidate_id"]
            .as_str()
            .expect("source candidate id");
        let topology_request = json!({
            "schema_version":"AuthoringTopologyRequest@1",
            "project_id":project_id,
            "candidate_id":source_candidate_id,
            "artifact_id":source_artifact["artifact_id"],
            "artifact_readback_sha256":source_artifact["canonical_sha256"],
            "program_sha256":source_artifact["program_sha256"],
            "operator_catalog_sha256":source_artifact["operator_catalog_sha256"],
            "readback_config_sha256":source_artifact["readback_config_sha256"],
            "authoring_node_id":"authoring-box",
            "part_id":"beveled-part",
            "authoring_topology_policy_sha256":"a6fb36a530e49537673b66d65ecb6e4fb4f51ffb3e7d01a0980be71f28cb367d",
            "max_response_bytes":1048576
        });
        // `AuthoringTopologyRequest@1` has no input hash; the Runtime-owned
        // producer itself is the exact source/topology readback used here.
        let topology =
            authoring_topology::get(runtime, &topology_request).expect("source authoring topology");
        let mut request = json!({
            "schema_version":"GeometryModifierApplyRequest@2",
            "project_id":project_id,
            "source_candidate_id":source_candidate_id,
            "source_candidate_canonical_sha256":source_candidate["canonical_sha256"],
            "source_artifact_sha256":source_candidate["prepared_object_sha256"],
            "source_artifact_readback_sha256":source_artifact["canonical_sha256"],
            "source_geometry_program_sha256":source_artifact["program_sha256"],
            "source_operator_catalog_sha256":source_artifact["operator_catalog_sha256"],
            "source_readback_config_sha256":source_artifact["readback_config_sha256"],
            "source_part_id":"beveled-part",
            "source_terminal_node_id":"authoring-box",
            "source_authoring_topology_sha256":topology["topology_sha256"],
            "source_edge_id":source_edge_id,
            "bevel_m":0.2,
            "segments":3,
            "profile":0.5,
            "clamp_overlap":false,
            "base_version_id":null,
            "idempotency_key":idempotency_key,
            "max_response_bytes":1048576,
            "input_sha256":""
        });
        let mut input_binding = request.clone();
        input_binding
            .as_object_mut()
            .expect("bevel request object")
            .remove("input_sha256");
        request["input_sha256"] = Value::String(canonical_json_hash(&input_binding));
        let apply_sha256 = canonical_json_hash(&request);
        json!({
            "typed":"geometry",
            "modifier_apply_request_v2":request,
            "modifier_apply_request_v2_sha256":apply_sha256
        })
    }

    fn refresh_bevel_v2_request_hashes(request: &mut Value) {
        let nested = request
            .get_mut("modifier_apply_request_v2")
            .expect("bevel v2 nested request");
        let mut input_binding = nested.clone();
        input_binding
            .as_object_mut()
            .expect("bevel v2 request object")
            .remove("input_sha256");
        nested["input_sha256"] = Value::String(canonical_json_hash(&input_binding));
        request["modifier_apply_request_v2_sha256"] = Value::String(canonical_json_hash(nested));
    }

