    /// Build the real Runtime-owned upstream for the animated socket
    /// projection.  This intentionally stops immediately before the
    /// projection under test: every dependency is admitted through its
    /// public Runtime prepare path, so a future particles fixture can reuse
    /// the same materialization, clip, AnchorSet and delivery lineage.
    struct AnimatedSocketDurableFixture {
        root: std::path::PathBuf,
        database: std::path::PathBuf,
        cas: std::path::PathBuf,
        project_id: String,
        candidate_id: String,
        source_artifact_sha256: String,
        animation: Value,
        socket: Value,
        projection_request: Value,
    }

    fn animated_socket_transform_projection_request(
        project_id: &str,
        prepared: &Value,
        delivery: &Value,
        anchor: &Value,
        animation: &Value,
        socket: &Value,
    ) -> Value {
        let candidate_id = prepared["candidate"]["candidate_id"]
            .as_str()
            .expect("animated projection candidate ID");
        let candidate_state_sha256 = prepared["candidate"]["canonical_sha256"]
            .as_str()
            .expect("animated projection candidate state hash");
        let source_artifact_sha256 = prepared["artifact"]["artifact_id"]
            .as_str()
            .expect("animated projection source artifact hash");
        let source_artifact_readback_sha256 = prepared["artifact"]["canonical_sha256"]
            .as_str()
            .expect("animated projection source readback hash");
        let animation_receipt = animation
            .get("receipt")
            .expect("animated projection animation receipt");
        let socket_receipt = socket
            .get("receipt")
            .expect("animated projection socket receipt");
        let socket_roles = json!([
            "weapon-root",
            "grip-primary",
            "muzzle-vfx",
            "magazine-well",
            "sight-primary",
            "energy-core-vfx"
        ]);
        let part_ids = [
            "grip-module",
            "magazine-module",
            "optic-rail",
            "energy-core",
            "barrel-assembly",
        ];
        let part_hierarchy_nodes = part_ids
            .iter()
            .enumerate()
            .map(|(node_index, part_id)| {
                json!({
                    "node_index":node_index,
                    "part_id":part_id,
                    "parent_node_index":-1,
                    "parent_node_name":Value::Null,
                    "children":[]
                })
            })
            .collect::<Vec<_>>();
        let part_hierarchy_sha256 = canonical_json_hash(&json!({
            "schema_version":"GameWeaponAnimatedGlbSocketPartHierarchy@1",
            "policy":"flat-identity-rest-part-hierarchy-only@1",
            "nodes":part_hierarchy_nodes
        }));
        let sample_time_ticks = json!([0_u64, 500, 1000]);
        let frame_scope = "lod0-animation-frame-range-1-16@1";
        let sample_schedule_sha256 = canonical_json_hash(&json!({
            "frame_scope":frame_scope,
            "sample_time_ticks":sample_time_ticks,
            "timebase_hz":1000
        }));
        let mut request = json!({
            "schema_version":"GameWeaponAnimatedGlbSocketTransformProjectionPrepareRequest@1",
            "projection_key_sha256":"",
            "project_id":project_id,
            "candidate_id":candidate_id,
            "candidate_state_sha256":candidate_state_sha256,
            "delivery_manifest_object_sha256":delivery["delivery_manifest_object_sha256"],
            "source_artifact_sha256":source_artifact_sha256,
            "source_artifact_readback_sha256":source_artifact_readback_sha256,
            "animated_artifact_sha256":animation["animated_artifact_sha256"],
            "animated_artifact_readback_sha256":animation_receipt["animation_validation_sha256"],
            "animation_receipt_object_sha256":animation["receipt_object_sha256"],
            "animation_receipt_canonical_sha256":animation_receipt["canonical_sha256"],
            "animated_socket_materialization_key_sha256":socket["animated_socket_materialization_key_sha256"],
            "derived_animated_socket_artifact_sha256":socket["derived_animated_socket_artifact_sha256"],
            "derived_animated_socket_artifact_readback_sha256":socket_receipt["derived_animated_socket_artifact_readback_sha256"],
            "derived_animated_socket_receipt_object_sha256":socket["receipt_object_sha256"],
            "derived_animated_socket_receipt_canonical_sha256":socket_receipt["canonical_sha256"],
            "anchor_set_object_sha256":anchor["anchor_set_object_sha256"],
            "anchor_set_canonical_sha256":anchor["anchor_set"]["canonical_sha256"],
            "animation_clip_id":animation_receipt["clip_id"],
            "animation_clip_object_sha256":animation_receipt["clip_object_sha256"],
            "animation_clip_canonical_sha256":animation_receipt["clip_sha256"],
            "socket_node_id_encoding_sha256":socket_receipt["socket_node_id_encoding_sha256"],
            "socket_node_inventory_sha256":socket_receipt["socket_node_inventory_sha256"],
            "socket_roles_sha256":canonical_json_hash(&socket_roles),
            "socket_roles":socket_roles,
            "part_hierarchy_sha256":part_hierarchy_sha256,
            "part_hierarchy_policy":"flat-identity-rest-part-hierarchy-only@1",
            "transform_representation_policy":"trs-quaternion-no-matrix-no-shear@1",
            "sample_schedule_sha256":sample_schedule_sha256,
            "sample_count":3,
            "sample_time_ticks":sample_time_ticks,
            "frame_scope":frame_scope,
            "timebase_hz":1000,
            "transform_projection_policy":"glb-animation-linear-nlerp-flat-part-hierarchy-composed-world-trs@1",
            "coordinate_system":"forgecad-rh-y-up-m@1",
            "transform_convention":"column-vector-parent-world-times-trs-quaternion-xyzw@1",
            "float_quantization_policy":"f32-round-nearest-canonical-json@1",
            "input_sha256":"",
            "idempotency_key":"animated-socket-transform-projection-fixture"
        });
        let mut preimage = request.clone();
        let object = preimage
            .as_object_mut()
            .expect("animated projection request object");
        object.remove("projection_key_sha256");
        object.remove("input_sha256");
        object.remove("idempotency_key");
        let input_sha256 = canonical_json_hash(&preimage);
        request["projection_key_sha256"] = Value::String(input_sha256.clone());
        request["input_sha256"] = Value::String(input_sha256);
        request
    }

    fn build_animated_socket_durable_fixture() -> (Runtime, AnimatedSocketDurableFixture) {
        let root = std::env::temp_dir().join(format!(
            "forgecad-animated-socket-durable-fixture-{}",
            Uuid::new_v4()
        ));
        fs::create_dir_all(&root).expect("animated socket durable fixture root");
        let database = root.join("runtime.sqlite");
        let cas = root.join("cas");
        let runtime = Runtime::open_with_cas(&database, &cas).expect("animated fixture runtime");
        let project = runtime
            .create_project(
                "fictional animated socket durable fixture",
                json!({"profile":"mvp"}),
            )
            .expect("animated fixture project");
        let prepared = [64_u64, 32, 16]
            .into_iter()
            .map(|segments| {
                runtime
                    .prepare_geometry_candidate(
                        &project.project_id,
                        None,
                        json!({"typed":"geometry","geometry_program":game_weapon_delivery_program(&project.project_id, segments)}),
                    )
                    .expect("animated fixture geometry candidate")
            })
            .collect::<Vec<_>>();
        let prepared: [Value; 3] = prepared.try_into().expect("animated fixture LODs");
        let delivery = runtime
            .game_asset_delivery_prepare(&game_asset_delivery_prepare_request(
                &project.project_id,
                &prepared,
            ))
            .expect("animated fixture delivery");
        let anchor = runtime
            .game_weapon_anchor_prepare(&game_weapon_anchor_request(&project.project_id, &delivery))
            .expect("animated fixture AnchorSet");
        let clip = runtime
            .mechanical_animation_clip_prepare(&game_weapon_animation_clip_prepare_request(
                &project.project_id,
                &prepared[0],
            ))
            .expect("animated fixture animation clip");
        let animation = runtime
            .mechanical_animation_glb_prepare(&game_weapon_animation_glb_prepare_request(
                &project.project_id,
                &prepared[0],
            ))
            .expect("animated fixture animation GLB");
        assert_eq!(clip["clip"]["clip_id"], "weapon-structural-clip");
        let socket_request = game_weapon_animated_glb_socket_request(
            &project.project_id,
            &delivery,
            &anchor,
            &animation,
        );
        let socket = runtime
            .game_weapon_animated_glb_socket_prepare(&socket_request)
            .expect("animated fixture socket materialization");
        let projection_request = animated_socket_transform_projection_request(
            &project.project_id,
            &prepared[0],
            &delivery,
            &anchor,
            &animation,
            &socket,
        );
        let candidate_id = prepared[0]["candidate"]["candidate_id"]
            .as_str()
            .expect("animated fixture candidate ID")
            .to_owned();
        let source_artifact_sha256 = prepared[0]["artifact"]["artifact_id"]
            .as_str()
            .expect("animated fixture source artifact hash")
            .to_owned();
        (
            runtime,
            AnimatedSocketDurableFixture {
                root,
                database,
                cas,
                project_id: project.project_id,
                candidate_id,
                source_artifact_sha256,
                animation,
                socket,
                projection_request,
            },
        )
    }

    fn game_delivery_lod_program(project_id: &str, radial_segments: u64) -> Value {
        let mut program = json!({
            "schema_version":"GeometryProgram@2",
            "project_id":project_id,
            "representation_plan_sha256":"7".repeat(64),
            "operator_catalog_sha256":operator_catalog_sha256(),
            "units":{"length":"meter","angle":"radian","coordinate_system":"right-handed-y-up"},
            "budgets":{"max_nodes":1,"max_triangles":1000,"max_glb_bytes":1048576,"max_worker_memory_bytes":536870912,"max_runtime_ms":10000},
            "nodes":[{
                "node_id":"body-node",
                "operator_id":"forgecad.geometry.primitive@2",
                "inputs":[],
                "parameters":{
                    "shape":"cylinder",
                    "radius_m":0.25,
                    "height_m":1.0,
                    "radial_segments":radial_segments,
                    "position_m":[0.0,0.0,0.0],
                    "rotation_rad":[0.0,0.0,0.0]
                }
            }],
            "part_outputs":[{
                "part_id":"body-part",
                "input_node_ids":["body-node"],
                "material_zone_id":"zone-body",
                "solid":true
            }]
        });
        program["canonical_sha256"] = Value::String(canonical_json_hash(&program));
        program
    }

    fn game_weapon_delivery_program(project_id: &str, radial_segments: u64) -> Value {
        let parts = [
            (
                "grip-module",
                "grip-node",
                "box",
                [-0.25, -0.3, 0.0],
                [0.16, 0.38, 0.16],
            ),
            (
                "magazine-module",
                "magazine-node",
                "box",
                [0.0, -0.24, 0.0],
                [0.18, 0.32, 0.14],
            ),
            (
                "optic-rail",
                "optic-node",
                "box",
                [0.12, 0.25, 0.0],
                [0.28, 0.08, 0.12],
            ),
            (
                "energy-core",
                "energy-node",
                "box",
                [0.16, 0.0, 0.0],
                [0.22, 0.2, 0.18],
            ),
        ];
        let mut nodes = parts
            .iter()
            .map(|(_, node_id, shape, position, size)| json!({
                "node_id":node_id,
                "operator_id":"forgecad.geometry.primitive@2",
                "inputs":[],
                "parameters":{"shape":shape,"size_m":size,"position_m":position,"rotation_rad":[0.0,0.0,0.0]}
            }))
            .collect::<Vec<_>>();
        nodes.push(json!({
            "node_id":"barrel-node",
            "operator_id":"forgecad.geometry.primitive@2",
            "inputs":[],
            "parameters":{"shape":"cylinder","radius_m":0.09,"height_m":0.8,"radial_segments":radial_segments,"position_m":[0.4,0.0,0.0],"rotation_rad":[0.0,0.0,1.5707963267948966]}
        }));
        let mut part_outputs = parts
            .iter()
            .map(|(part_id, node_id, _, _, _)| json!({
                "part_id":part_id,"input_node_ids":[node_id],"material_zone_id":"zone-weapon","solid":true
            }))
            .collect::<Vec<_>>();
        part_outputs.push(json!({"part_id":"barrel-assembly","input_node_ids":["barrel-node"],"material_zone_id":"zone-weapon","solid":true}));
        let mut program = json!({
            "schema_version":"GeometryProgram@2",
            "project_id":project_id,
            "representation_plan_sha256":"8".repeat(64),
            "operator_catalog_sha256":operator_catalog_sha256(),
            "units":{"length":"meter","angle":"radian","coordinate_system":"right-handed-y-up"},
            "budgets":{"max_nodes":5,"max_triangles":2000,"max_glb_bytes":2097152,"max_worker_memory_bytes":536870912,"max_runtime_ms":10000},
            "nodes":nodes,
            "part_outputs":part_outputs
        });
        program["canonical_sha256"] = Value::String(canonical_json_hash(&program));
        program
    }

