    fn prepare_game_weapon_appearance_candidate(
        runtime: &Runtime,
        project_id: &str,
        radial_segments: u64,
    ) -> Value {
        let mut geometry = game_weapon_delivery_program(project_id, radial_segments);
        for output in geometry["part_outputs"]
            .as_array_mut()
            .expect("weapon Part outputs")
        {
            let part_id = output["part_id"].as_str().expect("weapon Part ID");
            output["material_zone_id"] = json!(if part_id == "barrel-assembly" {
                "zone-muzzle-emissive"
            } else if part_id == "energy-core" {
                "zone-core-emissive"
            } else {
                "zone-weapon-dark"
            });
        }
        geometry["budgets"]["max_glb_bytes"] = json!(67_108_864);
        geometry.as_object_mut().unwrap().remove("canonical_sha256");
        geometry["canonical_sha256"] = Value::String(canonical_json_hash(&geometry));
        let appearance = game_weapon_appearance_program(project_id, &geometry);
        let artifact = forgecad_geometry_worker::compile_geometry_program_with_appearance(
            &geometry,
            Some(&appearance),
        )
        .expect("weapon Appearance GLB");
        let object = runtime
            .put_object(
                &artifact.glb,
                None,
                "model/gltf-binary",
                "appearance-v2-glb",
            )
            .expect("weapon Appearance GLB CAS");
        let prepared = runtime
            .prepare_candidate(
                project_id,
                None,
                &format!("appearance-lod-{radial_segments}"),
                &object.record.sha256,
                json!({
                    "typed":"appearance-test-fixture",
                    "geometry_program_sha256":geometry["canonical_sha256"],
                    "appearance_program_sha256":appearance["canonical_sha256"]
                }),
            )
            .expect("weapon Appearance candidate");
        let readback = runtime
            .artifact_readback_bounded(
                &object.record.sha256,
                &prepared.candidate.candidate_id,
                64 * 1024 * 1024,
            )
            .expect("weapon Appearance strict readback");
        json!({"candidate":prepared.candidate,"artifact":readback})
    }

    fn material_quality_geometry_program(project_id: &str, radial_segments: u64) -> Value {
        let lod_scale = match radial_segments {
            64 => 1.0,
            32 => 0.9,
            16 => 0.8,
            _ => panic!("material quality fixture LOD is unsupported"),
        };
        let mut geometry = json!({
            "schema_version":"GeometryProgram@2",
            "project_id":project_id,
            "representation_plan_sha256":sha256_hex(format!("material-quality-box-lod-{radial_segments}").as_bytes()),
            "operator_catalog_sha256":operator_catalog_sha256(),
            "units":{"length":"meter","angle":"radian","coordinate_system":"right-handed-y-up"},
            "budgets":{"max_nodes":1,"max_triangles":1000,"max_glb_bytes":67_108_864,"max_worker_memory_bytes":536_870_912,"max_runtime_ms":10_000},
            "nodes":[{
                "node_id":"body-node",
                "operator_id":"forgecad.geometry.primitive@2",
                "inputs":[],
                "parameters":{
                    "shape":"box",
                    "size_m":[1.2 * lod_scale,0.35,0.25],
                    "position_m":[0.0,0.0,0.0],
                    "rotation_rad":[0.0,0.0,0.0]
                }
            }],
            "part_outputs":[{
                "part_id":"body-part",
                "input_node_ids":["body-node"],
                "material_zone_id":"zone-body",
                "solid":true
            }]
        });
        geometry["canonical_sha256"] = Value::String(canonical_json_hash(&geometry));
        geometry
    }

