    #[test]
    fn geometry_modifier_stack_rejects_duplicate_ids_hash_drift_and_non_unary_operators() {
        let runtime = Runtime::ephemeral().expect("runtime");
        let project = runtime
            .create_project("Modifier stack negative test", json!({"profile":"mvp"}))
            .expect("project");
        let make_request = |operator_id: &str| {
            let mut request = json!({
                "schema_version":"GeometryModifierStackRequest@1",
                "project_id":project.project_id,
                "representation_plan_sha256":"8".repeat(64),
                "part_id":"shell",
                "material_zone_id":"zone-shell",
                "solid":true,
                "base_node":{"node_id":"base","operator_id":"forgecad.geometry.primitive@2","inputs":[],"parameters":{"shape":"box","size_m":[1.0,1.0,1.0],"position_m":[0.0,0.0,0.0],"rotation_rad":[0.0,0.0,0.0]}},
                "modifiers":[
                    {"modifier_id":"same","enabled":true,"operator_id":operator_id,"parameters":{"shape":"transform","translation_m":[0.0,0.0,0.0],"rotation_rad":[0.0,0.0,0.0],"scale":[1.0,1.0,1.0]}},
                    {"modifier_id":"same","enabled":false,"operator_id":"forgecad.geometry.mirror@1","parameters":{"shape":"mirror","axis":"x","offset_m":0.0}}
                ],
                "input_sha256":""
            });
            let mut binding = request.clone();
            binding.as_object_mut().unwrap().remove("input_sha256");
            request["input_sha256"] = Value::String(canonical_json_hash(&binding));
            request
        };
        let duplicate = make_request("forgecad.geometry.transform@2");
        assert!(runtime
            .geometry_program_hash(&duplicate)
            .expect_err("duplicate ids")
            .to_string()
            .contains("modifier_id values must be unique"));
        let mut drifted = duplicate.clone();
        drifted["modifiers"][0]["modifier_id"] = json!("changed");
        assert!(runtime
            .geometry_program_hash(&drifted)
            .expect_err("hash drift")
            .to_string()
            .contains("INPUT_HASH_MISMATCH"));
        let non_unary = make_request("forgecad.geometry.boolean@1");
        assert!(runtime
            .geometry_program_hash(&non_unary)
            .expect_err("boolean is not a unary modifier")
            .to_string()
            .contains("only active unary modifiers are allowed"));
        let mut node_collision = duplicate;
        node_collision["modifiers"][1]["modifier_id"] = json!("other");
        node_collision["base_node"]["node_id"] = json!("modifier-effective-0");
        let mut binding = node_collision.clone();
        binding.as_object_mut().unwrap().remove("input_sha256");
        node_collision["input_sha256"] = Value::String(canonical_json_hash(&binding));
        assert!(runtime
            .geometry_program_hash(&node_collision)
            .expect_err("generated node id collision")
            .to_string()
            .contains("GEOMETRY_MODIFIER_STACK_REJECTED"));
    }

